def build_changelog(limit: int = 2) -> str:
    """Собирает сообщение об обновлении.

    Показываются последние `limit` выпусков: полный список за всю историю
    в одном сообщении не читается и упирается в ограничение Telegram.
    """
    backend = "PostgreSQL" if not config.is_sqlite() else "SQLite"
    parts = [
        f"🚀 <b>Система «Радар» v{config.VERSION}</b>",
        f"<i>База данных: {backend}</i>",
        "",
    ]
    for index, (version, items) in enumerate(RELEASES[:limit]):
        if index:
            parts.append("")
            parts.append(f"<b>Ранее, в версии {version}:</b>")
        parts.extend(items)

    if len(RELEASES) > limit:
        parts.append("")
        parts.append("<i>Полная история изменений — в репозитории проекта.</i>")
    return "\n".join(parts)


async def announce() -> None:
    """Рассылает changelog один раз на версию, а не при каждом рестарте."""
    marker = await storage.meta_get("announced_version") or {}
    if marker.get("value") == config.VERSION:
        return
    await storage.meta_set("announced_version", {"value": config.VERSION})
    for uid, user in list(storage.users().items()):
        if roles.is_moderator(user.get("role")):
            await send_html(uid, build_changelog())
            await asyncio.sleep(0.2)


async def setup_commands() -> None:
    """Список команд в синей кнопке меню Telegram."""
    from aiogram.types import BotCommand

    commands = [
        BotCommand(command="menu", description="Главное меню"),
        BotCommand(command="partner", description="Партнёрский проект"),
        BotCommand(command="panel", description="Веб-панель"),
        BotCommand(command="digest", description="Новостные подборки"),
        BotCommand(command="help", description="Справка"),
        BotCommand(command="id", description="Мой ID и роль"),
        BotCommand(command="cancel", description="Отменить ввод"),
    ]
    try:
        await bot.set_my_commands(commands)
    except Exception:  # noqa: BLE001
        log.warning("Не удалось установить меню команд", exc_info=True)


# --------------------------------------------------------------------------
#  Надзор за фоновыми задачами (с 4.9.8.14)
# --------------------------------------------------------------------------
#
# Задачи создавались через `create_task` и на этом забывались. Две беды
# сразу: ссылку на задачу никто не держал (asyncio хранит только слабую,
# и сборщик мусора вправе убрать задачу, ждущую ввода-вывода), а её
# исключение никто не доставал — оно тонуло вместе с задачей.
#
# Для мониторинга это означало худшее: цикл умирал, бот продолжал отвечать
# на команды, тревоги прекращались молча. Единственным следом была строка
# в журнале, которую никто не читает, пока всё «работает».

_background: set[asyncio.Task] = set()

# Как часто сторож проверяет признаки жизни цикла и сколько раз поднимает
# его заново, прежде чем признать положение безнадёжным.
WATCHDOG_INTERVAL = 60.0
WATCHDOG_REVIVALS = 3

_monitor_task: asyncio.Task | None = None


# Задачи, которые обязаны работать до самой остановки. Их тихое завершение
# — уже событие: мониторинг, переставший крутиться, означает бота без
# оповещений. Разовым задачам (разослать changelog, поднять сервер панели)
# завершиться, наоборот, положено.
_FOREVER = {"monitor", "watchdog", "max"}


def _task_finished(task: asyncio.Task) -> None:
    """Достаёт исключение завершившейся задачи и пишет о нём в журнал."""
    _background.discard(task)
    if task.cancelled():
        return
    name = task.get_name()
    error = task.exception()
    if error is None:
        if name in _FOREVER:
            log.critical("Фоновая задача «%s» завершилась сама", name)
        else:
            log.debug("Фоновая задача «%s» выполнена", name)
        return
    log.critical("Фоновая задача «%s» упала", name, exc_info=error)


def spawn(coro, name: str) -> asyncio.Task:
    """Фоновая задача со ссылкой и разбором исключения.

    Ссылка обязательна: asyncio держит на задачу только слабую, и задача,
    которую больше никто не помнит, может быть убрана сборщиком мусора
    прямо посреди ожидания.
    """
    task = asyncio.create_task(coro, name=name)
    _background.add(task)
    task.add_done_callback(_task_finished)
    return task


async def notify_admins(text: str) -> None:
    """Письмо администраторам. Молчит, если писать некому или некуда."""
    for uid, user in list(storage.users().items()):
        if not roles.is_admin(user.get("role")) or user.get("blocked"):
            continue
        try:
            await send_html(uid, text)
        except Exception:  # noqa: BLE001
            log.warning("Сообщение сторожа не доставлено: %s", uid)


async def watchdog() -> None:
    """Следит, что фоновый цикл жив, и поднимает его, если нет.

    Бот, который отвечает на команды, но не шлёт тревог, снаружи выглядит
    исправным — и Docker его не перезапустит: процесс-то живой. Поэтому
    сторож живёт внутри и, исчерпав попытки поднять цикл, останавливает
    процесс сам: `restart: unless-stopped` поднимет контейнер заново,
    и это честнее, чем тихо работать без оповещений.
    """
    global _monitor_task

    revivals = 0
    while True:
        await asyncio.sleep(WATCHDOG_INTERVAL)

        task = _monitor_task
        ok, silent_for = monitor.alive()
        if task is not None and not task.done() and ok:
            revivals = 0
            continue

        reason = (
            "задача мониторинга завершилась"
            if task is None or task.done()
            else f"цикл молчит {silent_for} с при пределе {monitor.silence_limit()} с"
        )
        revivals += 1
        log.critical("Сторож: %s (попытка %d)", reason, revivals)

        if revivals > WATCHDOG_REVIVALS:
            log.critical(
                "Сторож: цикл не поднимается после %d попыток — "
                "останавливаю процесс, контейнер запустится заново",
                WATCHDOG_REVIVALS,
            )
            await notify_admins(
                "🚨 <b>Мониторинг не поднимается</b>\n\n"
                "Фоновый цикл не удалось восстановить — перезапускаю бота. "
                "Если сообщение повторится, смотрите журнал."
            )
            os.kill(os.getpid(), signal.SIGTERM)
            return

        await notify_admins(
            "⚠️ <b>Мониторинг перезапущен сторожем</b>\n\n"
            f"Причина: {reason}. Оповещения возобновятся в ближайшем цикле."
        )

        if task is not None and not task.done():
            task.cancel()
            try:
                await task
            except (asyncio.CancelledError, Exception):  # noqa: BLE001
                pass

        monitor.mark_alive()
        _monitor_task = spawn(monitor.run(), "monitor")


async def prepare_database() -> None:
    """Готовит базу: ждёт готовности, создаёт схему, переносит старые данные."""
    await db_engine.wait_ready()

    log.info("Проверяю схему базы")
    created, tables, repaired = await db_engine.ensure_schema()
    await db_engine.stamp_alembic()
    if repaired:
        log.warning("Схема была несовместима и пересоздана (%d таблиц)", tables)
    elif created:
        log.info("Схема базы создана (%d таблиц)", tables)
    else:
        log.info("Схема базы актуальна (%d таблиц)", tables)
    if await importer.is_empty() and importer.legacy_present():
        # Импортёр db.json удалён в 4.6.1. Молча стартовать с пустой базой
        # нельзя: человек решит, что данные потеряны, а они лежат рядом.
        log.error(
            "Рядом лежит data/db.json от версии 3.x, но перенос из него "
            "прекращён с 4.6.1. Обновитесь сначала до 4.6.0 — она перенесёт "
            "данные, — и только потом на эту версию. Подробности в README, "
            "раздел «Обновление с прежних версий»."
        )
    await storage.load()
    features.apply(await repo.load_features())
    # Чаты со своей ссылкой — для кнопки «💬 Наши чаты» в меню
    # (с 4.9.9.2). Меню синхронное и в базу само не ходит.
    from radar import chatlink

    published = await chatlink.refresh_published()
    if published:
        log.info("Чатов в меню пользователей: %d", published)
    active = sum(1 for flag in features.FLAGS if features.enabled(flag.key))
    log.info("Возможностей включено: %d из %d", active, len(features.FLAGS))
    logstore.ensure_directory()
    stale_logs = logstore.purge_old()
    if stale_logs:
        log.info("Удалено устаревших журналов: %d", stale_logs)

    removed = await repo.purge_old_events()
    if removed:
        log.info("Удалено устаревших событий: %d", removed)


async def main() -> None:
    await prepare_database()

    dp.message.outer_middleware(AccessMiddleware())
    dp.callback_query.outer_middleware(AccessMiddleware())
    handlers.setup(dp)

    log.info(
        "Запуск «Радар» v%s | ИИ: %s | TZ: %s | опрос каждые %d с",
        config.VERSION,
        config.GEMINI_MODEL if config.AI_ENABLED else "выключен (эвристика)",
        os.getenv("TZ", "system"),
        config.POLL_INTERVAL,
    )

    if ai.ENABLED:
        await ai.discover_models()
        log.info(
            "Модели: ассистент «%s», анализ «%s»",
            ai.current_model(ai.ASSISTANT), ai.current_model(ai.ANALYSIS),
        )

    await setup_commands()

    global _monitor_task
    _monitor_task = spawn(monitor.run(), "monitor")
    # Сторож поднимается вместе с циклом: без него смерть задачи
    # мониторинга остаётся незамеченной до первой ненаступившей тревоги.
    spawn(watchdog(), "watchdog")

    # Веб-панель — отдельная задача: её сбой не должен касаться оповещений
    panel_started = False
    if features.enabled("web_panel"):
        from radar.web import run as run_panel

        spawn(run_panel(), "web-panel")
        panel_started = True
    spawn(announce(), "announce")

    # Канал управления для командной строки (5.9.3): без него radarctl
    # менял бы только базу, а бот держит всё в памяти и затирал бы правки.
    from radar import adminsock

    spawn(adminsock.serve(), "admin-socket")

    # Тайм-аут капчи в группах (5.9.4): задача живёт всегда и сама молчит,
    # пока возможность «captcha_kick» выключена.
    from radar.handlers import group as group_handlers

    spawn(group_handlers.captcha_sweeper(bot), "captcha-sweeper")

    # Адаптер MAX. Пакет radar/platforms/ существовал с 4.4 и не
    # импортировался ни одним модулем — флаг «Мессенджер MAX» значился
    # в списке возможностей и не мог ничего включить.
    #
    # Запускается отдельной задачей и только по флагу: реализация
    # не проверялась на живом сервере, и она не должна мешать Telegram,
    # если MAX ответит не тем, чего мы ждём.
    if features.enabled("platform_max"):
        from radar.platforms.max import MaxTransport

        max_transport = MaxTransport()
        if max_transport.configured:
            spawn(max_transport.start(), "max")
            # Копии тревог привязанным (5.6). Импорт здесь: блок ВК ниже
            # импортирует mirror ещё раз, это дёшево и не зависит от порядка.
            from radar import mirror as max_mirror

            max_mirror.register("max", max_transport.send_text)
            log.info("Адаптер MAX запущен")
        else:
            log.warning(
                "Мессенджер MAX включён флагом, но MAX_BOT_TOKEN пуст — "
                "адаптер не запускается"
            )

    # ВКонтакте как мессенджер (5.6): привязка к Telegram и копии тревог.
    from radar import mirror

    if features.enabled("platform_vk"):
        from radar import secrets as vk_secrets
        from radar.platforms import vkbot
        from radar.platforms.vk import VkTransport

        vk_transport = VkTransport(vk_secrets.get("VK_BOT_TOKEN"),
                                   vk_secrets.get("VK_BOT_GROUP_ID"), vkbot.reply)
        if vk_transport.configured:
            mirror.register("vk", vk_transport.send_text)
            spawn(vk_transport.start(), "vk")
            log.info("Адаптер ВКонтакте запущен")
        else:
            log.warning("ВКонтакте включён флагом, но VK_BOT_TOKEN или "
                        "VK_BOT_GROUP_ID не заданы — адаптер не запускается")

    # Discord (с 5.5): канал сообщества — сводки и статус, не оповещения.
    # Своя задача, как у MAX: сбой Discord не касается Telegram и тревог.
    if features.enabled("platform_discord"):
        from radar import secrets as secrets_module
        from radar.platforms import discordbot
        from radar.platforms.discord import DiscordTransport

        # Намерение Server Members запрашивается, только когда включена
        # проверка участников: оно привилегированное и без нужды не берётся.
        discord_transport = DiscordTransport(
            secrets_module.get("DISCORD_BOT_TOKEN"), discordbot.reply,
            member_events=discordbot.verify_enabled())
        if discord_transport.configured:
            spawn(discordbot.run(discord_transport), "discord")
            log.info("Адаптер Discord запущен")
        else:
            log.warning("Discord включён флагом, но DISCORD_BOT_TOKEN пуст — "
                        "адаптер не запускается")

    # Кто писал, пока бот был выключен. Спрашиваем ДО сброса очереди:
    # delete_webhook(drop_pending_updates=True) стирает её без следа,
    # и человек, написавший во время обновления, не получает ответа никогда.
    # Сами обновления не обрабатываются — только адресаты (см. restartnotice).
    if features.enabled("restart_notice"):
        from radar import i18n, restartnotice

        try:
            await restartnotice.notify(
                bot,
                storage.users(),
                send_html,
                i18n.language_of,
                lambda lang: i18n.t(
                    "restart.missed", lang,
                    "🛠 <b>Бот был на технических работах</b>\n\n"
                    "Ваше сообщение пришло во время перезапуска и не было "
                    "обработано — пришлите его ещё раз.\n\n"
                    "<i>Оповещения об опасности не потеряны: после "
                    "перезапуска бот перечитывает источники заново.</i>",
                ),
            )
        except Exception:  # noqa: BLE001
            # Вежливость не должна мешать запуску: бот обязан подняться.
            log.exception("Уведомление о технических работах не разослано")

    try:
        await bot.delete_webhook(drop_pending_updates=True)
        await dp.start_polling(bot, allowed_updates=dp.resolve_used_update_types())
    finally:
        # Гасим всё, что запускали, и дожидаемся отмены. Раньше панель
        # только «отменялась»: её задача к этому моменту давно завершена
        # (run() возвращается сразу после старта сервера), и отмена
        # не делала ничего — порт освобождался лишь выходом процесса.
        for task in list(_background):
            task.cancel()
        for task in list(_background):
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception:  # noqa: BLE001
                log.debug("Задача «%s» завершилась с ошибкой", task.get_name())

        if panel_started:
            from radar.web import shutdown as panel_shutdown

            await panel_shutdown()
        await bot.session.close()
        await db_engine.dispose()
        log.info("Остановлено")


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except (KeyboardInterrupt, SystemExit):
        pass
    except db_engine.AuthenticationError:
        # Причина уже подробно объяснена в логе — трассировка тут лишний шум.
        raise SystemExit(1)
    except Exception:  # noqa: BLE001
        # Без этого контейнер уходит в бесконечный цикл рестартов, а причина
        # теряется среди одинаковых трейсбеков.
        log.critical("Критический сбой при запуске", exc_info=True)
        log.critical(
            "Проверьте .env (DB_PASSWORD без символа $), доступность базы "
            "и логи radar_db: docker logs --tail 40 radar_db"
        )
        raise SystemExit(1)
