from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Iterable, Sequence

from .textutils import (
    cluster_locations,
    district_matches,
    esc,
    esc_attr,
    house_in_range,
    normalize_city,
    same_city,
    street_matches,
)

# Ключи категорий совпадают с настройками пользователя из версий 2.x —
# это сохраняет совместимость с продакшен-базой.
CATEGORY_TITLES = {
    "bpla": "БПЛА / ракетная опасность",
    "mchs": "Экстренные оповещения МЧС",
    "jkh": "ЖКХ и аварии на сетях",
    "whitelist": "Предупреждать о «белых списках»",
}

CATEGORY_ICONS = {"bpla": "🛸", "mchs": "🆘", "jkh": "🛠", "whitelist": "📶"}

# Военные угрозы объявляются на весь город, независимо от указанных улиц.
CITY_WIDE_ALWAYS = {"bpla"}
# Связь и «белые списки» обычно вводятся на город/регион целиком.
CITY_WIDE_DEFAULT = {"whitelist"}

SEVERITY_ICONS = {"critical": "🔴", "warning": "🟠", "info": "🔵"}

# О «белых списках» в городских пабликах почти не пишут — операторы вводят их
# молча. Поэтому предупреждение выдаётся не по новости, а автоматически:
# объявлена угроза БПЛА или ракетная опасность → значит связь, скорее всего,
# уже ограничена.
ALL_CLEAR_NOTICE = (
    "📶 <b>Мобильный интернет</b>\n"
    "«Белые списки» могут быть отключены в ближайшее время — связь обычно "
    "восстанавливают не сразу после отбоя, а в течение нескольких часов."
)

WHITELIST_NOTICE = (
    "📵 <b>Мобильный интернет</b>\n"
    "При угрозе с воздуха операторы включают «белые списки»: работают только "
    "госуслуги, банки, карты и такси. Мессенджеры и соцсети могут не открываться.\n"
    "Домашний проводной интернет и Wi-Fi обычно продолжают работать. "
    "Для срочной связи — звонки и SMS."
)

@dataclass
class Analysis:
    """Результат разбора одного сообщения источника."""

    relevant: bool = False
    # Идентификатор записи в журнале. Проставляется после сохранения
    # события и нужен рассылке, чтобы отметить доставку. В сравнении
    # не участвует: два одинаковых по смыслу разбора не должны
    # считаться разными только из-за номера строки в базе.
    event_id: int | None = field(default=None, compare=False)
    categories: list[str] = field(default_factory=list)
    severity: str = "info"
    scope: str = "city"  # region | city | district | street
    region: str = ""
    city: str = ""
    districts: list[str] = field(default_factory=list)
    streets: list[dict[str, Any]] = field(default_factory=list)  # {"street": str, "houses": [str]}
    summary: str = ""
    source: str = ""
    raw: str = ""
    link: str = ""            # ссылка на новость (для RSS)
    all_clear: bool = False   # отбой ранее объявленной опасности
    historical: bool = False  # событие в прошлом: сводка, а не тревога
    # Памятка, а не событие (с 4.9.9.2): инструкция о действиях при
    # аварии, номера экстренных служб. Пересылается целиком и спокойно,
    # без «опасности» в заголовке — тревогой она не является.
    guidance: bool = False
    engine: str = "ai"  # ai | heuristic

    @classmethod
    def from_payload(
        cls, payload: dict[str, Any], *, source: str, raw: str, link: str = ""
    ) -> "Analysis":
        streets: list[dict[str, Any]] = []
        for item in payload.get("streets") or []:
            if isinstance(item, str):
                streets.append({"street": item, "houses": []})
            elif isinstance(item, dict) and item.get("street"):
                houses = item.get("houses") or []
                streets.append(
                    {
                        "street": str(item["street"]),
                        "houses": [str(h) for h in houses if str(h).strip()],
                    }
                )
        categories = [c for c in (payload.get("categories") or []) if c in CATEGORY_TITLES]
        severity = str(payload.get("severity") or "info").lower()
        scope = str(payload.get("scope") or "city").lower()
        return refine(cls(
            relevant=bool(payload.get("relevant")) and bool(categories),
            categories=categories,
            severity=severity if severity in SEVERITY_ICONS else "info",
            scope=scope if scope in {"region", "city", "district", "street"} else "city",
            region=str(payload.get("region") or "").strip(),
            city=str(payload.get("city") or "").strip(),
            districts=[str(d) for d in (payload.get("districts") or []) if str(d).strip()],
            streets=streets,
            summary=str(payload.get("summary") or "").strip(),
            source=source,
            raw=raw,
            link=link,
            all_clear=bool(payload.get("all_clear")),
            historical=bool(payload.get("historical")),
            guidance=bool(payload.get("guidance")),
        ))

    @property
    def is_city_wide(self) -> bool:
        """Оповещение действует на весь город (военная угроза, связь, общегородская ЧС)."""
        cats = set(self.categories)
        if cats & CITY_WIDE_ALWAYS:
            return True
        if cats & CITY_WIDE_DEFAULT and not self.streets:
            return True
        if "jkh" in cats:
            return False
        # МЧС и прочее: адресное, только если названы конкретные улицы
        return not self.streets

    @property
    def icon(self) -> str:
        for key in ("bpla", "mchs", "jkh", "whitelist"):
            if key in self.categories:
                return CATEGORY_ICONS[key]
        return "ℹ️"

    def title(self) -> str:
        names = [CATEGORY_TITLES[c] for c in self.categories if c in CATEGORY_TITLES]
        return " / ".join(names) or "Событие"

    def text(self) -> str:
        return self.summary or self.raw[:300]


# --------------------------------------------------------------------------
#  Эвристический разбор (работает без Gemini)
# --------------------------------------------------------------------------

_HEURISTICS: list[tuple[str, re.Pattern]] = [
    ("bpla", re.compile(
        r"бпла|беспилотн|дрон|воздушн\w* тревог|ракетн\w* опасн|работа\w* пво|"
        r"противовоздушн|обломк\w* бпла|угроз\w* атаки", re.I)),
    ("mchs", re.compile(
        r"мчс|штормов\w* предупрежд|чрезвычайн\w* ситуац|эвакуац|крупн\w* пожар|"
        r"экстренн\w* оповещ|режим повышенной готовности|паводок|подтоплен", re.I)),
    ("jkh", re.compile(
        r"отключ\w*\s+(?:воды|холодн|горяч|электро|света|газ|отоплен)|"
        r"без воды|без света|без газа|без отоплен|прекращ\w* подач|"
        r"аварий\w*\s+(?:работ|отключ|ситуац)|порыв|утечк\w* газа|"
        r"ремонтн\w* работ|коммунальн\w* авар|обесточ", re.I)),
    ("whitelist", re.compile(
        r"бел\w* список|ограничен\w* мобильн\w* интернет|мобильн\w* интернет"
        r"|перебо\w* (?:со )?связ|ограничен\w* связи", re.I)),
]

# Признаки того, что событие уже произошло и завершилось: такие сообщения
# нужны как сводка, но поднимать по ним тревогу поздно и вредно —
# пользователь перестаёт доверять сигналам.
#
# Причастия («сбит», «уничтожен», «отражён» и т. д.) ловятся и без «был»
# рядом — сводки МЧС и Минобороны обычно пишут «БПЛА уничтожен», а не
# «был уничтожен». Но краткая форма причастия неотличима по буквам от
# действия, которое ещё не завершилось или не случилось: «не уничтожен»,
# «будет уничтожен» — поэтому такие случаи явно исключены. «\bне »/«\bбудет »/
# «\bбудут » — с границей слова, иначе слово вроде «районе» (…районЕ
# уничтожен) ложно опознаётся как «не» перед глаголом.
HISTORICAL_RE = re.compile(
    r"\bвчера\b|\bпозавчера\b|\bнакануне\b|на прошл\w+ (?:недел|выходн)|"
    r"\bв ночь на\b|минувш\w+ (?:ноч|сутк|день)|"
    r"по итогам (?:дня|ночи|суток)|за (?:прошедши\w+ )?(?:сутки|ночь|неделю)|"
    r"сообщал\w* ранее|напомним|как сообщалось|как стало известно|как выяснилось|"
    r"(?<!\bне )(?<!\bбудет )(?<!\bбудут )"
    r"\b(?:сбит|уничтожен|отраж[её]н|ликвидирован|устран[её]н|локализован)(?:а|о|ы)?\b|"
    r"\d{1,2}\s+(?:январ|феврал|март|апрел|ма[йя]|июн|июл|август|сентябр|октябр|ноябр|декабр)\w*",
    re.I,
)

ALL_CLEAR_RE = re.compile(
    r"отбо[йя]\b|снят\w*\s+(?:режим\w*\s+)?(?:беспилотн\w*|ракетн\w*|воздушн\w*|опасн\w*)|"
    r"опасност\w*\s+снят|угроза\s+снят|тревога\s+отмен|"
    r"режим\w*\s+беспилотн\w*\s+опасност\w*\s+отмен|"
    r"отмен\w*\s+(?:режим\w*\s+)?(?:беспилотн\w*|ракетн\w*|воздушн\w*)|"
    r"обстановка\s+спокойн|угроз\w*\s+миновал",
    re.I,
)

# --------------------------------------------------------------------------
#  Страховка поверх разбора ИИ (с 4.9.9.2)
# --------------------------------------------------------------------------
#
# Модель — главный судья, но не единственный. Две ошибки она делала
# на живом сервере, и обе стоят доверия к сигналам:
#
# * новость СМИ пересказывает уже прошедшую ракетную опасность
#   («вечером в Саратове была объявлена ракетная опасность, она
#   действовала с 21:10 до 22:40») — и уходила тревогой, потому что
#   в тексте есть «ракетная опасность»;
# * памятка ЖКХ о действиях при аварии уходила как авария с заголовком
#   «ЖКХ и аварии на сетях» — хотя никакой аварии не было.
#
# Правила ниже не заменяют модель, а ловят то, что она пропустила.
# Ошибиться в обратную сторону — спрятать настоящую тревогу — хуже,
# поэтому обе проверки уступают признакам «происходит сейчас».

# Сама опасность описана в прошедшем времени: «была объявлена»,
# «объявлялась», «действовала», закрытый интервал «с 21:10 до 22:40».
# Настоящее и перфект («объявлена», «введена», «действует») сюда
# не попадают — это ровно то, что должно оставаться тревогой.
PAST_THREAT_RE = re.compile(
    r"\b(?:был[аои]?|ранее)\s+(?:\w+\s+){0,2}(?:объявлен|введ[её]н|действовал)\w*|"
    r"\bобъявлял\w*|\bвводил\w*|\bдействовал\w*|"
    r"\bс\s+\d{1,2}[:.]\d{2}\s+до\s+\d{1,2}[:.]\d{2}|"
    r"\bв течение\s+(?:\d+\s+)?(?:час|минут)\w*",
    re.I,
)

# Признаки того, что опасность действует прямо сейчас. При них
# ни «прошедшее время», ни «памятка» тревогу не отменяют.
LIVE_THREAT_RE = re.compile(
    r"оставайтесь|укройтесь|пройдите в укрыти|пройти в укрыти|"
    r"до (?:объявления )?отбоя|пока не будет объявлен отбой|"
    r"\bдействует\b|сохраняется\b|продолжает действовать|"
    r"прямо сейчас|в данный момент|\bвнимание\s*!",
    re.I,
)

# Памятка, а не событие: как действовать, куда звонить.
GUIDANCE_RE = re.compile(
    r"памятк|инструкци\w*\s+(?:о|по)\s+действи|как (?:правильно )?действовать|"
    r"что делать,?\s+(?:при|если|в случае)|правил\w*\s+поведения|"
    r"порядок действий|рекомендаци\w*\s+(?:жител|населени|граждан)|"
    r"номер\w*\s+(?:телефон\w*\s+)?(?:экстренн|аварийн|единой дежурн)|"
    r"напоминаем\s+(?:жител|о правил|номер|порядок)",
    re.I,
)

THREAT_CATEGORIES = frozenset({"bpla", "mchs"})


def refine(analysis: "Analysis") -> "Analysis":
    """Доправляет разбор там, где модель ошибалась (с 4.9.9.2).

    Возвращает тот же объект — правка на месте, чтобы не терять поля,
    которые сюда не относятся.
    """
    text = analysis.raw or analysis.summary
    live = bool(LIVE_THREAT_RE.search(text))

    # Памятка. От модели — верим как есть: она видит контекст целиком.
    # От правила — только когда нет признаков «происходит сейчас»:
    # живое оповещение с порядком действий памяткой не становится.
    if not analysis.guidance and not live and GUIDANCE_RE.search(text):
        analysis.guidance = True
    if analysis.guidance:
        # Памятка не бывает «в прошлом» и не бывает отбоем: это просто
        # текст, который полезно прочитать. И она общегородская — улиц
        # у инструкции нет, а по совпадению улиц её иначе не доставить.
        analysis.historical = False
        analysis.all_clear = False
        analysis.severity = "info"
        analysis.scope = "city"
        analysis.streets = []
        return analysis

    # Прошедшая опасность, которую пересказывает новость.
    if (
        not analysis.historical
        and not analysis.all_clear
        and set(analysis.categories) & THREAT_CATEGORIES
        and not live
        and PAST_THREAT_RE.search(text)
    ):
        analysis.historical = True
        analysis.severity = "info"
    return analysis


_STREET_TYPE_RE = (
    r"(?:ул(?:ица|\.)?|пр(?:оспект|-т|\.)?|пер(?:еулок|\.)?|б(?:ульвар|-р)|"
    r"ш(?:оссе|\.)?|пл(?:ощадь|\.)?|проезд|наб(?:ережная|\.)?|тракт|мкр(?:орайон)?)"
)
_STREET_AFTER = re.compile(
    _STREET_TYPE_RE + r"\s+([А-ЯЁ][\w\-]+(?:\s+[А-ЯЁ]?[\w\-]+){0,2})", re.U
)
_STREET_BEFORE = re.compile(
    r"([А-ЯЁ][\w\-]+(?:\s+[А-ЯЁ]?[\w\-]+){0,1})\s+" + _STREET_TYPE_RE + r"(?![\w])", re.U
)
_HOUSES = re.compile(r"(?:д(?:ом|\.)|№)\s*([\d]+[А-Яа-яA-Za-z]?(?:\s*/\s*\d+)?)", re.U)
_DISTRICT = re.compile(r"([А-ЯЁ][а-яё\-]+)\s+район", re.U)
_CITY = re.compile(r"(?:в|город[еа]?|г\.)\s+([А-ЯЁ][а-яё\-]+)", re.U)


def heuristic_analysis(
    text: str, *, source: str = "", default_city: str = "", link: str = ""
) -> Analysis:
    """Резервный разбор без ИИ: ключевые слова + извлечение улиц и домов."""
    categories = [key for key, pattern in _HEURISTICS if pattern.search(text)]
    if not categories:
        return Analysis(
            relevant=False, source=source, raw=text, link=link, engine="heuristic"
        )

    streets: list[dict[str, Any]] = []
    seen: set[str] = set()
    for match in list(_STREET_AFTER.finditer(text)) + list(_STREET_BEFORE.finditer(text)):
        name = match.group(1).strip(" ,.;:")
        key = name.lower()
        if len(name) < 3 or key in seen:
            continue
        seen.add(key)
        tail = text[match.end(): match.end() + 60]
        houses = [h.replace(" ", "") for h in _HOUSES.findall(tail)]
        streets.append({"street": name, "houses": houses})

    districts = [f"{d} район" for d in dict.fromkeys(_DISTRICT.findall(text))]
    city_match = _CITY.search(text)
    city = city_match.group(1) if city_match else default_city

    if "bpla" in categories:
        scope = "city"
    elif streets:
        scope = "street"
    elif districts:
        scope = "district"
    else:
        scope = "city"

    all_clear = bool(ALL_CLEAR_RE.search(text))
    historical = bool(HISTORICAL_RE.search(text))
    if all_clear or historical:
        severity = "info"
    else:
        severity = "critical" if {"bpla", "mchs"} & set(categories) else "warning"
    summary = re.sub(r"\s+", " ", text).strip()
    return refine(Analysis(
        relevant=True,
        all_clear=all_clear,
        historical=historical,
        categories=categories,
        severity=severity,
        scope=scope,
        city=city,
        districts=districts,
        streets=streets[:8],
        summary=summary[:400],
        source=source,
        raw=text,
        link=link,
        engine="heuristic",
    ))


# --------------------------------------------------------------------------
#  Сопоставление новости с локацией
# --------------------------------------------------------------------------

def location_city(loc: dict[str, Any]) -> str:
    return str(loc.get("city") or "")


def geo_matches(analysis: Analysis, loc: dict[str, Any]) -> bool:
    """Относится ли событие к местности пользователя.

    Правило намеренно строгое: **без подтверждённого совпадения оповещение
    на весь город не отправляется**. Прежде проверка пропускалась, если ИИ
    не извлёк город, и сообщение федерального канала о другом регионе уходило
    всем — саратовец получал тревогу про Подмосковье.

    Порядок проверок:
      1. Город события совпал с городом локации.
      2. Регион события совпал с регионом локации.
      3. География события известна, но не совпала — отказ.
      4. География события не распознана: для адресных событий полагаемся
         на совпадение улицы (она достаточно специфична), для общегородских —
         ищем упоминание города или региона в тексте, иначе отказ.
    """
    loc_city = location_city(loc)
    loc_region = str(loc.get("region") or "")

    if analysis.city and loc_city and same_city(analysis.city, loc_city):
        return True
    if analysis.region and loc_region and same_city(analysis.region, loc_region):
        return True

    # География события известна, но с локацией не сошлась
    if (analysis.city and loc_city) or (analysis.region and loc_region):
        return False

    # География события не распознана
    if not analysis.city and not analysis.region:
        if analysis.streets:
            # Адресное событие: решает совпадение улицы дальше по цепочке
            return True
        haystack = f"{analysis.raw} {analysis.summary}".lower()
        for name in (loc_city, loc_region):
            normalized = normalize_city(name)
            if normalized and len(normalized) >= 4 and normalized in haystack:
                return True
        return False

    # У локации нет географии — записи из старых версий, где хранился
    # только адрес. Доверяем улице, но не рассылаем общегородские тревоги.
    if not loc_city and not loc_region:
        return bool(analysis.streets)

    return False


def matches_location(analysis: Analysis, loc: dict[str, Any]) -> bool:
    """Затрагивает ли событие конкретную локацию пользователя."""
    if not analysis.relevant:
        return False

    if not geo_matches(analysis, loc):
        return False

    if analysis.is_city_wide:
        return True

    # Адресный уровень: улица (и дом), затем район, затем общегородская авария.
    loc_street = str(loc.get("street") or "")
    loc_house = str(loc.get("house") or "")
    if analysis.streets:
        if not loc_street:
            return _raw_mentions_location(analysis, loc)
        for item in analysis.streets:
            if street_matches(loc_street, item.get("street", "")):
                if house_in_range(loc_house, item.get("houses") or []):
                    return True
        return False

    if analysis.districts:
        loc_district = str(loc.get("district") or "")
        if loc_district:
            return any(district_matches(loc_district, d) for d in analysis.districts)
        return False

    if analysis.scope in ("city", "region"):
        return True

    return False


def _raw_mentions_location(analysis: Analysis, loc: dict[str, Any]) -> bool:
    """Запасной путь для старых локаций без разобранного адреса."""
    name = str(loc.get("name") or "")
    tokens = {w for w in re.findall(r"[а-яёa-z0-9]{4,}", name.lower())}
    if not tokens:
        return False
    haystack = (analysis.raw + " " + " ".join(s.get("street", "") for s in analysis.streets)).lower()
    return any(token in haystack for token in tokens)


def match_locations(analysis: Analysis, locations: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    return [loc for loc in locations if matches_location(analysis, loc)]


# --------------------------------------------------------------------------
#  Сборка сообщений
# --------------------------------------------------------------------------

def _loc_label(loc: dict[str, Any]) -> str:
    return esc(loc.get("name") or "локация")


def _label(key: str, russian: str, lang: str = "ru") -> str:
    """Строка каркаса оповещения на нужном языке.

    Переводится ТОЛЬКО каркас — заголовки и пояснения. Текст самого
    сообщения из городского канала идёт как есть: обращение к модели
    ради перевода добавило бы секунды к срочному оповещению и могло бы
    не вернуться вовсе. Понятная наполовину тревога сейчас лучше
    полностью переведённой через минуту.
    """
    from . import i18n

    return i18n.t(key, lang, russian)


def category_title(key: str, lang: str = "ru") -> str:
    """Название категории оповещения. Русское — запасной вариант."""
    return _label(f"category.{key}", CATEGORY_TITLES.get(key, key), lang)


def format_locations_header(locations: Sequence[dict[str, Any]], note: str = "",
                            lang: str = "ru") -> str:
    names = ", ".join(_loc_label(loc) for loc in locations)
    suffix = f" <i>({note})</i>" if note else ""
    title = _label("alert.matched", "Совпавшие локации", lang)
    return f"📍 <b>{title}:</b> {names}{suffix}"


def _source_label(analysis: Analysis) -> str:
    label = analysis.source or "источник"
    name = esc(label) if ("." in label or "/" in label) else f"@{esc(label)}"
    # У новости из RSS есть прямая ссылка — делаем заголовок кликабельным.
    if analysis.link:
        return f'<a href="{esc_attr(analysis.link)}">{name}</a>'
    return name


def _no_ads(text: str) -> str:
    """Текст без рекламы VPN — с нейтральной пометкой, не с партнёрской.

    В оповещениях своя реклама недопустима так же, как чужая
    (CLAUDE.md, «Что не обсуждается», п.2), поэтому здесь только
    пометка о вырезанном — см. radar/adfilter.py.
    """
    from . import adfilter

    return adfilter.strip(text)[0]


def _event_line(analysis: Analysis) -> str:
    icon = "✅" if analysis.all_clear else SEVERITY_ICONS.get(analysis.severity, "🔵")
    mark = "" if analysis.engine == "ai" else " <i>(без ИИ)</i>"
    line = f"{icon} <b>{_source_label(analysis)}</b>{mark}\n{esc(_no_ads(analysis.text()))}"
    if analysis.link:
        line += f'\n🔗 <a href="{esc_attr(analysis.link)}">Читать источник</a>'
    return line


def build_city_alert(
    city: str,
    locations: Sequence[dict[str, Any]],
    events: Sequence[Analysis],
    whitelist_notice: bool = False,
    lang: str = "ru",
) -> str:
    """Одно сообщение на город: военные и другие общегородские угрозы."""
    titles = {analysis.title() for analysis in events}
    danger = _label("alert.danger", "ОПАСНОСТЬ", lang)
    head = f"🚨 <b>{danger} — {esc(city or 'город')}</b>"
    lines = [
        head,
        f"<b>{esc(' / '.join(sorted(titles)))}</b>",
        format_locations_header(
            locations, _label("alert.citywide", "весь город", lang), lang
        ),
        "",
    ]
    lines.extend(_event_line(analysis) for analysis in events)
    if whitelist_notice:
        lines.append("")
        # Флаг проверяется здесь, а не только у вызывающего: примечание
        # добавляется из нескольких мест, и договорённость «проверьте сами»
        # уже один раз не сработала.
        if _whitelist_enabled():
            lines.append(WHITELIST_NOTICE)
    return "\n".join(lines)


def build_all_clear(
    city: str,
    locations: Sequence[dict[str, Any]],
    events: Sequence[Analysis],
    whitelist_notice: bool = False,
) -> str:
    """Отбой опасности: спокойный тон, другой сигнал, без слова «ОПАСНОСТЬ»."""
    titles = {analysis.title() for analysis in events}
    lines = [
        f"✅ <b>ОТБОЙ — {esc(city or 'город')}</b>",
        f"<b>{esc(' / '.join(sorted(titles)))}</b> — опасность снята",
        format_locations_header(locations, "весь город"),
        "",
    ]
    lines.extend(_event_line(analysis) for analysis in events)
    if whitelist_notice:
        lines.append("")
        lines.append(ALL_CLEAR_NOTICE)
    return "\n".join(lines)


def build_utility_alert(locations: Sequence[dict[str, Any]], events: Sequence[Analysis], grouped: bool) -> str:
    """Сообщение по ЖКХ/адресным событиям для одной группы локаций."""
    note = "в пределах 1 км" if grouped else ""
    lines = [
        "🛠 <b>ЖКХ и аварии на сетях</b>",
        format_locations_header(locations, note),
        "",
    ]
    lines.extend(_event_line(analysis) for analysis in events)
    return "\n".join(lines)


# Предел текста памятки. Telegram режет на 4096, send_html делит длинное
# на части, но памятка на три сообщения — это уже не памятка, а стена.
GUIDANCE_LIMIT = 3000


def source_link(analysis: Analysis) -> str:
    """Ссылка на оригинал: сохранённая или собранная по имени канала."""
    if analysis.link:
        return analysis.link
    name = (analysis.source or "").lstrip("@")
    if re.fullmatch(r"[A-Za-z0-9_]{5,32}", name):
        return f"https://t.me/{name}"
    return ""


def build_guidance(analysis: Analysis) -> str:
    """Памятка целиком, со ссылкой на источник и без «опасности».

    Пересылкой в прямом смысле это быть не может: бот читает каналы
    через веб-превью, а не как участник, и переслать пост средствами
    Telegram ему нечем. Поэтому — полный текст и ссылка на оригинал,
    где пост виден таким, каким его опубликовали.
    """
    body = _no_ads((analysis.raw or analysis.summary).strip())
    if len(body) > GUIDANCE_LIMIT:
        body = body[:GUIDANCE_LIMIT].rstrip() + "…"
    lines = [
        f"ℹ️ <b>Памятка</b> · {_source_label(analysis)}",
        "",
        esc(body),
    ]
    link = source_link(analysis)
    if link:
        lines += ["", f'🔗 <a href="{esc_attr(link)}">Оригинал сообщения</a>']
    return "\n".join(lines)


def cluster_title(cluster: Sequence[dict[str, Any]]) -> str:
    """Заголовок сводки погоды: одна локация или список объединённых."""
    names = ", ".join(_loc_label(loc) for loc in cluster)
    if len(cluster) > 1:
        return f"📍 <b>{names}</b> <i>(в пределах 1 км)</i>"
    return f"📍 <b>{names}</b>"


# --------------------------------------------------------------------------
#  Группировка оповещений для одного пользователя
# --------------------------------------------------------------------------

def _city_of(analysis: Analysis, locations: Sequence[dict[str, Any]], fallback: str) -> tuple[str, str]:
    """Ключ группировки по городу и его отображаемое имя."""
    for loc in locations:
        city = str(loc.get("city") or "")
        if city:
            return normalize_city(city), city
    city = analysis.city or fallback
    return normalize_city(city), city or "город"


def _whitelist_enabled() -> bool:
    try:
        from . import features

        return features.enabled("whitelist_notice")
    except Exception:  # noqa: BLE001
        return True


def _all_clear_enabled() -> bool:
    """Ленивая проверка флага: matching не должен зависеть от features
    на уровне импорта — модуль используется и в тестах без окружения."""
    try:
        from . import features

        return features.enabled("all_clear")
    except Exception:  # noqa: BLE001
        return True


def plan_alerts(
    locations: Sequence[dict[str, Any]],
    settings: dict[str, Any],
    analyses: Sequence[Analysis],
    radius_m: float = 1000.0,
    default_city: str = "",
) -> list[tuple[str, str]]:
    """Собирает готовые сообщения для пользователя.

    Правила:
      * военные и другие общегородские угрозы — одно сообщение на город
        со списком всех совпавших локаций в нём;
      * ЖКХ и адресные события — отдельное сообщение на группу локаций;
      * локации ближе radius_m объединяются в одну группу.

    Возвращает список пар («city» | «utility», текст сообщения).
    """
    if not locations:
        return []

    enabled = {key for key, value in (settings or {}).items() if value}
    warn_about_whitelist = "whitelist" in enabled
    clusters = cluster_locations(locations, radius_m)

    city_buckets: dict[str, dict[str, Any]] = {}
    cluster_buckets: dict[int, dict[str, Any]] = {}
    guidance: list[str] = []

    for analysis in analyses:
        if not analysis.relevant or not (set(analysis.categories) & enabled):
            continue

        # Памятка — отдельным сообщением, до разбора на тревоги: она
        # не опасность и не должна попасть ни в «ОПАСНОСТЬ — город»,
        # ни в «ЖКХ и аварии на сетях». География та же, что у тревоги:
        # без подтверждённого города её не шлём.
        if analysis.guidance:
            if match_locations(analysis, locations):
                guidance.append(build_guidance(analysis))
            continue

        # Событие в прошлом — не повод для тревоги. Оно уйдёт в сводку,
        # которую бот присылает утром и вечером.
        if analysis.historical:
            continue

        matched = match_locations(analysis, locations)
        if not matched:
            continue

        if analysis.all_clear and not _all_clear_enabled():
            # Флаг «Отбой опасности» выключен — сообщений об отбое не шлём.
            # Раньше флаг значился в списке и ни на что не влиял.
            continue

        if analysis.is_city_wide:
            key, label = _city_of(analysis, matched, default_city)
            # Отбой не должен смешиваться с действующей тревогой в одном сообщении.
            bucket_key = f"{key}:clear" if analysis.all_clear else key
            bucket = city_buckets.setdefault(
                bucket_key,
                {"city": label, "locs": {}, "events": [], "all_clear": analysis.all_clear},
            )
            bucket["events"].append(analysis)
            for loc in matched:
                bucket["locs"][loc.get("id") or loc.get("name")] = loc
            continue

        matched_ids = {id(loc) for loc in matched}
        for index, cluster in enumerate(clusters):
            inside = [loc for loc in cluster if id(loc) in matched_ids]
            if not inside:
                continue
            bucket = cluster_buckets.setdefault(
                index, {"size": len(cluster), "locs": {}, "events": []}
            )
            bucket["events"].append(analysis)
            for loc in inside:
                bucket["locs"][loc.get("id") or loc.get("name")] = loc

    messages: list[tuple[str, str]] = []
    for bucket in city_buckets.values():
        military = any("bpla" in analysis.categories for analysis in bucket["events"])
        notice = military and warn_about_whitelist
        locs = list(bucket["locs"].values())
        if bucket["all_clear"]:
            messages.append(
                ("clear", build_all_clear(bucket["city"], locs, bucket["events"], notice))
            )
        else:
            messages.append(
                ("city", build_city_alert(bucket["city"], locs, bucket["events"], notice))
            )
    for bucket in cluster_buckets.values():
        messages.append(
            (
                "utility",
                build_utility_alert(
                    list(bucket["locs"].values()), bucket["events"], grouped=bucket["size"] > 1
                ),
            )
        )
    # Памятки — последними: сначала то, что происходит, потом то,
    # что полезно знать.
    messages.extend(("guidance", text) for text in guidance)
    return messages


# --------------------------------------------------------------------------
#  Сводка по завершившимся событиям
# --------------------------------------------------------------------------

def build_recap(
    events: Sequence[Analysis],
    period: str = "за сутки",
    region_hint: str = "",
) -> str:
    """Спокойная сводка по тому, что уже произошло.

    Отделена от тревог намеренно: сигнал об опасности должен означать
    «происходит сейчас». Если мешать его с пересказом вчерашних событий,
    люди перестают реагировать на оба.
    """
    if not events:
        return ""

    by_category: dict[str, list[Analysis]] = {}
    for item in events:
        for category in item.categories or ["other"]:
            by_category.setdefault(category, []).append(item)

    header = f"📰 <b>Сводка {esc(period)}</b>"
    if region_hint:
        header += f" — {esc(region_hint)}"
    lines = [header, ""]

    order = ("bpla", "mchs", "jkh", "whitelist")
    for category in order:
        items = by_category.get(category)
        if not items:
            continue
        icon = CATEGORY_ICONS.get(category, "•")
        lines.append(f"{icon} <b>{esc(CATEGORY_TITLES.get(category, category))}</b>")
        for item in items[:6]:
            lines.append(f"• {esc(_no_ads(item.text())[:280])}")
            if item.link:
                lines.append(f'  🔗 <a href="{esc_attr(item.link)}">источник</a>')
        if len(items) > 6:
            lines.append(f"  <i>…и ещё {len(items) - 6}</i>")
        lines.append("")

    lines.append("<i>Это сводка о том, что уже завершилось. "
                 "Об опасности прямо сейчас бот сообщает отдельно.</i>")
    return "\n".join(lines).strip()
