from .textutils import esc

log = logging.getLogger("radar.aibench")

REQUEST_TIMEOUT = 60
PAUSE = 1.5


@dataclass(frozen=True)
class Provider:
    key: str
    title: str
    env: str
    base_url: str
    model: str
    kind: str = "openai"       # openai | gemini | anthropic
    region: str = ""


PROVIDERS: tuple[Provider, ...] = (
