cat > "radar/partners.py" <<'RADAR_FILE_33'
"""Партнёрские проекты.

Раздел со списком проектов автора вместо одной кнопки. Проекты хранятся
данными, а не в коде: суперадминистратор добавляет, скрывает и меняет
порядок из бота, без правки исходников и пересборки образа.

Границы, заданные в дорожной карте и здесь соблюдаемые:

* реклама только собственных проектов автора — сторонних объявлений
  в «Радаре» нет и не планируется;
* оповещения об опасности не место для промо: раздел живёт в меню,
  а внутрь тревог не попадает (`PROMO_IN_ALERTS` по умолчанию выключен).

Первый проект — HydraSite — переносится из настроек `.env`, чтобы
существующие установки не потеряли кнопку при обновлении.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import logging
import re
from dataclasses import dataclass, field
from typing import Any
from urllib.parse import urlparse

from . import config

log = logging.getLogger("radar.partners")

MAX_PROJECTS = 20
MAX_TITLE = 48
MAX_DESCRIPTION = 300
MAX_TERMS = 600

# Режимы промокода
NONE = "none"
SHARED = "shared"
UNIQUE = "unique"
KINDS = (NONE, SHARED, UNIQUE)
KIND_TITLES = {
    NONE: "нет промокода",
    SHARED: "один код на всех",
    UNIQUE: "свой код каждому",
}

# Ссылка ведёт наружу, и по ней пойдут люди, которым бот сообщает
# об опасности. Схемы кроме http(s) и telegram-ссылок не принимаем.
ALLOWED_SCHEMES = ("http", "https", "tg")

_SLUG_RE = re.compile(r"^[a-z0-9-]{2,32}$")


def clean_description(text: str, title: str = "", icon: str = "") -> str:
    """Приводит описание к виду, пригодному для показа в списке.

    Две беды, обе видны только на живых данных:

    * описание могло прийти из PROMO_TEXT с HTML-разметкой, а в списке
      текст экранируется — человек видел «<b>HydraSite</b>» буквально;
    * первая строка часто дублировала название, которое уже стоит
      заголовком, и выглядело это как сбой.

    Чистим при каждом чтении, а не только при создании: у тех, кто
    обновился раньше, запись уже лежит в базе испорченной, и правка
    в момент создания их не спасёт.
    """
    from .textutils import strip_tags

    cleaned = strip_tags(text or "").strip()
    if not cleaned:
        return ""

    lines = cleaned.split("\n")
    while lines and _echoes_title(lines[0], title, icon):
        lines.pop(0)
    return "\n".join(lines).strip()


def _echoes_title(line: str, title: str, icon: str) -> bool:
    """Повторяет ли строка описания название проекта."""
    if not title:
        return False
    cleaned = line.replace(icon, "").strip() if icon else line.strip()
    if not cleaned:
        return True
    return cleaned.lower().startswith(title.lower())


@dataclass
class Project:
    """Один партнёрский проект."""

    slug: str
    title: str
    url: str
    description: str = ""
    icon: str = "🔗"
    order: int = 100
    visible: bool = True
    clicks: int = 0

    # --- промокоды (с 4.7) ---
    # Три режима. NONE — у проекта промокода нет.
    # SHARED — код один на всех (партнёр раздал одну строку); закрепляем
    #   за человеком дату получения, потому что срок считается от неё.
    # UNIQUE — код генерируется каждому свой; партнёру отдаётся выгрузка
    #   кодов с датами, без наших идентификаторов.
    promo_kind: str = "none"
    promo_value: str = ""            # для SHARED — сама строка кода
    promo_prefix: str = ""           # для UNIQUE — приставка вида HYDRA
    promo_terms: str = ""            # условия, пишет суперадминистратор

    def to_dict(self) -> dict[str, Any]:
        return {
            "slug": self.slug, "title": self.title, "url": self.url,
            "description": self.description, "icon": self.icon,
            "order": self.order, "visible": self.visible, "clicks": self.clicks,
            "promo_kind": self.promo_kind, "promo_value": self.promo_value,
            "promo_prefix": self.promo_prefix, "promo_terms": self.promo_terms,
        }

    @property
    def has_promo(self) -> bool:
        if self.promo_kind == SHARED:
            return bool(self.promo_value)
        return self.promo_kind == UNIQUE

    @classmethod
    def from_dict(cls, raw: dict[str, Any] | None) -> "Project | None":
        """Разбор записи. None — если запись негодная.

        Мусор в данных не должен ронять раздел целиком: одна битая запись
        просто выпадает из списка, остальные показываются.
        """
        if not isinstance(raw, dict):
            return None
        slug = str(raw.get("slug") or "").strip().lower()
        title = str(raw.get("title") or "").strip()
        url = str(raw.get("url") or "").strip()
        if not valid_slug(slug) or not title or not valid_url(url):
            return None
        icon = str(raw.get("icon") or "🔗")[:4]
        return cls(
            slug=slug,
            title=title[:MAX_TITLE],
            url=url,
            description=clean_description(
                str(raw.get("description") or ""), title, icon
            )[:MAX_DESCRIPTION],
            icon=icon,
            order=_as_int(raw.get("order"), 100),
            visible=bool(raw.get("visible", True)),
            clicks=max(0, _as_int(raw.get("clicks"), 0)),
            promo_kind=_as_kind(raw.get("promo_kind")),
            promo_value=str(raw.get("promo_value") or "")[:64].strip(),
            promo_prefix=str(raw.get("promo_prefix") or "")[:12].strip().upper(),
            promo_terms=str(raw.get("promo_terms") or "")[:MAX_TERMS],
        )


def from_form(data: Any, existing: "Project | None" = None) -> "Project | None":
    """Проект из полей формы веб-панели. None — поля негодные.

    Собирается через `from_dict`, а не присваиванием: там уже живут обрезка
    длин, чистка описания и разбор режима промокода. Второй набор этих
    правил в панели неминуемо разошёлся бы с ботом — человек получил бы
    проект, который бот показывает иначе, чем панель обещала.

    Переходы берутся у существующей записи: правка названия не повод
    обнулять счётчик, по которому считается отдача партнёра.
    """
    def value(key: str, default: str = "") -> str:
        try:
            return str(data.get(key, default) or default)
        except AttributeError:
            return default

    return Project.from_dict({
        "slug": value("slug"),
        "title": value("title"),
        "url": value("url"),
        "description": value("description"),
        "icon": value("icon") or "🔗",
        "order": value("order", "100"),
        # Снятый флажок форма не присылает вовсе — это не «ложь»,
        # а отсутствие ключа, и трактуется именно так.
        "visible": bool(value("visible")),
        "clicks": existing.clicks if existing is not None else 0,
        "promo_kind": value("promo_kind", NONE),
        "promo_value": value("promo_value"),
        "promo_prefix": value("promo_prefix"),
        "promo_terms": value("promo_terms"),
    })


def _as_kind(value: Any) -> str:
    kind = str(value or NONE).strip().lower()
    return kind if kind in KINDS else NONE


def _as_int(value: Any, default: int) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def valid_slug(slug: str) -> bool:
    return bool(_SLUG_RE.match(slug or ""))


def valid_url(url: str) -> bool:
    if not url or len(url) > 500:
        return False
    try:
        parsed = urlparse(url.strip())
    except ValueError:
        return False
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False
    # tg://resolve?domain=… не имеет netloc в привычном смысле
    return bool(parsed.netloc or parsed.path)


def order_projects(projects: list[Project]) -> list[Project]:
    """Порядок показа: по полю order, при равенстве — по названию."""
    return sorted(projects, key=lambda item: (item.order, item.title.lower()))


def visible_projects(projects: list[Project]) -> list[Project]:
    return [item for item in order_projects(projects) if item.visible]


def parse_all(raw: Any) -> list[Project]:
    """Список проектов из хранилища, с отбрасыванием негодных записей."""
    if not isinstance(raw, list):
        return []
    result: list[Project] = []
    seen: set[str] = set()
    for item in raw[:MAX_PROJECTS * 2]:
        project = Project.from_dict(item)
        if project is None:
            log.debug("Пропущена негодная запись партнёрского проекта")
            continue
        if project.slug in seen:
            continue
        seen.add(project.slug)
        result.append(project)
    return result[:MAX_PROJECTS]


def default_projects() -> list[Project]:
    """Проект из настроек .env — чтобы обновление не потеряло кнопку.

    До 4.6.5 партнёрский проект был один и жил в PROMO_*. При первом
    открытии раздела он переносится в список как обычная запись, дальше
    правится из бота наравне с остальными.
    """
    if not config.PROMO_ENABLED or not config.PROMO_URL:
        return []
    title = config.PROMO_TITLE or "Партнёрский проект"
    icon = "🔗"
    # В PROMO_TITLE обычно уже есть значок — отделяем его, чтобы не
    # дублировать в списке.
    parts = title.split(maxsplit=1)
    if len(parts) == 2 and not parts[0].isalnum() and len(parts[0]) <= 4:
        icon, title = parts[0], parts[1]
    description = clean_description(config.PROMO_TEXT or "", title, icon)

    return [Project(
        slug="hydrasite",
        title=title[:MAX_TITLE],
        url=config.PROMO_URL,
        description=description[:MAX_DESCRIPTION],
        icon=icon,
        order=10,
    )]


# --------------------------------------------------------------------------
#  Хранение
# --------------------------------------------------------------------------
#
# Проекты лежат в таблице meta одной записью, а не отдельной таблицей:
# их единицы, они меняются вручную и никогда не участвуют в выборках.
# Отдельная таблица с миграцией дала бы ту же функциональность дороже.

META_KEY = "partners"

_cache: list[Project] | None = None


async def load() -> list[Project]:
    """Список проектов. При первом обращении переносит проект из .env."""
    global _cache
    if _cache is not None:
        return _cache

    from .db import repo

    try:
        raw = await repo.get_meta(META_KEY, None)
    except Exception:  # noqa: BLE001
        log.exception("Не удалось прочитать партнёрские проекты")
        return default_projects()

    if raw is None:
        _cache = default_projects()
        if _cache:
            await save(_cache)
        return _cache

    _cache = parse_all(raw)
    return _cache


async def save(projects: list[Project]) -> None:
    global _cache
    from .db import repo

    ordered = order_projects(projects)[:MAX_PROJECTS]
    await repo.set_meta(META_KEY, [item.to_dict() for item in ordered])
    _cache = ordered


def forget() -> None:
    """Сбросить кэш — нужен тестам и после правки извне."""
    global _cache
    _cache = None


async def by_slug(slug: str) -> Project | None:
    for project in await load():
        if project.slug == slug:
            return project
    return None


async def remember_click(slug: str) -> None:
    """Считает переход. Ошибка счётчика не должна мешать переходу."""
    projects = await load()
    for project in projects:
        if project.slug == slug:
            project.clicks += 1
            try:
                await save(projects)
            except Exception:  # noqa: BLE001
                log.debug("Счётчик переходов не сохранился")
            return
RADAR_FILE_33
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/promo.py"
cat > "radar/promo.py" <<'RADAR_FILE_34'
"""Промокоды партнёрских проектов.

Правило одно и жёсткое: **один код на человека на проект**. Повторное
нажатие возвращает уже выданный код, а не новый. Иначе выдача превращается
в бесконечный источник кодов, и партнёр справедливо перестанет их принимать.

Два режима, потому что партнёры работают по-разному:

* один код на всех — партнёр дал одну строку. Сам код у всех одинаковый,
  но дата получения у каждого своя: срок действия считается от неё,
  а не от того дня, когда код придумали;
* свой код каждому — код генерируется здесь. Партнёру отдаётся выгрузка
  «код и дата выдачи», **без наших идентификаторов**: ему нужно проверять
  коды, а не знать, кто из наших людей за каким пришёл.

Выгрузка намеренно не содержит user_id ни в каком виде — в том числе
не выводится из кода. Код случайный, а не производный от идентификатора:
иначе партнёр смог бы сопоставить коды с людьми, а обещание
«без привязки» оказалось бы неправдой.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import logging
import secrets as _random
from dataclasses import dataclass
from datetime import datetime, timezone

from . import partners

log = logging.getLogger("radar.promo")

# Без похожих знаков: код диктуют голосом и переписывают руками.
ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
CODE_LENGTH = 8
MAX_ATTEMPTS = 12


@dataclass
class Issued:
    """Выданный код."""

    code: str
    project: str
    issued_at: datetime
    shared: bool = False

    @property
    def date(self) -> str:
        return self.issued_at.strftime("%d.%m.%Y")


def generate(prefix: str = "") -> str:
    """Случайный код. Приставка помогает партнёру отличить свои коды."""
    body = "".join(_random.choice(ALPHABET) for _ in range(CODE_LENGTH))
    clean = "".join(char for char in (prefix or "").upper() if char.isalnum())[:8]
    return f"{clean}-{body}" if clean else body


async def issue(project: partners.Project, user_key: str) -> Issued | None:
    """Выдать код человеку. Повтор возвращает прежний.

    None означает «у проекта нет промокода» — вызывающий не должен был
    предлагать кнопку, но проверить дешевле, чем доверять.
    """
    if not project.has_promo:
        return None

    from .db import repo

    existing = await repo.promo_for_user(project.slug, user_key)
    if existing is not None:
        return Issued(
            code=existing["code"],
            project=project.slug,
            issued_at=existing["issued_at"],
            shared=project.promo_kind == partners.SHARED,
        )

    now = datetime.now(timezone.utc)

    if project.promo_kind == partners.SHARED:
        # Код общий, но запись всё равно личная: дата получения у каждого
        # своя, и именно от неё считается срок.
        code = project.promo_value.strip()
        await repo.save_promo(project.slug, user_key, code, now, shared=True)
        return Issued(code=code, project=project.slug, issued_at=now, shared=True)

    # Уникальный: подбираем свободный код. Совпадение маловероятно, но
    # выдать двум людям один код хуже, чем сделать лишний запрос.
    for _ in range(MAX_ATTEMPTS):
        code = generate(project.promo_prefix)
        if await repo.promo_code_taken(code):
            continue
        await repo.save_promo(project.slug, user_key, code, now, shared=False)
        return Issued(code=code, project=project.slug, issued_at=now)

    log.error("Не удалось подобрать свободный промокод для «%s»", project.slug)
    return None


async def export_for_partner(slug: str) -> list[dict[str, str]]:
    """Выгрузка для партнёра: код и дата выдачи, без наших идентификаторов.

    Это обещание, а не оформление: партнёру нужно проверять коды, а не
    знать, кто из наших людей за каким пришёл.
    """
    from .db import repo

    rows = await repo.promo_list(slug)
    return [
        {"code": row["code"], "issued": row["issued_at"].strftime("%Y-%m-%d")}
        for row in rows
    ]


def render_csv(rows: list[dict[str, str]]) -> str:
    """CSV для передачи партнёру. Заголовок — чтобы файл читался без пояснений."""
    lines = ["code,issued"]
    lines.extend(f"{row['code']},{row['issued']}" for row in rows)
    return "\n".join(lines) + "\n"
