cat > "radar/web/auth.py" <<'RADAR_FILE_45'
"""Аутентификация веб-панели через Telegram Login Widget.

Пароли не заводим намеренно: у каждого пользователя уже есть подтверждённая
учётная запись Telegram, а роль хранится в базе бота. Виджет отдаёт данные,
подписанные HMAC от токена бота, — этого достаточно, чтобы убедиться, что
данные не подделаны, и не хранить ещё один секрет.

Проверяется три вещи, и все три обязательны:
  * подпись `hash` сходится с вычисленной по токену бота;
  * `auth_date` не старше допустимого — иначе перехваченная однажды ссылка
    работала бы вечно;
  * роль пользователя есть в базе: обычный пользователь попадает в личный
    кабинет, модератор и выше — ещё и в разделы администрирования.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import hashlib
import hmac
import logging
import secrets as secrets_module
import time
from dataclasses import dataclass, field
from typing import Any

log = logging.getLogger("radar.web.auth")

# Данные виджета считаются свежими сутки; дальше нужен повторный вход
AUTH_TTL = 86400
SESSION_TTL = 3600 * 4
SESSION_COOKIE = "radar_session"

# Защита от подбора: сколько неудачных попыток допустимо с одного адреса
MAX_ATTEMPTS = 10
ATTEMPT_WINDOW = 600


@dataclass
class Session:
    token: str
    user_key: str
    role: str
    created: float = field(default_factory=time.time)
    seen: float = field(default_factory=time.time)

    @property
    def expired(self) -> bool:
        return time.time() - self.created > SESSION_TTL


_sessions: dict[str, Session] = {}
_attempts: dict[str, list[float]] = {}

# Чем узнавать роль в дальнейшем. Панель передаёт свой способ при входе:
# завязываться здесь на хранилище напрямую значило бы тянуть в модуль
# входа половину бота (и ломать офлайн-проверки).
_role_lookup = None


def _secret_key(bot_token: str) -> bytes:
    """Ключ подписи виджета — SHA-256 от токена бота."""
    return hashlib.sha256(bot_token.encode("utf-8")).digest()


def check_signature(data: dict[str, Any], bot_token: str) -> bool:
    """Сверяет подпись данных виджета."""
    received = str(data.get("hash") or "")
    if not received or not bot_token:
        return False

    pairs = sorted(
        f"{key}={value}" for key, value in data.items() if key != "hash"
    )
    payload = "\n".join(pairs)
    expected = hmac.new(
        _secret_key(bot_token), payload.encode("utf-8"), hashlib.sha256
    ).hexdigest()

    # Сравнение постоянного времени: обычное == даёт утечку по таймингу
    return hmac.compare_digest(expected, received)


def check_freshness(data: dict[str, Any], ttl: int = AUTH_TTL) -> bool:
    try:
        issued = int(data.get("auth_date") or 0)
    except (TypeError, ValueError):
        return False
    if issued <= 0:
        return False
    return 0 <= time.time() - issued <= ttl


# Потолок числа адресов в памяти. Отметки о неудачах заводились на каждый
# адрес и не убирались никогда: подбирающему пароль достаточно менять
# источник, чтобы словарь рос без предела. Своё окно истекает у каждой
# записи само, но чистку нужно кому-то запускать.
ATTEMPT_CAP = 5000


def forget_stale_attempts(now: float | None = None) -> int:
    """Убирает адреса, у которых не осталось свежих попыток."""
    moment = now if now is not None else time.time()
    empty = [
        address for address, history in _attempts.items()
        if not any(moment - stamp < ATTEMPT_WINDOW for stamp in history)
    ]
    for address in empty:
        _attempts.pop(address, None)
    return len(empty)


def rate_limited(address: str) -> bool:
    """Не слишком ли много неудачных попыток с этого адреса."""
    now = time.time()
    history = [stamp for stamp in _attempts.get(address, []) if now - stamp < ATTEMPT_WINDOW]
    _attempts[address] = history
    return len(history) >= MAX_ATTEMPTS


def note_failure(address: str) -> None:
    now = time.time()
    if len(_attempts) >= ATTEMPT_CAP:
        forget_stale_attempts(now)
    _attempts.setdefault(address, []).append(now)


def clear_failures(address: str) -> None:
    _attempts.pop(address, None)


def authenticate(
    data: dict[str, Any],
    bot_token: str,
    role_lookup,
    address: str = "",
) -> tuple[Session | None, str]:
    """Полная проверка входа. Возвращает (сессия, причина отказа)."""
    if address and rate_limited(address):
        return None, "слишком много попыток, подождите"

    if not check_signature(data, bot_token):
        if address:
            note_failure(address)
        log.warning("Веб-панель: подпись не сошлась (адрес %s)", address or "?")
        return None, "подпись не сошлась"

    if not check_freshness(data):
        return None, "данные входа устарели, войдите заново"

    user_key = str(data.get("id") or "")
    if not user_key:
        return None, "не передан идентификатор"

    role = role_lookup(user_key)
    if not role:
        return None, "пользователь не зарегистрирован в боте"

    from .. import roles as role_module

    # Зарегистрированный пользователь входит в свой личный кабинет; права
    # на разделы администрирования проверяет guard уже у каждого маршрута.
    # Явная проверка списка важна: roles.level("") по умолчанию равен user.
    if role not in role_module.ORDER:
        log.info("Веб-панель: неизвестная роль %s у пользователя %s", role, user_key)
        return None, "роль пользователя не определена"

    if address:
        clear_failures(address)

    global _role_lookup
    _role_lookup = role_lookup

    session = Session(
        token=secrets_module.token_urlsafe(32),
        user_key=user_key,
        role=role,
    )
    _sessions[session.token] = session
    log.info("Веб-панель: вход %s (%s)", user_key, role)
    return session, ""


#  Вход по одноразовому коду из бота (5.7)
#
#  Виджет Telegram — не единственный путь: у общего аккаунта вход может
#  быть из ВК, MAX или Discord, а Telegram бывает недоступен. Бот в любой
#  сети выдаёт по `/panel` код на пять минут для основного ключа профиля;
#  код одноразовый, перебор ограничен тем же счётчиком попыток с адреса,
#  что и у виджета (десять за десять минут на восемь цифр).

LOGIN_CODE_TTL = 300
_login_codes: dict[str, tuple[str, float]] = {}


def issue_login_code(user_key: str, now: float | None = None) -> str:
    moment = now if now is not None else time.time()
    for code in [code for code, (_, until) in _login_codes.items() if until < moment]:
        _login_codes.pop(code, None)
    for code in [code for code, (owner, _) in _login_codes.items() if owner == str(user_key)]:
        _login_codes.pop(code, None)
    while True:
        code = f"{secrets_module.randbelow(10 ** 8):08d}"
        if code not in _login_codes:
            break
    _login_codes[code] = (str(user_key), moment + LOGIN_CODE_TTL)
    return code


def authenticate_code(code: str, role_lookup, address: str = "",
                      now: float | None = None) -> tuple[Session | None, str]:
    """Вход по коду из бота. Возвращает (сессия, причина отказа)."""
    moment = now if now is not None else time.time()
    if address and rate_limited(address):
        return None, "слишком много попыток, подождите"
    entry = _login_codes.pop("".join(ch for ch in (code or "") if ch.isdigit()), None)
    if entry is None or entry[1] < moment:
        if address:
            note_failure(address)
        return None, "код не подошёл или устарел"
    user_key = entry[0]
    role = role_lookup(user_key)
    from .. import roles as role_module

    if role not in role_module.ORDER:
        return None, "роль пользователя не определена"
    if address:
        clear_failures(address)

    global _role_lookup
    _role_lookup = role_lookup
    session = Session(token=secrets_module.token_urlsafe(32), user_key=user_key, role=role)
    _sessions[session.token] = session
    log.info("Веб-панель: вход по коду %s (%s)", user_key, role)
    return session, ""


def session_by_token(token: str) -> Session | None:
    """Сессия по токену. Роль перечитывается, а не берётся из снимка.

    До 4.9.5.6 роль запоминалась при входе и жила в сессии четыре часа:
    понижённый или удалённый суперадминистратор продолжал открывать
    ключи, возможности и резервные копии до истечения этого срока —
    в боте права снимались сразу, а в панели нет.
    """
    session = _sessions.get(token or "")
    if session is None:
        return None
    if session.expired:
        _sessions.pop(token, None)
        return None

    from .. import roles as role_module

    current = current_role(session.user_key)
    if current not in role_module.ORDER:
        # Удалили пользователя или роль стала неизвестной: сессию закрываем.
        # Понижение до обычного пользователя оставляет доступ к его кабинету.
        log.info("Веб-панель: сессия %s закрыта — пользователь или роль отсутствуют", session.user_key)
        _sessions.pop(token, None)
        return None
    session.role = current

    session.seen = time.time()
    return session


def current_role(user_key: str) -> str | None:
    """Роль из хранилища. None — пользователя больше нет.

    Импорт внутри: хранилище тянет за собой почти весь бот, а модуль
    входа должен оставаться пригодным для офлайн-проверок.
    """
    if _role_lookup is not None:
        try:
            return _role_lookup(str(user_key)) or None
        except Exception:  # noqa: BLE001
            log.warning("Роль %s не перечитана", user_key, exc_info=True)
            return None

    try:
        from .. import storage
    except Exception:  # noqa: BLE001
        return None

    return storage.role_of(str(user_key))


def drop_session(token: str) -> None:
    _sessions.pop(token or "", None)


def cleanup() -> int:
    stale = [token for token, item in _sessions.items() if item.expired]
    for token in stale:
        _sessions.pop(token, None)
    forget_stale_attempts()
    return len(stale)


def active_sessions() -> int:
    cleanup()
    return len(_sessions)


# --------------------------------------------------------------------------
#  Защита форм (с 4.8.4.5)
# --------------------------------------------------------------------------
#
# Пока панель только читала, POST-запросов не было вовсе и защищать было
# нечего. С появлением правки источников и ключей чужая страница могла бы
# отправить форму от имени вошедшего администратора.
#
# Cookie сессии выставлена с SameSite=Lax, и она уже не уходит при POST
# со стороннего сайта — но полагаться на одну эту меру нельзя: значение
# задаётся в одном месте кода, и его правка молча сняла бы защиту.
# Поэтому к ней добавлен обычный скрытый токен.
#
# Токен выводится из токена сессии, а не хранится отдельно: своя таблица
# означала бы своё устаревание и свою очистку, а живёт он ровно столько же.

_CSRF_SALT = b"radar-csrf"


def csrf_token(session: Session | None) -> str:
    """Значение скрытого поля формы."""
    if session is None:
        return ""
    return hmac.new(_CSRF_SALT, session.token.encode("utf-8"),
                    hashlib.sha256).hexdigest()[:32]


def csrf_valid(session: Session | None, value: str) -> bool:
    """Сверка без утечки по времени сравнения."""
    expected = csrf_token(session)
    if not expected or not value:
        return False
    return hmac.compare_digest(expected, str(value))
