    groups: tuple[str, ...] = ()
    flags: tuple[str, ...] = ()
    note: str = ""
    links: tuple[tuple[str, str], ...] = ()     # (адрес, подпись)


@dataclass(frozen=True)
class Section:
    key: str
    path: str
    title: str
    intro: str
    cards: tuple[Card, ...] = field(default_factory=tuple)


