# Общие стили для публичных страниц
PUBLIC_STYLE = """
/* ============================================================
   PUBLIC PAGES STYLES (Privacy, Terms, Support, Pricing)
   ============================================================ */

.public-page {
  max-width: 880px;
  margin: 0 auto;
  padding: clamp(40px, 6vw, 64px) clamp(20px, 5vw, 60px);
}
.public-header {
  text-align: center;
  margin-bottom: 48px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--line);
}
.public-title {
  margin: 0 0 12px;
  font-size: clamp(28px, 4vw, 38px);
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--text);
}
.public-subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}
.public-content {
  line-height: 1.8;
  color: var(--text);
}
.public-content h2 {
  margin: 32px 0 16px;
  font-size: 22px;
  font-weight: 700;
  color: var(--text);
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}
.public-content h3 {
  margin: 24px 0 12px;
  font-size: 17px;
  font-weight: 600;
  color: var(--text);
}
.public-content p { margin: 0 0 16px; }
.public-content ul { margin: 0 0 16px; padding-left: 24px; }
.public-content li { margin-bottom: 8px; line-height: 1.7; }
.public-content a { color: var(--link); text-decoration: none; }
.public-content a:hover { text-decoration: underline; }
.public-content code {
  background: var(--surface-2);
  padding: 2px 6px;
  border-radius: 6px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.9em;
  color: var(--accent);
}
.public-content pre {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 16px;
  overflow-x: auto;
  margin: 16px 0;
}
.public-content pre code { background: none; padding: 0; color: var(--text); }
.public-content blockquote {
  border-left: 3px solid var(--accent);
  padding-left: 16px;
  margin: 16px 0;
  color: var(--muted);
  font-style: italic;
}
.public-content table {
  width: 100%;
  border-collapse: collapse;
  margin: 24px 0;
  font-size: 14px;
}
.public-content th, .public-content td {
  border: 1px solid var(--line);
  padding: 12px 16px;
  text-align: left;
}
.public-content th { background: var(--surface-2); font-weight: 700; }
.public-content tr:nth-child(even) td { background: var(--surface-2); }

/* Support form */
.support-form {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 28px;
  margin-top: 24px;
}
.form-group { margin-bottom: 20px; }
.form-label {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  color: var(--text);
}
.form-input, .form-select, .form-textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text);
  font-size: 15px;
  font-family: inherit;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.form-textarea { min-height: 140px; resize: vertical; }
.form-submit {
  width: 100%;
  padding: 14px 24px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: white;
  border: none;
  border-radius: 10px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
}
.form-submit:hover { box-shadow: 0 4px 16px rgba(79, 140, 255, 0.4); }
.form-submit:active { transform: scale(0.98); }
.form-note { margin-top: 12px; font-size: 13px; color: var(--muted); text-align: center; }

/* Pricing cards */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  margin-top: 32px;
}
.pricing-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
}
.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
  border-color: var(--accent);
}
.pricing-card.popular { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.pricing-name { font-size: 18px; font-weight: 700; color: var(--text); margin-bottom: 8px; }
.pricing-price { font-size: 36px; font-weight: 800; color: var(--text); margin-bottom: 4px; }
.pricing-period { color: var(--muted); font-size: 14px; margin-bottom: 20px; }
.pricing-features { list-style: none; padding: 0; margin: 0 0 24px; flex: 1; }
.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
  font-size: 14px;
  color: var(--text);
  line-height: 1.5;
}
.pricing-features li::before {
  content: "✓";
  color: var(--ok);
  font-weight: 700;
  flex-shrink: 0;
}
.pricing-btn {
  display: block;
  text-align: center;
  padding: 14px 24px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 15px;
  text-decoration: none;
  transition: transform 0.15s, background 0.15s;
}
.pricing-btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: white;
}
.pricing-btn-primary:hover { background: linear-gradient(135deg, var(--accent-2), var(--accent)); }
.pricing-btn-ghost {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--line);
}
.pricing-btn-ghost:hover { border-color: var(--accent); }
.pricing-note { margin-top: 24px; padding-top: 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: 13px; }

/* Contact cards */
.contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
  margin-top: 24px;
}
.contact-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
  transition: transform 0.2s, border-color 0.2s;
}
.contact-card:hover { transform: translateY(-2px); border-color: var(--accent); }
.contact-icon { font-size: 36px; margin-bottom: 12px; }
.contact-title { margin: 0 0 8px; font-size: 17px; font-weight: 700; color: var(--text); }
.contact-desc { margin: 0 0 16px; color: var(--muted); font-size: 14px; }
.contact-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
  font-size: 14px;
  transition: border-color 0.15s, background 0.15s;
}
.contact-link:hover { border-color: var(--accent); background: var(--accent-soft); }

/* Last updated badge */
.last-updated {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 24px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
"""

