def event_digest(source: str, raw: str) -> str:
    return hashlib.sha1(f"{source}\n{raw}".encode("utf-8")).hexdigest()


async def store_event(analysis: Any) -> int | None:
    """Сохраняет разобранное событие, возвращает его id.

    Повторное сохранение того же текста не создаёт дубликат: сработает
    уникальный индекс по digest и вернётся существующая запись.
    """
    if not getattr(analysis, "relevant", False):
        return None

    digest = event_digest(analysis.source, analysis.raw or analysis.summary)
    async with session() as active:
        existing = await active.scalar(select(Event.id).where(Event.digest == digest))
        if existing:
            return int(existing)
        row = Event(
            digest=digest,
            source=(analysis.source or "")[:200],
            kind="rss" if analysis.link else "tg",
            link=analysis.link or "",
            categories=list(analysis.categories),
            severity=analysis.severity,
            scope=analysis.scope,
            all_clear=bool(analysis.all_clear),
            city=(analysis.city or "")[:120],
            region=(analysis.region or "")[:120],
            districts=list(analysis.districts),
            streets=list(analysis.streets),
            summary=analysis.summary or "",
            raw=(analysis.raw or "")[:8000],
            engine=analysis.engine,
        )
        active.add(row)
        await active.flush()
        return int(row.id)


async def record_delivery(
    event_id: int, user_id: int | str, location_public_id: str | None
) -> bool:
    """Отмечает доставку. False — событие этой локации уже отправляли."""
    async with session() as active:
        row = await _find_user(active, user_id)
        if row is None:
            return False
        location_id = None
        if location_public_id:
            location_id = await active.scalar(
                select(Location.id).where(
                    Location.user_id == row.id,
                    Location.public_id == location_public_id,
                )
            )
        existing = await active.scalar(
            select(Delivery.id).where(
                Delivery.event_id == event_id,
                Delivery.user_id == row.id,
                Delivery.location_id == location_id,
            )
        )
        if existing is not None:
            return False
        active.add(
            Delivery(
                event_id=event_id,
                user_id=row.id,
                location_id=location_id,
                sent_at=datetime.now(timezone.utc),
            )
        )
        return True


async def was_delivered(event_id: int, user_id: int | str, location_public_id: str | None) -> bool:
    async with session() as active:
        row = await _find_user(active, user_id)
        if row is None:
            return False
        location_id = None
        if location_public_id:
            location_id = await active.scalar(
                select(Location.id).where(
                    Location.user_id == row.id,
                    Location.public_id == location_public_id,
                )
            )
        found = await active.scalar(
            select(Delivery.id).where(
                Delivery.event_id == event_id,
                Delivery.user_id == row.id,
                Delivery.location_id == location_id,
            )
        )
        return found is not None


async def history(
    user_id: int | str,
    location_public_id: str | None = None,
    *,
    days: int = 30,
    limit: int = 20,
    categories: Iterable[str] | None = None,
) -> list[Event]:
    """История событий, приходивших пользователю (опционально по одной локации)."""
    since = datetime.now(timezone.utc) - timedelta(days=days)
    async with session() as active:
        row = await _find_user(active, user_id)
        if row is None:
            return []
        wanted = set(categories or [])
        query = (
            select(Event)
            .join(Delivery, Delivery.event_id == Event.id)
            .where(Delivery.user_id == row.id, Delivery.sent_at >= since)
            .order_by(Event.created_at.desc())
        )
        if not wanted:
            query = query.limit(limit)
        if location_public_id:
            location_id = await active.scalar(
                select(Location.id).where(
                    Location.user_id == row.id,
                    Location.public_id == location_public_id,
                )
            )
            query = query.where(Delivery.location_id == location_id)
        rows = (await active.scalars(query)).all()

    if wanted:
        rows = [row for row in rows if wanted & set(row.categories or [])][:limit]
    return list(rows)


async def event_stats(days: int = 30) -> dict[str, int]:
    since = datetime.now(timezone.utc) - timedelta(days=days)
    async with session() as active:
        events = await active.scalar(
            select(func.count(Event.id)).where(Event.created_at >= since)
        )
        deliveries = await active.scalar(
            select(func.count(Delivery.id)).where(Delivery.sent_at >= since)
        )
    return {"events": int(events or 0), "deliveries": int(deliveries or 0)}


async def event_breakdown(hours: int = 24) -> dict[str, int]:
    """События за последние часы по категориям — для публичной сводки (5.5).

    Считаются только категории и отбои: ни адресов, ни городов, ни текста.
    Сводка уходит в общий канал, и ничего, что привязывает событие к месту,
    ей не нужно.
    """
    since = datetime.now(timezone.utc) - timedelta(hours=hours)
    async with session() as active:
        rows = (await active.execute(
            select(Event.categories, Event.all_clear).where(Event.created_at >= since)
        )).all()
    counts: dict[str, int] = {"_total": len(rows), "_all_clear": 0}
    for categories, all_clear in rows:
        if all_clear:
            counts["_all_clear"] += 1
        for category in categories or []:
            counts[str(category)] = counts.get(str(category), 0) + 1
    return counts


async def danger_state(city: str = "", hours: int = 24) -> dict[str, bool]:
    """Текущее состояние угроз по последнему событию каждой категории.

    Суточные счётчики для этого не подходят: отбой тоже имеет категорию
    угрозы, но должен снимать статус, а не включать его.
    """
    since = datetime.now(timezone.utc) - timedelta(hours=hours)
    async with session() as active:
        rows = (await active.scalars(
            select(Event)
            .where(Event.created_at >= since)
            .order_by(Event.created_at.desc())
            .limit(1000)
        )).all()

    wanted_city = city.strip().casefold()
    state = {"bpla": False, "mchs": False}
    seen: set[str] = set()
    for row in rows:
        if wanted_city and (row.city or "").strip().casefold() != wanted_city:
            continue
        for category in ("bpla", "mchs"):
            if category in seen or category not in (row.categories or []):
                continue
            seen.add(category)
            state[category] = not row.all_clear and row.severity != "info"
        if len(seen) == 2:
            break
    return state


async def latest_threat(city: str = "", hours: int = 72) -> dict[str, Any] | None:
    """Последнее событие угрозы (bpla/mchs) по городу для публичного виджета.

    Возвращает краткую сводку без привязки к адресу: тип, серьёзность,
    время, текст и признак отбоя. ``None`` — за окно данных ничего не было.
    """
    since = datetime.now(timezone.utc) - timedelta(hours=hours)
    wanted_city = city.strip().casefold()
    async with session() as active:
        query = (
            select(Event)
            .where(Event.created_at >= since)
            .order_by(Event.created_at.desc())
            .limit(500)
        )
        rows = (await active.scalars(query)).all()

    for row in rows:
        if wanted_city and (row.city or "").strip().casefold() != wanted_city:
            continue
        if not ({"bpla", "mchs"} & set(row.categories or [])):
            continue
        created = row.created_at
        if created is not None and created.tzinfo is None:
            created = created.replace(tzinfo=timezone.utc)
        categories = list(row.categories or [])
        return {
            "type": "air_raid" if "bpla" in categories else "mchs",
            "severity": row.severity or "info",
            "all_clear": bool(row.all_clear),
            "summary": (row.summary or "").strip()[:300],
            "source": (row.source or "").strip()[:200],
            "published_at": created.isoformat() if created else "",
        }
    return None


async def recent_events(
    limit: int = 20,
    hours: int = 48,
    categories: Iterable[str] | None = None,
) -> list[dict[str, Any]]:
    """Последние события для публичных виджетов (5.10.0).

    Отдаётся только то, что допустимо показывать без авторизации: сводка,
    источник, ссылка, категории и серьёзность. Адреса, улицы и районы
    сюда не попадают — они привязывают событие к месту и поднимаются
    только в истории конкретного пользователя.
    """
    limit = int(limit)
    if limit <= 0:
        return []
    limit = min(limit, 100)
    since = datetime.now(timezone.utc) - timedelta(hours=hours)
    wanted = set(categories or [])
    async with session() as active:
        query = (
            select(Event)
            .where(Event.created_at >= since)
            .order_by(Event.created_at.desc())
        )
        # Для отфильтрованной ленты LIMIT применяем после проверки категории:
        # иначе подходящие события теряются за первыми limit чужих записей.
        if not wanted:
            query = query.limit(limit)
        rows = (await active.scalars(query)).all()

    result: list[dict[str, Any]] = []
    for row in rows:
        if wanted and not (wanted & set(row.categories or [])):
            continue
        created = row.created_at
        if created is not None and created.tzinfo is None:
            created = created.replace(tzinfo=timezone.utc)
        result.append({
            "id": row.id,
            "title": row.summary or "Событие",
            "summary": row.summary,
            "source": row.source,
            "url": row.link,
            "categories": list(row.categories or []),
            "severity": row.severity,
            "published_at": created.isoformat() if created else "",
        })
        if len(result) >= limit:
            break
    return result


async def purge_old_events(days: int | None = None) -> int:
    """Чистка истории. Возвращает число удалённых событий."""
    keep = config.EVENT_RETENTION_DAYS if days is None else days
    if keep <= 0:
        return 0
    edge = datetime.now(timezone.utc) - timedelta(days=keep)
    async with session() as active:
        result = await active.execute(delete(Event).where(Event.created_at < edge))
        return int(result.rowcount or 0)


