#  Короткие ссылки (с 4.6.1)
# --------------------------------------------------------------------------

async def save_short_link(code: str, url: str, created_by: int = 0) -> None:
    """Запоминает ссылку. Повтор не считается ошибкой: код детерминированный,
    и одна и та же ссылка из двух подборок обязана дать один адрес."""
    async with session() as active:
        row = await active.get(ShortLink, code)
        if row is None:
            active.add(ShortLink(code=code, url=url, created_by=created_by))
        elif row.url != url:
            # Совпадение кодов у разных ссылок теоретически возможно.
            # Молча перезаписать нельзя: разосланные ссылки увели бы не туда.
            log.warning("Код %s уже занят другой ссылкой — сокращение отменено", code)
            return
        await active.commit()


async def resolve_short_link(code: str) -> str | None:
    """Отдаёт адрес и считает переход."""
    async with session() as active:
        row = await active.get(ShortLink, code)
        if row is None:
            return None
        row.hits += 1
        row.last_hit = datetime.now(timezone.utc)
        await active.commit()
        return row.url


async def short_link_stats(limit: int = 20) -> list[dict[str, Any]]:
    async with session() as active:
        result = await active.execute(
            select(ShortLink).order_by(ShortLink.created_at.desc()).limit(limit)
        )
        return [
            {"code": row.code, "url": row.url, "hits": row.hits,
             "created_at": row.created_at}
            for row in result.scalars()
        ]


async def short_link_list(limit: int = 500) -> list[dict[str, Any]]:
    """Ссылки с владельцем — для страницы панели.

    В отличие от short_link_stats, здесь есть created_by: страница
    показывает, кто сократил, и без этого поля была бы списком
    безымянных адресов.
    """
    async with session() as active:
        result = await active.execute(
            select(ShortLink).order_by(ShortLink.created_at.desc()).limit(limit)
        )
        return [
            {"code": row.code, "url": row.url, "hits": row.hits,
             "created_by": row.created_by, "created_at": row.created_at,
             "last_hit": row.last_hit}
            for row in result.scalars()
        ]


async def remove_short_link(code: str) -> bool:
    """Удаляет одну ссылку. False — такой не было."""
    async with session() as active:
        row = await active.get(ShortLink, code)
        if row is None:
            return False
        await active.delete(row)
        await active.commit()
    return True


async def clear_short_links() -> int:
    """Удаляет все ссылки. Возвращает, сколько снесено.

    Автосокращение подборок создаёт их само и переживает чистку:
    при следующем выпуске ссылки появятся снова с теми же кодами.
    """
    async with session() as active:
        result = await active.execute(select(ShortLink))
        rows = list(result.scalars())
        for row in rows:
            await active.delete(row)
        await active.commit()
    return len(rows)


