cat > "radar/redeem.py" <<'RADAR_FILE_92'
#!/usr/bin/env python3
"""Погашение кодов, выданных на стороне.

Партнёрский проект раздаёт коды у себя, человек приносит код сюда
и получает подписку. От `radar/promo.py` это противоположное движение:
там коды выдаём мы и отдаём партнёру выгрузку, здесь код приходит
снаружи и мы его засчитываем.

Список кодов ведёт суперадминистратор — на стороне партнёра они
генерируются как угодно, а сюда попадают готовыми. Своей генерации нет
намеренно: код, который мы придумали сами, партнёр не сможет проверить
у себя, и сверять две выдумки было бы нечем.

Код одноразовый. Кто и когда его погасил, остаётся в записи: без этого
на вопрос «почему у него подписка» ответить нечем.

Про этот механизм ничего не сказано в интерфейсе бота, в README и в списке
изменений — так задумано. Код узнаёт тот, кому его дали на стороне
партнёра, и вводит его сообщением; для остальных ничего не меняется.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import logging
import re
from datetime import datetime, timezone
from typing import Any

log = logging.getLogger("radar.redeem")

# Одна блокировка на весь модуль: гасить коды параллельно нельзя.
_LOCK = asyncio.Lock()

META_KEY = "redeem_codes"

# Сколько дней даёт код по умолчанию.
DEFAULT_DAYS = 28

# Что вообще считаем кодом. Рамки нужны и для проверки при заведении,
# и для того, чтобы обычное сообщение не принималось за попытку погашения.
CODE_RE = re.compile(r"^[A-Z0-9][A-Z0-9-]{4,31}$")

MAX_CODES = 500


def normalize(code: str) -> str:
    """Приводит ввод к хранимому виду: регистр и пробелы человек не считает."""
    return re.sub(r"\s+", "", str(code or "")).upper()


def looks_like_code(text: str) -> bool:
    """Похоже ли сообщение на код. Нужна, чтобы не хватать чужой текст."""
    return bool(CODE_RE.match(normalize(text)))


async def load() -> list[dict[str, Any]]:
    from .db import repo

    try:
        raw = await repo.get_meta(META_KEY, None)
    except Exception:  # noqa: BLE001
        log.exception("Список кодов недоступен")
        return []
    if not isinstance(raw, list):
        return []
    return [item for item in raw if isinstance(item, dict) and item.get("code")]


async def save(items: list[dict[str, Any]]) -> None:
    from .db import repo

    await repo.set_meta(META_KEY, items[:MAX_CODES])


async def add(codes: str, days: int = DEFAULT_DAYS) -> tuple[list[str], list[str]]:
    """Заводит коды из присланного текста. Возвращает (добавленные, пропущенные)."""
    items = await load()
    known = {str(item.get("code")) for item in items}

    added: list[str] = []
    skipped: list[str] = []
    for chunk in re.split(r"[,\n;\s]+", codes or ""):
        code = normalize(chunk)
        if not code:
            continue
        if not CODE_RE.match(code) or code in known:
            skipped.append(chunk.strip())
            continue
        items.append({"code": code, "days": max(1, int(days)),
                      "used_by": "", "used_at": ""})
        known.add(code)
        added.append(code)

    if added:
        await save(items)
        log.info("Заведено кодов: %d", len(added))
    return added, skipped


async def drop(code: str) -> bool:
    items = await load()
    code = normalize(code)
    rest = [item for item in items if str(item.get("code")) != code]
    if len(rest) == len(items):
        return False
    await save(rest)
    return True


async def redeem(code: str, user_key: str) -> int:
    """Гасит код. Возвращает число дней; 0 — код не подошёл.

    Одноразовость проверяется по записи, а не по факту начисления: иначе
    один и тот же код, введённый дважды подряд, дал бы дни дважды.

    Между проверкой «использован ли код» и записью результата стоит await,
    а апдейты aiogram обрабатываются параллельными задачами: без общей
    блокировки два сообщения с одним кодом, отправленные подряд, успевали
    пройти проверку до первой записи, и дни начислялись дважды. Список
    лежит одним значением в базе, поэтому уникальным индексом, как
    у партнёрских промокодов, здесь не обойтись — нужна блокировка.
    """
    code = normalize(code)
    if not CODE_RE.match(code):
        return 0

    async with _LOCK:
        return await _redeem_locked(code, user_key)


async def _redeem_locked(code: str, user_key: str) -> int:
    items = await load()
    for item in items:
        if str(item.get("code")) != code:
            continue
        if item.get("used_by"):
            return 0
        item["used_by"] = str(user_key)
        item["used_at"] = datetime.now(timezone.utc).isoformat()
        await save(items)
        days = max(1, int(item.get("days") or DEFAULT_DAYS))
        log.info("Код погашен: %s дней %d", code[:4] + "…", days)
        return days
    return 0


async def summary() -> str:
    """Состояние списка для суперадминистратора."""
    items = await load()
    if not items:
        return "Кодов пока нет."
    used = sum(1 for item in items if item.get("used_by"))
    return f"Кодов: {len(items)}, погашено: {used}, свободно: {len(items) - used}"
RADAR_FILE_92
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/tg.py"
cat > "radar/tg.py" <<'RADAR_FILE_93'
"""Экземпляр бота и безопасные обёртки отправки сообщений."""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import logging

from aiogram import Bot, Dispatcher
from aiogram.client.default import DefaultBotProperties
from aiogram.enums import ParseMode
from aiogram.exceptions import (
    TelegramBadRequest,
    TelegramForbiddenError,
    TelegramNetworkError,
    TelegramRetryAfter,
    TelegramServerError,
)
from aiogram.fsm.storage.memory import MemoryStorage
from aiogram.types import CallbackQuery, InlineKeyboardButton, InlineKeyboardMarkup

from . import accounts, config, identity
from .textutils import split_text, strip_tags

log = logging.getLogger("radar.tg")

def _build_bot() -> Bot:
    """Экземпляр бота. При заданном TELEGRAM_API_SERVER — через свой сервер.

    Собственный Bot API Server снимает предел отправки с 50 МБ до 2 ГБ.
    Режим is_local означает, что сервер берёт файлы прямо с диска, минуя
    передачу по HTTP, — для видео это на порядок быстрее.
    """
    properties = DefaultBotProperties(parse_mode=ParseMode.HTML)
    if not config.TELEGRAM_API_SERVER:
        return Bot(token=config.BOT_TOKEN, default=properties)

    from aiogram.client.session.aiohttp import AiohttpSession
    from aiogram.client.telegram import TelegramAPIServer

    log.info("Использую собственный Bot API Server: %s", config.TELEGRAM_API_SERVER)
    session = AiohttpSession(
        api=TelegramAPIServer.from_base(
            config.TELEGRAM_API_SERVER, is_local=config.TELEGRAM_API_LOCAL
        )
    )
    return Bot(token=config.BOT_TOKEN, session=session, default=properties)


bot = _build_bot()
dp = Dispatcher(storage=MemoryStorage())

def back_kb(target: str = "menu:main", title: str = "🏠 В главное меню") -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[[InlineKeyboardButton(text=title, callback_data=target)]]
    )


# Сколько раз пытаться отправить один кусок и сколько ждать между
# попытками. До 4.9.8.14 попыток было две, и обе тратились на паузу
# по требованию Telegram: два ответа «retry after» подряд — и кусок
# молча пропадал, а функция возвращала True, то есть «доставлено».
# Для системы оповещения это худший из возможных исходов: тревога
# потеряна, и никто об этом не знает.
SEND_ATTEMPTS = 3
# Потолок паузы. Telegram при сильном ограничении просит подождать
# минуты; держать на этом всю рассылку нельзя — остальные получатели
# ждут своей тревоги.
RETRY_CAP = 30.0


async def send_html(
    chat_id: int | str,
    text: str,
    reply_markup: InlineKeyboardMarkup | None = None,
) -> bool:
    """Отправляет длинный HTML-текст частями, переживая ошибки разметки и лимиты.

    Возвращает True, только если ушло всё. False означает «не доставлено»,
    и вызывающая сторона вправе повторить в следующем цикле. Ценой этого
    может стать повтор первого куска у длинного сообщения, разбитого
    на части: дубль лучше потерянной тревоги.

    С 5.7 профиль может жить и без Telegram — под ключом `vk:…`, `max:…`
    или `discord:…`. Такой ключ уходит адаптеру своей сети (кнопки там
    не передаются): любая рассылка по списку пользователей доставляет
    и им, а не падает на `int("vk:5")`.
    """
    if not identity.is_telegram(chat_id):
        from . import mirror

        return await mirror.send_external(str(chat_id), text)
    # Заблокировавшему бота и удалившему аккаунт слать нечего: запрос
    # к API каждый цикл и предупреждение в журнале ничего не меняют.
    # Отметка снимается, когда человек пишет боту (AccessMiddleware).
    if accounts.is_dead(chat_id):
        return False
    chunks = split_text(text)
    for index, chunk in enumerate(chunks):
        markup = reply_markup if index == len(chunks) - 1 else None
        delivered = False
        for attempt in range(SEND_ATTEMPTS):
            last = attempt == SEND_ATTEMPTS - 1
            try:
                await bot.send_message(int(chat_id), chunk, reply_markup=markup)
                delivered = True
                break
            except TelegramRetryAfter as exc:
                if last:
                    break
                await asyncio.sleep(min(exc.retry_after + 1, RETRY_CAP))
            except TelegramForbiddenError:
                log.info("Пользователь %s недоступен (бот заблокирован)", chat_id)
                if accounts.mark_dead(chat_id):
                    from . import storage

                    try:
                        await storage.save(chat_id)
                    except Exception:  # noqa: BLE001
                        log.debug("Отметка о недоступности не сохранена", exc_info=True)
                return False
            except TelegramBadRequest as exc:
                log.warning("Ошибка разметки (%s), отправляю обычным текстом", exc)
                try:
                    await bot.send_message(
                        int(chat_id), strip_tags(chunk), parse_mode=None, reply_markup=markup
                    )
                    delivered = True
                except Exception:  # noqa: BLE001
                    log.exception("Не удалось отправить сообщение %s", chat_id)
                break
            except (TelegramNetworkError, TelegramServerError) as exc:
                # Обрыв связи и сбой на стороне Telegram — состояния
                # преходящие. Раньше они попадали в общий except ниже
                # и означали отказ без единого повтора: одна икота сети
                # стоила человеку оповещения.
                if last:
                    log.warning("Связь с Telegram не восстановилась: %s", exc)
                    break
                await asyncio.sleep(1.5 * (attempt + 1))
            except Exception:  # noqa: BLE001
                log.exception("Сбой отправки сообщения %s", chat_id)
                return False
        if not delivered:
            log.error(
                "Сообщение для %s не доставлено за %d попытки — будет повторено",
                chat_id, SEND_ATTEMPTS,
            )
            return False
        await asyncio.sleep(0.05)
    return True


async def safe_edit(
    call: CallbackQuery,
    text: str,
    markup: InlineKeyboardMarkup | None = None,
) -> None:
    """edit_text, устойчивый к «message is not modified» и слишком длинным текстам."""
    chunks = split_text(text)
    try:
        await call.message.edit_text(chunks[0], reply_markup=markup if len(chunks) == 1 else None)
    except TelegramBadRequest as exc:
        if "message is not modified" in str(exc):
            return
        try:
            await call.message.answer(chunks[0], reply_markup=markup if len(chunks) == 1 else None)
        except Exception:  # noqa: BLE001
            log.exception("Не удалось обновить сообщение")
            return
    for index, chunk in enumerate(chunks[1:], start=1):
        await send_html(
            call.message.chat.id, chunk, markup if index == len(chunks) - 1 else None
        )
