"""Фоновый цикл: сбор источников, разбор через ИИ, группировка и рассылка."""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import logging
from collections import deque
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import aiohttp

from . import (
    ai,
    backup,
    config,
    dbcare,
    digest,
    features,
    filedrop,
    geocode,
    health,
    i18n,
    presets,
    profiling,
    roles,
    shortener,
    quiet,
    secrets,
    sos,
    sourcecheck,
    sources,
    media,
    mirror,
    music,
    storage,
    timezones,
    weather,
)
from .matching import Analysis, build_recap, cluster_title, geo_matches, plan_alerts
from .textutils import cluster_center, cluster_locations, esc
from .tg import send_html

log = logging.getLogger("radar.monitor")

seen = sources.SeenStore()
_stats = {
    "cycles": 0,
    "items": 0,
    "alerts": 0,
    # Когда последний раз завершился полноценный проход по источникам.
    "last_cycle": 0,
    # Признак жизни самого цикла: обновляется на каждом витке, включая
    # холостые в режиме обслуживания. По нему сторож отличает «бот занят
    # длинным циклом» от «цикла больше нет».
    "heartbeat": 0,
    # Сколько раз цикл поднимался заново после сбоя.
    "restarts": 0,
    # Доставленных оповещений о событиях — без погоды (с 4.9.9.3).
    "delivered": 0,
}

# Задержка от публикации в источнике до рассылки, секунды (с 4.9.9.3).
# Ограниченная очередь: метрике нужны недавние значения, а не история
# с первого запуска, и на одноплатнике память не бесконечна.
_latency: "deque[float]" = deque(maxlen=300)

# Дольше суток — это не задержка, а старая новость, всплывшая заново:
# в медиану она внесла бы шум, а не правду.
LATENCY_CEILING = 24 * 3600


def record_latency(analyses: list, published: dict[str, float],
                   now_ts: float) -> int:
    """Записывает задержку для событий, по которым ушли оповещения.

    Возвращает число записанных значений. Считается от времени поста
    в источнике до конца рассылки этого цикла — то есть ровно то, что
    чувствует человек: когда случилось и когда он узнал.
    """
    recorded = 0
    for analysis in analyses:
        if not analysis.relevant or analysis.historical or analysis.guidance:
            continue
        moment = published.get(analysis.raw, 0.0)
        if not moment:
            continue
        delay = now_ts - moment
        if 0 <= delay <= LATENCY_CEILING:
            _latency.append(delay)
            recorded += 1
    return recorded


def latency_samples() -> list[float]:
    return list(_latency)

def stats() -> dict[str, Any]:
    return dict(_stats, seen=len(seen), cache=ai.cache_size(), **ai.counters())


# --------------------------------------------------------------------------
#  Признак жизни (с 4.9.8.14)
# --------------------------------------------------------------------------
#
# Отметка `last_cycle` собиралась с 4.x и не читалась нигде: ни в /stats,
# ни в диагностике. Смысла в ней не было — а между тем это единственное,
# по чему видно, что оповещения ещё работают. Задача мониторинга могла
# умереть с исключением, и бот продолжал отвечать на команды как ни в чём
# не бывало: тревоги просто переставали приходить.
#
# Отметка лежит и в памяти (для /stats и сторожа внутри процесса), и файлом
# на диске — оттуда её читает healthcheck контейнера, которому в процесс
# не заглянуть.

# Путь к отметке — один на всех: его же читает проверка HEALTHCHECK,
# которая работает отдельным процессом и в память бота не заглядывает.
HEARTBEAT_FILE = health.HEARTBEAT_FILE


def _touch_heartbeat() -> None:
    """Отмечает виток цикла. Сбой записи файла не должен ронять цикл."""
    _stats["heartbeat"] = int(time.time())
    try:
        path = Path(HEARTBEAT_FILE)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(str(_stats["heartbeat"]), encoding="utf-8")
    except OSError as exc:
        log.debug("Отметка о жизни не записана: %s", exc)


def mark_alive() -> None:
    """Считать цикл живым прямо сейчас.

    Нужно сторожу: заново поднятый цикл сначала делает прогревочный
    проход по всем источникам, и без этой отметки он был бы признан
    мёртвым ещё до первого витка.
    """
    _touch_heartbeat()


def silence_limit() -> int:
    """Сколько секунд молчания цикла считать поломкой.

    Три интервала опроса: один цикл может затянуться на медленных
    источниках, два подряд — уже не случайность. Нижняя граница
    в пять минут защищает от ложных срабатываний при малом интервале.
    """
    return max(300, config.POLL_INTERVAL * 3)


def alive(now: float | None = None) -> tuple[bool, int]:
    """Жив ли фоновый цикл и сколько секунд назад подавал признаки.

    До первого витка возвращает «жив»: бот только поднялся, и поднимать
    тревогу из-за незавершённого первого прохода незачем.
    """
    moment = now if now is not None else time.time()
    beat = int(_stats["heartbeat"])
    if not beat:
        return True, 0
    quiet_for = int(moment - beat)
    return quiet_for <= silence_limit(), quiet_for


# --------------------------------------------------------------------------
#  Погода: пора ли отправлять
# --------------------------------------------------------------------------

def weather_due(user: dict[str, Any], now_ts: int, now: datetime) -> bool:
    mode = user.get("weather_mode", "interval")
    if mode == "interval":
        interval = int(user.get("weather_interval") or 0)
        if interval <= 0:
            return False
        return now_ts - int(user.get("last_weather") or 0) >= interval * 60

    target = str(user.get("weather_time") or "08:00")
    try:
        hour, minute = (int(part) for part in target.split(":"))
    except ValueError:
        return False
    if user.get("last_fixed_date") == now.strftime("%Y-%m-%d"):
        return False
    # Сравниваем по окну, а не по точной минуте: цикл может длиться дольше минуты.
    return (now.hour, now.minute) >= (hour, minute)


# --------------------------------------------------------------------------
#  Геокодирование «хвостов» из старой базы
# --------------------------------------------------------------------------

async def backfill_geocode(session: aiohttp.ClientSession) -> None:
    """Дозаполняет город/улицу/дом у локаций, перенесённых из версий 2.x."""
    pending: list[dict[str, Any]] = []
    for user in storage.users().values():
        for loc in user.get("locs") or []:
            if loc.get("city") or not (loc.get("lat") or loc.get("lon")):
                continue
            pending.append(loc)
    if not pending:
        return

    log.info("Дозаполняю адреса для %d локаций из старой базы", len(pending))
    for loc in pending:
        info = await geocode.reverse(session, float(loc["lat"]), float(loc["lon"]))
        for key in ("street", "house", "city", "district", "region"):
            if info.get(key):
                loc[key] = info[key]
        if loc.get("name", "").replace(" ", "").replace(",", "").replace(".", "").isdigit():
            loc["name"] = info.get("name") or loc["name"]
    await storage.save()
    log.info("Адреса дозаполнены")


# --------------------------------------------------------------------------
#  Рассылка одному пользователю
# --------------------------------------------------------------------------

async def dispatch_user(
    session: aiohttp.ClientSession,
    uid: str,
    user: dict[str, Any],
    analyses: list[Analysis],
    now_ts: int,
    now: datetime,
) -> bool:
    """Готовит и отправляет сообщения одному пользователю. True — база изменена."""
    locations = user.get("locs") or []
    if not locations:
        return False

    messages = plan_alerts(
        locations,
        user.get("settings") or {},
        analyses,
        config.CLUSTER_RADIUS_M,
        config.DEFAULT_CITY,
    )

    # Антиспам: несколько источников часто сообщают об одном событии
    if features.enabled("antispam"):
        messages = quiet.merge_similar(messages)

    # Местное время ЭТОГО человека, а не сервера: тихие часы и «погода
    # в 8:00» должны означать восемь утра там, где он живёт. now приходит
    # в UTC — общий для цикла якорь, от него считается каждый пояс.
    moment = timezones.local_now(user, now)
    categories = {name for item in analyses for name in item.categories}

    sent = 0
    # Рассылаемые сообщения идут без кнопок вовсе (с 4.8.4.4). Раньше под
    # последним висело «🏠 В главное меню»: тревога уводила в меню, хотя
    # человек читал её, а не собирался настраивать бота. Меню и так всегда
    # рядом — закреплённой кнопкой «☰ Меню» под полем ввода.
    outgoing: list[str] = []
    for _kind, text in messages:
        # Повтор того же события по той же локации не отправляем
        if features.enabled("antispam") and quiet.deliveries.already(uid, "all", text):
            continue

        # Тихие часы придерживают несрочное; военные и МЧС проходят всегда
        if features.enabled("quiet_hours") and quiet.should_hold(categories, user, moment):
            quiet.hold(uid, text)
            # Придержанное считается доставленным сразу: оно уже в очереди,
            # и второй экземпляр той же тревоги следующим циклом лёг бы
            # рядом с первым.
            if features.enabled("antispam"):
                quiet.deliveries.remember(uid, "all", text)
            continue

        outgoing.append(text)

    for text in outgoing:
        if await send_html(uid, text):
            sent += 1
            # Копия на привязанные ВК и MAX (5.6). Фоновой задачей: зеркало
            # не задерживает Telegram и не может уронить цикл оповещений.
            mirror.alert(uid, text)
            # Отдельно от общего счётчика: в «alerts» попадает и погода,
            # а метрике задержки нужны только оповещения о событиях.
            _stats["delivered"] += 1
            # Отметка о доставке ставится ПОСЛЕ отправки. До 4.9.8.14 она
            # шла раньше, и одной сетевой икоты хватало, чтобы тревога
            # пропала: отправка не удалась, а повтор был уже запрещён
            # на двенадцать часов вперёд.
            if features.enabled("antispam"):
                quiet.deliveries.remember(uid, "all", text)
        else:
            log.warning(
                "Тревога для %s не ушла — повторю в следующем цикле", uid
            )
        await asyncio.sleep(0.3)

    # Доставку отмечаем только когда что-то действительно ушло: журнал
    # обязан отражать полученное, а не запланированное. Иначе человек
    # увидит в нём тревогу, которой не приходило.
    if sent and features.enabled("history"):
        from .db import repo as history_repo

        for analysis in analyses:
            event_id = getattr(analysis, "event_id", None)
            if not event_id:
                continue
            try:
                await history_repo.record_delivery(event_id, uid, None)
            except Exception:  # noqa: BLE001
                log.debug("Доставка не записана в журнал")

    changed = False
    if features.enabled("weather") and weather_due(user, now_ts, moment):
        clusters = cluster_locations(locations, config.CLUSTER_RADIUS_M)
        for cluster in clusters:
            lat, lon = cluster_center(cluster)
            data = await weather.fetch(session, lat, lon, lang=i18n.language_of(user))
            await weather.deliver(uid, data, cluster_title(cluster), None, user)
            sent += 1
            await asyncio.sleep(0.2)
        user["last_weather"] = now_ts
        if user.get("weather_mode") == "time":
            user["last_fixed_date"] = now.strftime("%Y-%m-%d")
        changed = True

    _stats["alerts"] += sent
    return changed


# --------------------------------------------------------------------------
#  Цикл
# --------------------------------------------------------------------------

# Завершившиеся события копятся до утренней и вечерней сводки: тревожить
# ими сразу бессмысленно, а знать о них полезно.
_recap_pool: list[Analysis] = []
_recap_sent: dict[str, str] = {}

RECAP_HOURS = (9, 20)


def collect_recap(analyses: list[Analysis]) -> None:
    for item in analyses:
        if item.historical and item.relevant:
            _recap_pool.append(item)
    # Держим разумный объём: сводка за сутки, а не за месяц
    del _recap_pool[:-100]


def recap_due(now: datetime) -> str | None:
    """Пора ли отправлять сводку. Возвращает метку периода или None."""
    if not _recap_pool:
        return None
    for hour in RECAP_HOURS:
        if now.hour == hour:
            marker = f"{now:%Y-%m-%d}-{hour}"
            if _recap_sent.get("last") != marker:
                return marker
    return None


async def send_recap(now: datetime) -> None:
    """Утренняя и вечерняя сводка по тому, что уже произошло."""
    marker = recap_due(now)
    if marker is None:
        return

    _recap_sent["last"] = marker
    period = "за ночь" if now.hour < 12 else "за день"

    delivered = 0
    for uid, user in list(storage.users().items()):
        locations = user.get("locs") or []
        if not locations:
            continue
        enabled = {key for key, value in (user.get("settings") or {}).items() if value}

        relevant = [
            item for item in _recap_pool
            if (set(item.categories) & enabled)
            and any(geo_matches(item, loc) for loc in locations)
        ]
        if not relevant:
            continue

        hint = str(locations[0].get("city") or "")
        text = build_recap(relevant, period, hint)
        if text and await send_html(uid, text):
            delivered += 1
        await asyncio.sleep(0.3)

    log.info("Сводка %s разослана: %d получателей", period, delivered)
    _recap_pool.clear()


async def send_digests(now: datetime) -> None:
    """Новостные подборки в выбранное пользователем время."""
    if not features.enabled("digest") or not _digest_pool:
        return

    with profiling.measure("digest"):
        await _send_digests_inner(now)


async def _send_digests_inner(now: datetime) -> None:
    """Собственно рассылка. Вынесена, чтобы замер не оборачивал холостые проходы."""
    delivered = 0
    for uid, user in list(storage.users().items()):
        subscription = digest.subscription_of(user)
        local = timezones.local_now(user, now)
        marker = digest.due(subscription, local)
        if marker is None:
            continue

        locations = user.get("locs") or []
        city = str(locations[0].get("city") or "") if locations else ""
        summaries = await digest.summaries_for(_digest_pool, subscription)
        text = digest.build(_digest_pool, subscription, local, city, summaries)
        if not text:
            continue

        if await send_html(uid, text):
            subscription.last_sent = marker
            digest.store_subscription(user, subscription)
            delivered += 1
        await asyncio.sleep(0.3)

    if delivered:
        await storage.save()
        log.info("Подборки разосланы: %d получателей", delivered)


def collect_digest(items: list[Any]) -> None:
    """Копит материал для подборок.

    Берёт СЫРЫЕ сообщения источников, а не разобранные ИИ. Это главное
    отличие от тревог, и из-за его отсутствия подборки не приходили вообще.

    Разбор ИИ отвечает на вопрос «это тревога?»: матч «Спартака», выход
    игры и курс доллара он честно помечает как нерелевантные — они и не
    тревога. Дальше такие сообщения отбрасывались дважды: предфильтром
    до модели и отбором `relevant` после. В пул подборок не доходило
    ничего, кроме аварий ЖКХ, а у них своей тематики в списке нет.

    Для подборки важен не уровень опасности, а тематика. Поэтому здесь
    свой отбор — по ключевым словам темы, независимо от того, что решил
    разбор тревог.
    """
    if not features.enabled("digest"):
        return

    added = 0
    for item in items:
        text = getattr(item, "text", "") or ""
        if not text:
            continue
        topic = digest.topic_of(text)
        if topic is None:
            continue
        _digest_pool.append(
            digest.Entry(
                topic=topic,
                summary=text.strip()[:220],
                source=getattr(item, "source", ""),
                link=getattr(item, "link", ""),
            )
        )
        added += 1

    if added:
        log.info("В подборки добавлено: %d (в пуле %d)", added, len(_digest_pool))
        asyncio.create_task(_shorten_pool_links())
    del _digest_pool[:-300]


_digest_pool: list["digest.Entry"] = []


def digest_state() -> dict[str, Any]:
    """Что сейчас в пуле подборок.

    Нужна для диагностики: подборки не приходили неделями, и понять это
    можно было только чтением кода — снаружи «пусто» и «сломано»
    выглядят одинаково.
    """
    by_topic: dict[str, int] = {}
    for entry in _digest_pool:
        by_topic[entry.topic] = by_topic.get(entry.topic, 0) + 1
    return {
        "total": len(_digest_pool),
        "topics": by_topic,
        "enabled": features.enabled("digest"),
    }


async def _shorten_pool_links() -> None:
    """Заменяет ссылки в накопленном материале короткими.

    Отдельной задачей, а не внутри разбора: обращение к базе не должно
    задерживать цикл, а если сокращение не удалось, подборка обязана уйти
    с исходными ссылками — длинная ссылка лучше отсутствующей.
    """
    if not features.enabled("link_shortener") or not shortener.enabled():
        return

    from .db import repo

    for entry in _digest_pool:
        if not entry.link or entry.link.startswith(shortener.base_url()):
            continue
        if not shortener.valid(entry.link):
            continue
        code = shortener.code_for(entry.link)
        try:
            await repo.save_short_link(code, entry.link)
        except Exception:  # noqa: BLE001
            log.debug("Сокращение ссылки не удалось, оставляю исходную")
            continue
        entry.link = shortener.short_url(code)


HELD_META_KEY = "quiet_held"


async def load_held() -> int:
    """Поднимает придержанное тихими часами из базы (с 4.9.8.14)."""
    if not features.enabled("quiet_hours"):
        return 0
    from .db import repo

    try:
        rows = await repo.get_meta(HELD_META_KEY, [])
    except Exception:  # noqa: BLE001
        log.warning("Придержанные оповещения не прочитаны из базы")
        return 0
    restored = quiet.restore(rows)
    if restored:
        log.info("Восстановлено придержанных оповещений: %d", restored)
    return restored


async def save_held() -> None:
    """Пишет очередь в базу, если она менялась.

    Раз за цикл, а не на каждое придержанное сообщение: очередь нужна
    для того, чтобы пережить перезапуск, и лишняя запись в базу на слабом
    железе дороже, чем потеря нескольких минут в редком случае падения.
    """
    if not quiet.dirty():
        return
    from .db import repo

    try:
        await repo.set_meta(HELD_META_KEY, quiet.snapshot())
    except Exception:  # noqa: BLE001
        log.warning("Придержанные оповещения не сохранены")
        return
    quiet.mark_saved()


async def release_held(now: datetime) -> None:
    """Отдаёт то, что придержали тихие часы."""
    if not features.enabled("quiet_hours") or not quiet.held_count():
        return
    for uid, user in list(storage.users().items()):
        for item in quiet.release_items(uid, user, timezones.local_now(user, now)):
            if not await send_html(uid, item.text):
                # Не ушло — возвращаем в очередь: у придержанного нет
                # второго источника, событие давно вымылось из `seen`.
                # Счётчик попыток не даёт этому длиться вечно.
                quiet.hold(uid, item.text, created=item.created,
                           attempts=item.attempts + 1)
            else:
                # Копия на привязанные ВК и MAX — как у тревоги, ушедшей
                # сразу. До 5.6.2 придержанное туда не доходило вовсе.
                mirror.alert(uid, item.text)
            await asyncio.sleep(0.2)
    await save_held()


async def repeat_sos() -> None:
    """Повторяет активные сигналы SOS, пока отправитель не дал отбой."""
    if not features.enabled("sos"):
        return

    for alert in sos.due_alerts():
        owner = storage.get_user(alert.owner)
        if owner is None:
            sos.stop_alert(alert.owner)
            continue

        alert.repeats += 1
        alert.last_sent = time.time()
        text = sos.build_alert(
            owner.get("username") or f"ID {alert.owner}",
            "",
            alert.lat,
            alert.lon,
            alert.address,
            alert.note,
            repeat=alert.repeats,
        )
        for contact in sos.confirmed_contacts(owner):
            await send_html(contact.key, text)
        log.info("Повтор сигнала SOS от %s (%d)", alert.owner, alert.repeats)

        if alert.repeats >= sos.MAX_REPEATS:
            sos.stop_alert(alert.owner)
            await send_html(
                alert.owner,
                "🆘 Повторы сигнала прекращены — достигнут предел. "
                "Нажмите SOS заново, если помощь всё ещё нужна.",
            )


async def subscribed_topics() -> set[str]:
    """Тематики, на которые кто-то подписан прямо сейчас.

    Опрашивать ленту про кино, когда её никто не читает, — впустую жечь
    запросы на слабом сервере. Набор пересчитывается каждый цикл: он
    дешёвый, а подписки меняются.
    """
    if not features.enabled("digest"):
        return set()
    wanted: set[str] = set()
    for user in storage.users().values():
        subscription = digest.subscription_of(user)
        wanted.update(subscription.allowed_topics())
    return wanted


async def cycle(session: aiohttp.ClientSession, *, warmup: bool = False) -> None:
    # Флаги источников теперь действительно отключают источник, а не только
    # значатся в списке возможностей. Выключенный тумблер, который ничего
    # не делает, хуже отсутствующего: на него надеются.
    channels = list(storage.channels()) if features.enabled("source_telegram") else []
    feeds = list(storage.rss_feeds()) if features.enabled("source_rss") else []
    vk_extra: list[str] = []

    # Тематические ленты (игры, спорт, наука и прочее) добавляются к городским
    # источникам, а не заменяют их: городская часть системы важнее и должна
    # работать, даже если тематические ленты недоступны.
    thematic_channels, thematic_feeds, vk_extra = presets.thematic_sources(
        await subscribed_topics()
    )
    channels.extend(thematic_channels)
    feeds.extend(thematic_feeds)
    channels = list(dict.fromkeys(channels))
    feeds = list(dict.fromkeys(feeds))

    with profiling.measure("sources"):
        items = await sources.collect(
            session,
            channels,
            feeds,
            seen,
            config.MSG_PER_SOURCE,
            warmup=warmup,
        )
    # ВКонтакте читается тем же циклом: сообщества добавляются как источники,
    # а разбор дальше общий для всех типов.
    if features.enabled("source_vk"):
        vk_token = secrets.get("VK_SERVICE_TOKEN")
        groups = list(dict.fromkeys(list(storage.vk_groups()) + vk_extra))
        if vk_token and groups:
            with profiling.measure("vk"):
                for group in groups:
                    fetched = await sources.fetch_vk(
                        session, group, vk_token, config.MSG_PER_SOURCE
                    )
                    for entry in fetched:
                        if seen.add(entry.text):
                            items.append(entry)
                    await asyncio.sleep(0.4)
        elif groups and not vk_token:
            log.info("Источники VK включены, но VK_SERVICE_TOKEN не задан")

    if warmup:
        log.info("Первый проход: %d сообщений помечены прочитанными", len(seen))
        return

    _stats["cycles"] += 1
    _stats["items"] += len(items)
    _stats["last_cycle"] = int(time.time())

    analyses: list[Analysis] = []
    if items:
        payload = [(item.text, item.source, item.link) for item in items]
        try:
            if features.enabled("ai_analysis"):
                with profiling.measure("ai"):
                    parsed = await ai.analyze_batch(payload)
            else:
                # Флаг выключен — работаем на эвристике, как и обещано
                # в описании возможности. Оповещения продолжают приходить,
                # качество разбора ниже: это осознанный размен, а не отказ.
                from .matching import heuristic_analysis

                parsed = [
                    heuristic_analysis(text, source=source, link=link)
                    for text, source, link in payload
                ]
        except Exception:  # noqa: BLE001
            log.exception("Пакетный разбор сообщений не удался")
            parsed = []
        analyses = [analysis for analysis in parsed if analysis.relevant]

        # Журнал событий заполняется здесь. Функции store_event
        # и record_delivery были написаны давно и не вызывались ниоткуда:
        # раздел «Журнал» открывался и всегда показывал пусто, даже когда
        # тревоги приходили. Идентификаторы кладём в само событие, чтобы
        # рассылка знала, что отмечать доставленным.
        if features.enabled("history"):
            from .db import repo as history_repo

            for analysis in analyses:
                try:
                    analysis.event_id = await history_repo.store_event(analysis)
                except Exception:  # noqa: BLE001
                    log.debug("Событие не сохранилось в журнал")

        collect_recap(analyses)
        # Подборки наполняются из сырых сообщений: разбор ИИ отсеивает
        # всё, что не тревога, а для подборок это как раз материал.
        collect_digest(items)
        counters = ai.counters()
        log.info(
            "Новых сообщений: %d, значимых: %d | запросов к ИИ: %d, "
            "отсеяно фильтром: %d, из кэша: %d, эвристикой: %d",
            len(items), len(analyses), counters["requests"],
            counters["prefiltered"], counters["cached"], counters["heuristic"],
        )

    now_ts = int(time.time())
    # Якорь цикла — UTC. Местное время каждого получателя считается
    # от него внутри dispatch_user: пользователи живут в разных поясах.
    now = datetime.now(timezone.utc)
    changed = False
    delivered_before = _stats["delivered"]
    with profiling.measure("dispatch"):
        for uid, user in list(storage.users().items()):
            try:
                if await dispatch_user(session, uid, user, analyses, now_ts, now):
                    changed = True
            except Exception:  # noqa: BLE001
                log.exception("Ошибка рассылки пользователю %s", uid)
    # Задержку пишем, только если в этом цикле ушло хоть одно оповещение:
    # иначе в метрику попали бы события, которые никому не доставлялись.
    if analyses and _stats["delivered"] > delivered_before:
        published = {item.text: item.published for item in items if item.published}
        record_latency(analyses, published, time.time())
    if changed:
        with profiling.measure("save"):
            await storage.save()


async def _notify_admins(text: str) -> None:
    """Письмо администраторам — о том, что не требует решения сейчас.

    Ночные отчёты (обслуживание базы, проверка источников) адресованы
    тем, кто может починить, — администраторам и суперадминистратору.
    Модераторам хватит кнопки в разделе источников: письма каждое утро
    превращаются в шум. Ошибка отправки не будит никого посреди ночи:
    суть и так в журнале.
    """
    for uid, user in list(storage.users().items()):
        if not roles.is_admin(user.get("role")) or user.get("blocked"):
            continue
        try:
            await send_html(uid, text)
        except Exception:  # noqa: BLE001
            log.warning("Ночной отчёт не доставлен: %s", uid)


# Сколько сбоев цикла подряд считать поломкой самой HTTP-сессии.
# Единичные ошибки — обычное дело: источник ответил мусором, база моргнула.
# Три подряд означают, что сломалось общее — например, коннектор сессии,
# который прежде жил до конца процесса и не восстанавливался никогда.
FAILURES_BEFORE_RESET = 3


async def run() -> None:
    """Фоновый цикл. Сам поднимается после сбоя и сам об этом сообщает.

    До 4.9.8.14 вся работа шла внутри одного `async with ClientSession`,
    а прогревочные проходы стояли ВНЕ `try`. Любое исключение оттуда
    завершало задачу навсегда: бот продолжал отвечать на команды, тревоги
    молча прекращались, и в журнале оставалась одна строка.
    """
    while True:
        try:
            await _run_once()
        except asyncio.CancelledError:
            raise
        except Exception:  # noqa: BLE001
            _stats["restarts"] += 1
            log.exception(
                "Фоновый цикл остановлен (перезапуск %d), поднимаю заново",
                _stats["restarts"],
            )
            await asyncio.sleep(30.0)


async def _run_once() -> None:
    """Один заход: своя HTTP-сессия и цикл поверх неё."""
    _touch_heartbeat()
    timeout = aiohttp.ClientTimeout(total=30)
    headers = {"User-Agent": config.USER_AGENT, "Accept-Language": "ru,en;q=0.8"}
    async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
        try:
            await backfill_geocode(session)
        except Exception:  # noqa: BLE001
            log.exception("Дозаполнение адресов не удалось")

        try:
            await load_held()
        except Exception:  # noqa: BLE001
            log.exception("Придержанные оповещения не восстановлены")

        try:
            await cycle(session, warmup=True)
        except Exception:  # noqa: BLE001
            # Прогрев не смертелен: без него первый рабочий проход просто
            # увидит ленту непрочитанной. Ронять из-за этого весь
            # мониторинг нельзя.
            log.exception("Прогревочный проход не удался")
        _touch_heartbeat()

        paused = False
        failures = 0
        while True:
            started = time.monotonic()
            _touch_heartbeat()

            # Режим обслуживания: опрос источников и рассылки остановлены,
            # но цикл продолжает крутиться вхолостую — чтобы выход из режима
            # не требовал перезапуска контейнера. SOS не трогаем: он идёт
            # напрямую по нажатию кнопки, а не отсюда.
            if features.enabled("maintenance"):
                if not paused:
                    log.warning("Режим обслуживания: фоновый цикл остановлен")
                    paused = True
                await asyncio.sleep(15.0)
                continue
            if paused:
                log.info("Режим обслуживания снят: цикл возобновлён")
                paused = False
                # Первый проход после паузы — прогревочный: за время работ
                # источники накопили сообщения, и рассылать их скопом уже
                # поздно, событие в прошлом тревогой не является.
                try:
                    await cycle(session, warmup=True)
                except Exception:  # noqa: BLE001
                    log.exception("Прогревочный проход после работ не удался")

            try:
                now_moment = datetime.now()

                # Уборка рабочего каталога медиа. Здесь же, а не отдельной
                # задачей, по той же причине, что и копия: лишняя корутина
                # на одноплатнике дороже проверки раз в цикл. Успешная
                # отправка убирает за собой сама — сюда попадает то, что
                # осталось от прерванных загрузок.
                try:
                    media.sweep(config.MEDIA_DIR)
                    # Раздача крупных файлов живёт по своему сроку: сутки
                    # с момента выдачи ссылки, плюс общий бюджет места.
                    filedrop.purge()
                except Exception:  # noqa: BLE001
                    log.exception("Уборка рабочего каталога не удалась")

                # Копия по расписанию. Внутри цикла, а не отдельной задачей:
                # так она не запустится во время работ или при остановленном
                # мониторинге — снимать копию наполовину поднятой системы
                # незачем.
                try:
                    saved = await backup.run_scheduled(now_moment)
                    if saved:
                        log.info("Резервная копия создана: %s", saved)
                except Exception:  # noqa: BLE001
                    log.exception("Копия по расписанию не удалась")

                # Обслуживание базы — после копии, а не до: если сжатие
                # что-то испортит, копия уже снята со здоровой базы.
                # SQLite не отдаёт место после DELETE, поэтому чистка
                # истории без VACUUM не освобождает ни байта.
                try:
                    tidied = await dbcare.run_scheduled(now_moment)
                    if tidied:
                        log.info("Обслуживание базы: %s", tidied)
                        # Отчёт о чистке закрывает последний кусок пункта
                        # 4.9.5 дорожной карты: работа шла молча, и узнать,
                        # сколько освобождено, можно было только в /perf.
                        await _notify_admins(
                            "🗄 <b>Обслуживание базы</b>\n" + esc(tidied)
                        )
                except Exception:  # noqa: BLE001
                    log.exception("Обслуживание базы не удалось")

                # Диски — тем же ночным письмом (с 4.9.5.4). Сюда входит
                # и внешний носитель музыки, если каталог вынесен
                # командой mount: у него своя точка и свои проценты.
                # Письмо уходит только когда место реально тратится:
                # «диски в порядке» каждое утро — шум.
                if features.enabled("disk_watch"):
                    try:
                        report = music.disk_report(
                            [".", music.DIRECTORY, config.MEDIA_DIR]
                        )
                        if report and "⚠️" in report:
                            log.warning("Диск заполнен: см. ночной отчёт")
                            await _notify_admins(report)
                    except Exception:  # noqa: BLE001
                        log.exception("Отчёт о дисках не удался")

                # Проверка источников по расписанию — тем же ночным
                # механизмом, что копии и база. Письмо уходит только
                # когда есть мёртвые или затихшие (с 4.9.5).
                if features.enabled("source_autocheck"):
                    try:
                        letter = await sourcecheck.run_scheduled(now_moment)
                        if letter:
                            log.info("Проверка источников нашла проблемы")
                            await _notify_admins(letter)
                    except Exception:  # noqa: BLE001
                        log.exception("Проверка источников по расписанию не удалась")

                await repeat_sos()
                await release_held(now_moment)
                await send_recap(now_moment)
                await send_digests(now_moment)
                await cycle(session)
                # Придержанное этим проходом закрепляем сразу: очередь
                # нужна ровно для того, чтобы пережить перезапуск.
                await save_held()
                failures = 0
            except asyncio.CancelledError:
                raise
            except Exception:  # noqa: BLE001
                failures += 1
                log.exception("Сбой цикла мониторинга (подряд: %d)", failures)
                if failures >= FAILURES_BEFORE_RESET:
                    # Выходим наружу: внешний круг пересоздаст HTTP-сессию.
                    log.error(
                        "Сбоев подряд %d — пересоздаю сетевую сессию", failures
                    )
                    return
            elapsed = time.monotonic() - started
            await asyncio.sleep(max(15.0, config.POLL_INTERVAL - elapsed))
RADAR_FILE_98
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/health.py"
cat > "radar/health.py" <<'RADAR_FILE_99'
"""Проверка жизни бота для HEALTHCHECK контейнера.

Запускается снаружи процесса — `python -m radar.health` — и потому смотрит
не в память, а на файл отметки, который фоновый цикл переписывает на каждом
витке. Смысл в том, что живой процесс и работающий мониторинг — разные вещи:
бот может исправно отвечать на команды, когда тревоги уже не приходят,
и никакая проверка «процесс запущен» этого не покажет.

Нездоровый контейнер сам по себе не перезапускается — за это отвечает сторож
внутри процесса. Проверка нужна, чтобы состояние было видно снаружи:
в `docker ps`, в панели и в чужом мониторинге.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import sys
import time
from pathlib import Path

from . import config

HEARTBEAT_FILE = "data/heartbeat"

# Запас поверх предела молчания: проверка не должна срабатывать раньше
# сторожа, иначе контейнер будет числиться больным ровно в тот момент,
# когда цикл уже поднимается заново.
GRACE = 120


def limit() -> int:
    return max(300, config.POLL_INTERVAL * 3) + GRACE


def check(now: float | None = None) -> tuple[bool, str]:
    """Жив ли фоновый цикл. Возвращает (здоров, объяснение)."""
    moment = now if now is not None else time.time()
    path = Path(HEARTBEAT_FILE)
    try:
        beat = int(path.read_text(encoding="utf-8").strip() or 0)
    except (OSError, ValueError):
        # Файла нет — бот только поднимается. Считать это поломкой нельзя:
        # первый проход по источникам занимает до минуты.
        return True, "отметки ещё нет, бот запускается"

    silent = int(moment - beat)
    if silent > limit():
        return False, f"цикл молчит {silent} с при пределе {limit()} с"
    return True, f"цикл отвечал {silent} с назад"


def main() -> int:
    healthy, reason = check()
    print(reason)
    return 0 if healthy else 1


if __name__ == "__main__":
    sys.exit(main())
