cat > "radar/moderation.py" <<'RADAR_FILE_109'
"""Правила модерации групп: решение отдельно от Telegram.

Здесь нет ни aiogram, ни сети — только «текст плюс состояние автора
плюс настройки чата» → решение. Так правила можно прогнать таблицей
случаев в офлайн-тестах, а ошибка в них обнаруживается на тесте,
а не на живом человеке, которого забанили ни за что.

Почему решение возвращается, а не исполняется: удаление, мут и бан —
разные права в Telegram, и у бота их может не быть. Исполнитель
(`radar/handlers/group.py`) разбирается с правами и отказами, правила
об этом не знают вовсе.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import re
import time
from dataclasses import dataclass, field

# Действия по возрастанию строгости.
NONE = "none"
DELETE = "delete"
WARN = "warn"
MUTE = "mute"
BAN = "ban"

# Ссылка считается спамом начиная с этого уровня проверки ссылок
# (multitool/linkcheck). «attention» не трогаем: там слишком много
# обычных ссылок, и удалять их значило бы мешать разговору.
SPAM_LEVELS = ("suspect", "danger")

_URL_RE = re.compile(r"https?://\S+|\bt\.me/\S+|\b[\w-]+\.(?:ru|com|net|org|io)\b",
                     re.I)


@dataclass
class Settings:
    """Настройки одного чата. Значения по умолчанию — осознанно мягкие:
    свежеподключённый бот не должен начать с раздачи банов."""

    delete_spam_links: bool = True
    links_from_newcomers: bool = True   # новичкам ссылки нельзя вовсе
    stopwords: list[str] = field(default_factory=list)
    antiflood: bool = True
    flood_messages: int = 6             # столько сообщений
    flood_seconds: int = 10             # за столько секунд — флуд
    warns_before_mute: int = 3
    mute_minutes: int = 60
    warns_before_ban: int = 5
    newcomer_hours: int = 24            # сколько человек считается новичком
    captcha_minutes: int = 5            # сколько ждать нажатия «Я не бот» (5.9.4)


@dataclass
class Author:
    """Что известно об авторе сообщения на момент решения."""

    user_id: int
    joined_ago_hours: float = 999.0     # давно в чате — не новичок
    warns: int = 0
    is_admin: bool = False

    @property
    def newcomer(self) -> bool:
        return self.joined_ago_hours < 24.0


@dataclass
class Decision:
    """Что сделать и почему. Причина уходит в журнал и в сообщение чату:
    молчаливое удаление выглядит как поломка чата, а не как модерация."""

    action: str = NONE
    reason: str = ""
    delete_message: bool = False

    @property
    def acts(self) -> bool:
        return self.action != NONE or self.delete_message


def extract_urls(text: str) -> list[str]:
    """Ссылки из текста — включая t.me и голые домены: спам чаще всего
    приходит именно так, без схемы."""
    return _URL_RE.findall(text or "")


def _link_level(url: str) -> str:
    """Уровень ссылки по общей проверке проекта. Вторую реализацию
    заводить нечего — она уже написана и покрыта тестами."""
    try:
        from multitool.linkcheck.analyze import analyze

        return analyze(url).level
    except Exception:  # noqa: BLE001
        # Разбор ссылки не должен ронять модерацию: не смогли — не судим.
        return "ok"


class FloodTracker:
    """Счётчик частоты сообщений. В памяти намеренно: переживать
    перезапуск ему незачем, а таблица ради десяти секунд — это запись
    на диск на каждое сообщение чата."""

    def __init__(self) -> None:
        self._seen: dict[tuple[int, int], list[float]] = {}

    def hit(self, chat_id: int, user_id: int, window: int,
            now: float | None = None) -> int:
        moment = time.monotonic() if now is None else now
        key = (chat_id, user_id)
        recent = [stamp for stamp in self._seen.get(key, [])
                  if moment - stamp < window]
        recent.append(moment)
        self._seen[key] = recent
        return len(recent)

    def forget(self, chat_id: int, user_id: int) -> None:
        self._seen.pop((chat_id, user_id), None)


def decide(text: str, author: Author, settings: Settings,
           flood_count: int = 0) -> Decision:
    """Одно решение по одному сообщению.

    Порядок проверок — от дешёвых к дорогим и от мягких к строгим.
    Администраторы чата не модерируются вовсе: бот не должен спорить
    с теми, кто его назначил.
    """
    if author.is_admin:
        return Decision()

    lowered = (text or "").lower()

    # Стоп-слова — самое дешёвое и самое однозначное.
    for word in settings.stopwords:
        needle = word.strip().lower()
        if needle and needle in lowered:
            return _escalate(author, settings,
                             f"стоп-слово «{word.strip()}»", delete=True)

    # Ссылки.
    urls = extract_urls(text)
    if urls:
        if settings.links_from_newcomers and author.newcomer:
            return _escalate(author, settings,
                             "ссылка от новичка", delete=True)
        if settings.delete_spam_links:
            for url in urls:
                if _link_level(url) in SPAM_LEVELS:
                    return _escalate(author, settings,
                                     "подозрительная ссылка", delete=True)

    # Флуд — считается снаружи, здесь только порог.
    if settings.antiflood and flood_count > settings.flood_messages:
        return _escalate(author, settings, "флуд", delete=False)

    return Decision()


def _escalate(author: Author, settings: Settings, reason: str,
              delete: bool) -> Decision:
    """Лестница наказаний. Считаем по УЖЕ накопленным предупреждениям
    плюс текущее: иначе первое нарушение выглядело бы как нулевое."""
    warns = author.warns + 1

    if warns >= settings.warns_before_ban:
        return Decision(BAN, f"{reason}; предупреждений: {warns}", delete)
    if warns >= settings.warns_before_mute:
        return Decision(MUTE, f"{reason}; предупреждений: {warns}", delete)
    return Decision(WARN, f"{reason}; предупреждение {warns}", delete)


def describe(decision: Decision, settings: Settings) -> str:
    """Человеческая формулировка для сообщения в чат."""
    if decision.action == WARN:
        return f"⚠️ Предупреждение: {decision.reason}"
    if decision.action == MUTE:
        return (f"🔇 Ограничение на {settings.mute_minutes} мин: "
                f"{decision.reason}")
    if decision.action == BAN:
        return f"⛔️ Блокировка: {decision.reason}"
    if decision.delete_message:
        return f"🧹 Удалено: {decision.reason}"
    return ""
RADAR_FILE_109
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/chatlink.py"
cat > "radar/chatlink.py" <<'RADAR_FILE_110'
"""Ссылка на группу, где бот работает модератором.

Зачем отдельный модуль: ссылка нужна и боту, и веб-панели, а правило
получения у неё нетривиальное и ошибиться в нём дорого.

Порядок намеренно такой:

1. **Публичное имя** (`@name`) — лучшая ссылка: не отзывается, понятна
   на вид, работает для всех.
2. **Существующая постоянная ссылка** чата — если она уже есть, берём
   её. Именно этого просил автор: ссылка владельца уже разослана людям,
   и подменять её нельзя.
3. **Своя дополнительная ссылка** — только если первых двух нет.
   Создаётся `createChatInviteLink`, а НЕ `exportChatInviteLink`:
   второй отзывает прежнюю постоянную ссылку, и все, кому её раздали
   раньше, остаются с нерабочей. Разница в одном вызове, цена ошибки —
   сломанные приглашения у живых людей.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import logging

log = logging.getLogger("radar.chatlink")

# Имя своей ссылки: по нему владелец в списке приглашений группы
# понимает, откуда она взялась.
LINK_TITLE = "Радар"

_cache: dict[int, str] = {}


def forget(chat_id: int) -> None:
    """Сбросить запомненную ссылку — например, когда бота выгнали."""
    _cache.pop(chat_id, None)


# --------------------------------------------------------------------------
#  Чаты для пользователей (с 4.9.9.2)
# --------------------------------------------------------------------------
#
# Ссылка приглашения, заданная суперадминистратором, до 4.9.9.2 была
# видна только в разделе «Чаты» у администрации — то есть тем, кто
# в группе и так состоит. Теперь чаты со своей ссылкой видны всем
# в главном меню кнопкой «💬 Наши чаты».
#
# Показываются только чаты со ссылкой, заданной руками. Ссылку, которую
# бот нашёл или создал сам, не публикуем: закрытая группа, куда бота
# просто добавили модерировать, не обязана становиться открытой для всех
# пользователей бота. Решение «показывать» — это ровно ручная ссылка.
#
# Меню собирается синхронно, в базу из него не сходить — поэтому список
# держится в памяти и обновляется при старте и при каждой правке ссылки.

_published: list[tuple[int, str, str]] = []


async def refresh_published() -> int:
    """Перечитывает чаты со своей ссылкой. Возвращает их число."""
    try:
        from .db import repo

        rows = await repo.chat_list()
    except Exception:  # noqa: BLE001
        log.debug("Список чатов для меню не прочитан", exc_info=True)
        return len(_published)

    fresh = [
        (int(row["chat_id"]), str(row.get("title") or ""), str(row.get("invite") or ""))
        for row in rows
        if valid_invite(str(row.get("invite") or ""))
    ]
    fresh.sort(key=lambda item: item[1].lower())
    _published[:] = fresh
    return len(_published)


def published() -> list[tuple[int, str, str]]:
    """Чаты для меню: (id, название, ссылка)."""
    return list(_published)


# Что считаем ссылкой на чат. Проверка нужна не от злого умысла —
# ссылку задаёт суперадминистратор, — а от опечатки: кнопка с мусором
# вместо адреса выглядит как поломка бота, а не как промах в поле.
_ALLOWED_PREFIXES = ("https://t.me/", "http://t.me/", "https://telegram.me/")


def valid_invite(link: str) -> bool:
    """Похоже ли это на ссылку Telegram."""
    value = (link or "").strip()
    if len(value) > 300 or " " in value:
        return False
    return value.startswith(_ALLOWED_PREFIXES)


async def manual_link(chat_id: int) -> str:
    """Ссылка, заданная руками через бота или панель (с 4.9.9.1).

    Импорт базы внутри: модуль зовут в том числе оттуда, где базы может
    не быть под рукой, и падать из-за ненайденной ссылки он не должен.
    """
    try:
        from .db import repo

        row = await repo.chat_get(chat_id)
    except Exception:  # noqa: BLE001
        log.debug("Ссылка чата %s не прочитана из базы", chat_id)
        return ""
    if row is None:
        return ""
    link = str(row.get("invite") or "")
    return link if valid_invite(link) else ""


async def link_for(chat_id: int, bot=None) -> tuple[bool, str]:
    """Ссылка на чат. Возвращает (получилось, ссылка или причина).

    Порядок: заданная руками, потом запомненная, потом добытая у Telegram.
    Ручная идёт первой намеренно — её задают как раз тогда, когда
    автоматическая не годится: закрытый чат, своя ссылка с ограничением
    по времени, приглашение с заявкой на вступление.
    """
    manual = await manual_link(chat_id)
    if manual:
        return True, manual

    if chat_id in _cache:
        return True, _cache[chat_id]

    if bot is None:
        from .tg import bot as default_bot

        bot = default_bot

    try:
        chat = await bot.get_chat(chat_id)
    except Exception as exc:  # noqa: BLE001
        log.info("Чат %s недоступен: %s", chat_id, exc)
        return False, "Чат недоступен: бот удалён из группы или потерял права."

    username = getattr(chat, "username", "") or ""
    if username:
        link = f"https://t.me/{username}"
        _cache[chat_id] = link
        return True, link

    existing = getattr(chat, "invite_link", "") or ""
    if existing:
        # Ссылка владельца уже существует — используем её, а не свою.
        _cache[chat_id] = existing
        return True, existing

    try:
        created = await bot.create_chat_invite_link(chat_id, name=LINK_TITLE)
    except Exception as exc:  # noqa: BLE001
        log.info("Ссылка для %s не создана: %s", chat_id, exc)
        return False, ("Ссылки нет, и создать её не удалось: нужно право "
                       "«Пригласительные ссылки» у бота в этой группе.")

    link = getattr(created, "invite_link", "") or ""
    if not link:
        return False, "Telegram не вернул ссылку."
    _cache[chat_id] = link
    return True, link
