cat > "radar/adminsock.py" <<'RADAR_FILE_119'
"""Канал управления в работающий процесс бота (с 5.9.3).

**Поломка, ради которой он нужен.** Командная строка запускается через
`docker exec` — это отдельный процесс рядом с ботом, а не он сам. До 5.9.3
`radarctl.sh features on digest` менял флаг в базе и в памяти этого короткого
процесса, а бот читает флаги из базы один раз при старте: возможность
не включалась до перезапуска. Хуже того, источники и пользователи лежат
в памяти бота целиком (`storage`), и бот при очередном сохранении затирал
правку, сделанную из консоли.

**Как устроено.** Бот слушает Unix-сокет `data/admin.sock` (права 600,
владелец — тот, кто запустил бота). Командная строка отправляет ему свои
аргументы, бот разбирает их тем же `radar.cli` и выполняет у себя — в той
же памяти, с той же базой, — а вывод и код возврата отдаёт обратно. Второй
реализации нет: сокет не знает ни одной команды, он лишь переносит строку
запуска. Если бот не запущен, сокета нет, и командная строка работает
с базой напрямую, как раньше.

Почему сокет, а не порт. Терминала сервера в веб-панели нет и не будет:
канал не должен стать его обходом. Файл с правами 600 внутри каталога
данных недоступен ни из сети, ни другому пользователю хоста.

Протокол: одна строка JSON в обе стороны.
    →  {"argv": ["features", "on", "digest"]}
    ←  {"code": 0, "out": "…", "err": "…"}
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import io
import json
import logging
import os
import socket
from contextlib import redirect_stderr, redirect_stdout

log = logging.getLogger("radar.adminsock")

# Запрос — это строка аргументов, больше нескольких килобайт не бывает.
MAX_REQUEST = 64 * 1024

# Команды идут по одной: вывод перехватывается через sys.stdout, а он один
# на процесс, и две одновременные команды перемешали бы ответы.
_lock: asyncio.Lock | None = None


def path() -> str:
    """Где лежит сокет: рядом с базой, в каталоге данных."""
    explicit = (os.getenv("ADMIN_SOCKET") or "").strip()
    if explicit:
        return explicit
    from . import config

    folder = os.path.dirname(os.path.abspath(config.DB_FILE)) or "data"
    return os.path.join(folder, "admin.sock")


def supported() -> bool:
    return hasattr(socket, "AF_UNIX") and hasattr(asyncio, "start_unix_server")


# --------------------------------------------------------------------------
#  Сторона бота
# --------------------------------------------------------------------------

def _worker(loop: asyncio.AbstractEventLoop, argv: list[str]) -> tuple[int, str, str]:
    """Выполняет команду в отдельном потоке: часть команд блокирует
    (копия, обслуживание базы), а бот не должен вставать из-за них."""
    from . import cli

    out, err = io.StringIO(), io.StringIO()
    cli.attach(loop)
    try:
        with redirect_stdout(out), redirect_stderr(err):
            try:
                code = cli.main(argv)
            except SystemExit as exc:
                # argparse выходит сам при неверных аргументах.
                code = exc.code if isinstance(exc.code, int) else cli.FAILED
    finally:
        cli.attach(None)
    return int(code), out.getvalue(), err.getvalue()


async def execute(argv: list[str]) -> tuple[int, str, str]:
    global _lock
    if _lock is None:
        _lock = asyncio.Lock()
    loop = asyncio.get_running_loop()
    async with _lock:
        return await asyncio.to_thread(_worker, loop, argv)


async def _handle(reader: asyncio.StreamReader, writer: asyncio.StreamWriter) -> None:
    try:
        raw = await reader.readline()
        if not raw or len(raw) > MAX_REQUEST:
            return
        request = json.loads(raw.decode("utf-8"))
        argv = request.get("argv")
        if not isinstance(argv, list) or not all(isinstance(a, str) for a in argv):
            reply = {"code": 1, "out": "", "err": "bad request\n"}
        else:
            code, out, err = await execute(argv)
            reply = {"code": code, "out": out, "err": err}
        writer.write((json.dumps(reply, ensure_ascii=False) + "\n").encode("utf-8"))
        await writer.drain()
    except Exception:  # noqa: BLE001
        log.exception("Запрос к каналу управления не выполнен")
    finally:
        try:
            writer.close()
        except Exception:  # noqa: BLE001
            pass


def _clear_stale(target: str) -> bool:
    """Убирает сокет, оставшийся от упавшего процесса. Живой не трогает."""
    if not os.path.exists(target):
        return True
    probe = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    probe.settimeout(1)
    try:
        probe.connect(target)
    except OSError:
        try:
            os.unlink(target)
            return True
        except OSError:
            return False
    finally:
        probe.close()
    return False   # слушает другой экземпляр


async def serve() -> None:
    """Запускается задачей рядом с ботом и живёт до его остановки."""
    if not supported():
        log.info("Канал управления недоступен на этой системе")
        return
    target = path()
    os.makedirs(os.path.dirname(target) or ".", exist_ok=True)
    if not _clear_stale(target):
        log.warning("Канал управления занят другим процессом: %s", target)
        return
    # Права назначаются при создании файла, а не после: между bind и chmod
    # сокет был бы открыт всем, кто успеет подключиться.
    old_mask = os.umask(0o177)
    try:
        server = await asyncio.start_unix_server(_handle, path=target)
    finally:
        os.umask(old_mask)
    log.info("Канал управления: %s", target)
    try:
        async with server:
            await server.serve_forever()
    finally:
        try:
            os.unlink(target)
        except OSError:
            pass


# --------------------------------------------------------------------------
#  Сторона командной строки
# --------------------------------------------------------------------------

def call(argv: list[str]) -> tuple[int, str, str] | None:
    """Отправляет команду работающему боту. None — бот недоступен."""
    if not supported():
        return None
    target = path()
    if not os.path.exists(target):
        return None
    client = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    try:
        client.settimeout(3)
        client.connect(target)
    except OSError:
        client.close()
        return None
    try:
        # Подключились — дальше ждём сколько нужно: проверка источников
        # занимает минуты.
        client.settimeout(None)
        client.sendall((json.dumps({"argv": argv}, ensure_ascii=False) + "\n").encode("utf-8"))
        data = b""
        while not data.endswith(b"\n"):
            chunk = client.recv(65536)
            if not chunk:
                break
            data += chunk
        reply = json.loads(data.decode("utf-8"))
        return int(reply["code"]), str(reply.get("out", "")), str(reply.get("err", ""))
    except (OSError, ValueError, KeyError):
        # Команда уже отправлена и могла выполниться: повторять её
        # напрямую нельзя, иначе «add» или «prune» сработают дважды.
        return 1, "", "Связь с ботом прервалась; результат неизвестен — проверьте командой list.\n"
    finally:
        client.close()
RADAR_FILE_119
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/accounts.py"
cat > "radar/accounts.py" <<'RADAR_FILE_120'
"""Живые и мёртвые аккаунты в Telegram (с 5.9.4).

Три разные задачи, и важно не путать, на что способен Bot API:

* **Удалённые участники группы.** Bot API не умеет перечислять участников
  чата, поэтому чистка идёт по тем, кого бот видел сам (`ChatMember`:
  вступление, сообщение). Про каждого спрашивается `getChatMember`;
  удалённый аккаунт приходит как «Deleted Account». Тех, кто в чате давно
  и молчит, бот не знает — отчёт честно говорит, сколько из скольких
  участников проверено. Полный обход возможен только через MTProto
  (пользовательская сессия), и это сознательно не делается: такие сессии
  банят, а условия Telegram их не одобряют.
* **Мёртвые получатели оповещений.** Заблокировал бота или удалил аккаунт —
  `TelegramForbiddenError`. Отметка `dead` снимает повторные попытки: раньше
  тревога для такого человека уходила в API каждый цикл, и каждый раз —
  предупреждение в журнале. Снимается сама, когда человек пишет боту:
  разблокировать бота можно только заново нажав /start.
* **Новички по базе CAS** (Combot Anti-Spam). Это внешний сервис: ему
  отправляется числовой идентификатор человека. Поэтому — только по флагу
  `cas_check`, выключен по умолчанию, и об обмене сказано в README.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import logging
import time
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable

log = logging.getLogger("radar.accounts")

# Так Bot API называет удалённый аккаунт. Список, а не одна строка: бот
# видит имя в том виде, в каком его отдаёт сервер, и локализация иногда
# проскакивает.
DELETED_NAMES = {"deleted account", "удалённый аккаунт", "удаленный аккаунт"}

CAS_URL = "https://api.cas.chat/check"
CAS_TIMEOUT = 6

# Пауза между запросами getChatMember: у Bot API общий предел около 30
# запросов в секунду на бота, а чистка — не самое срочное, что он делает.
SCAN_PAUSE = 0.06
# Больше этого за один проход не проверяем: группа на десятки тысяч
# заблокировала бы бота для всего остального на несколько минут.
SCAN_LIMIT = 5000


def is_deleted_user(user: Any) -> bool:
    """Удалён ли аккаунт. У удалённого нет ни фамилии, ни имени пользователя."""
    name = str(getattr(user, "first_name", "") or "").strip().lower()
    if name not in DELETED_NAMES:
        return False
    return not getattr(user, "last_name", None) and not getattr(user, "username", None)


# --------------------------------------------------------------------------
#  Мёртвые получатели
# --------------------------------------------------------------------------

def _record(uid: int | str) -> dict[str, Any] | None:
    from . import storage

    return storage.get_user(uid)


def mark_dead(uid: int | str) -> bool:
    """Отмечает недоступного получателя. Только человек: у группы
    `Forbidden` значит другое (бота исключили), и её это не касается."""
    try:
        if int(uid) <= 0:
            return False
    except (TypeError, ValueError):
        return False
    record = _record(uid)
    if record is None or record.get("dead"):
        return False
    record["dead"] = int(time.time())
    log.info("Получатель %s недоступен — отправки ему приостановлены", uid)
    return True


def mark_alive(uid: int | str) -> bool:
    record = _record(uid)
    if record is None or not record.get("dead"):
        return False
    record.pop("dead", None)
    log.info("Получатель %s снова на связи", uid)
    return True


def is_dead(uid: int | str) -> bool:
    record = _record(uid)
    return bool(record and record.get("dead"))


def stale() -> list[tuple[str, int]]:
    """Недоступные получатели: (ключ, когда отмечен)."""
    from . import storage

    return sorted(
        ((key, int(item["dead"])) for key, item in storage.users().items()
         if item.get("dead")),
        key=lambda pair: pair[1])


# --------------------------------------------------------------------------
#  CAS
# --------------------------------------------------------------------------

async def _fetch_cas(user_id: int) -> dict[str, Any] | None:
    import aiohttp

    timeout = aiohttp.ClientTimeout(total=CAS_TIMEOUT)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.get(CAS_URL, params={"user_id": str(user_id)}) as response:
            if response.status != 200:
                return None
            return await response.json(content_type=None)


async def cas_banned(
    user_id: int,
    fetch: Callable[[int], Awaitable[dict[str, Any] | None]] | None = None,
) -> bool | None:
    """True — в базе, False — нет, None — не удалось узнать.

    Недоступность сервиса — не повод ни банить, ни пускать «на всякий
    случай»: вызывающий решает по None сам (у нас — пропускает).
    """
    try:
        data = await (fetch or _fetch_cas)(user_id)
    except Exception as exc:  # noqa: BLE001
        log.debug("CAS недоступен: %s", exc)
        return None
    if not isinstance(data, dict):
        return None
    return bool(data.get("ok"))


# --------------------------------------------------------------------------
#  Чистка удалённых аккаунтов в группе
# --------------------------------------------------------------------------

@dataclass
class Scan:
    chat_id: int
    members_total: int | None = None   # сколько участников в чате по данным Telegram
    known: int = 0                     # сколько из них бот видел
    checked: int = 0
    deleted: list[int] = field(default_factory=list)
    failed: int = 0
    truncated: bool = False

    @property
    def coverage(self) -> str:
        if not self.members_total:
            return f"{self.known}"
        return f"{self.known} / {self.members_total}"


async def scan_chat(bot: Any, chat_id: int, ids: list[int],
                    pause: float = SCAN_PAUSE) -> Scan:
    """Находит удалённые аккаунты среди известных боту участников."""
    result = Scan(chat_id=chat_id, known=len(ids))
    try:
        result.members_total = int(await bot.get_chat_member_count(chat_id))
    except Exception:  # noqa: BLE001
        result.members_total = None

    batch = ids[:SCAN_LIMIT]
    result.truncated = len(ids) > len(batch)
    for user_id in batch:
        try:
            member = await bot.get_chat_member(chat_id, user_id)
        except Exception:  # noqa: BLE001
            # Вышел из чата или бот потерял права — не повод считать его
            # удалённым, но и проверенным он не стал.
            result.failed += 1
        else:
            result.checked += 1
            if is_deleted_user(getattr(member, "user", None)):
                result.deleted.append(user_id)
        await asyncio.sleep(pause)
    return result


async def remove_deleted(bot: Any, chat_id: int, ids: list[int],
                         pause: float = SCAN_PAUSE) -> int:
    """Исключает найденных. Бан сразу снимается: человека нет, а запись
    «заблокирован» в списке чата только засоряла бы его."""
    from .db import repo

    removed = 0
    for user_id in ids:
        try:
            await bot.ban_chat_member(chat_id, user_id)
            await bot.unban_chat_member(chat_id, user_id, only_if_banned=True)
        except Exception:  # noqa: BLE001
            log.debug("Не удалось исключить %s из %s", user_id, chat_id, exc_info=True)
            continue
        removed += 1
        await repo.member_drop(chat_id, user_id)
        await asyncio.sleep(pause)
    if removed:
        log.info("Чат %s: исключено удалённых аккаунтов — %d", chat_id, removed)
    return removed
