"""Сетевые проверки: раскрытие редиректов, возраст домена, Safe Browsing.

Все функции асинхронны, каждая возвращает деградированный результат
вместо исключения — так тесты могут подменять сессию, а бот не падает.

Адрес проверяемой ссылки проверяется на частные подсети: запрос
к 127.0.0.1 или 10.x из бота, живущего на сервере, — это обращение
к самому серверу, и отдавать его наружу нельзя.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import logging
import socket
import ssl
from datetime import datetime, timezone
from urllib.parse import urljoin, urlparse

import aiohttp

log = logging.getLogger("radar.linkcheck.netcheck")

TIMEOUT = aiohttp.ClientTimeout(total=12, connect=6)
MAX_REDIRECTS = 5
RDAP_BOOTSTRAP = "https://rdap.org/domain/"


def _session() -> aiohttp.ClientSession:
    """Сессия, которая не соединится с внутренним адресом.

    Проверка `_is_public_ip` ниже делается ДО запроса, а соединение
    открывается по имени — то есть с повторным разрешением имени.
    Домен с коротким TTL отдавал публичный адрес на проверку
    и `127.0.0.1` на само соединение (DNS rebinding). Резолвер
    в соединителе закрывает и это, и редиректы.

    Обычная функция, а не корутина. До 4.9.9.2 здесь стояло
    `async def`, а вызывалась она как `async with _session() as sess` —
    корутина не бывает контекстным менеджером, и каждый такой вызов
    кончался `TypeError`. Проверка ловила его и писала «error: TypeError»,
    то есть с 4.9.4 ни одна сетевая проверка ссылки не отработала
    ни разу: ни редиректы, ни возраст домена, ни Safe Browsing.
    """
    connector = None
    try:
        import sys, os
        root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        if root not in sys.path:
            sys.path.insert(0, root)
        from radar import netguard

        connector = netguard.connector()
    except Exception:  # noqa: BLE001
        # Модуль бота рядом не оказался — остаётся проверка до запроса.
        log.warning("netguard недоступен, соединение без фильтра адресов")

    return aiohttp.ClientSession(
        timeout=TIMEOUT,
        headers={"User-Agent": "Mozilla/5.0 (compatible; LinkCheck/1.0)"},
        trust_env=True,
        connector=connector,
    )


def _is_public_ip(ip: str) -> bool:
    try:
        import ipaddress
        addr = ipaddress.ip_address(ip)
        return not (addr.is_private or addr.is_loopback or addr.is_link_local or addr.is_multicast)
    except ValueError:
        return False


async def _resolve(host: str) -> list[str]:
    loop = asyncio.get_running_loop()
    try:
        infos = await loop.getaddrinfo(host, None, family=socket.AF_UNSPEC, type=socket.SOCK_STREAM)
        return [info[4][0] for info in infos]
    except Exception as exc:  # noqa: BLE001
        log.warning("resolve failed %s: %s", host, exc)
        return []


# Коды, которыми сервер отвечает «HEAD не поддерживаю». Такой сайт
# на GET может редиректить как обычно, и считать его конечной точкой
# цепочки после одного HEAD — значит показать человеку не тот адрес.
_HEAD_REFUSED = frozenset({403, 404, 405, 501})


async def _probe_redirect(sess, url: str) -> tuple[int, str]:
    """Код ответа и адрес редиректа. HEAD, при отказе — GET без тела."""
    async with sess.head(url, allow_redirects=False) as resp:
        if resp.status not in _HEAD_REFUSED:
            return resp.status, resp.headers.get("Location") or ""
    async with sess.get(url, allow_redirects=False) as resp:
        # Тело не читаем: нужен только код и заголовок.
        return resp.status, resp.headers.get("Location") or ""


async def expand(url: str) -> "NetResult":
    from .analyze import NetResult

    res = NetResult()
    res.chain = [url]
    cur = url

    for _ in range(MAX_REDIRECTS):
        parsed = urlparse(cur)
        host = parsed.netloc.split("@")[-1].split(":")[0]
        ips = await _resolve(host)
        if not ips:
            res.notes.append("dns failed")
            res.final_url = cur
            return res
        if not all(_is_public_ip(ip) for ip in ips):
            res.notes.append("private ip blocked")
            res.final_url = cur
            return res

        try:
            async with _session() as sess:
                status, location = await _probe_redirect(sess, cur)
                if 300 <= status < 400:
                    if not location:
                        break
                    # urljoin, а не склейка: адрес редиректа бывает
                    # относительным без ведущего слэша, с портом или
                    # «//host/path» — склейка теряла порт и путь.
                    cur = urljoin(cur, location)
                    res.chain.append(cur)
                    continue
                res.success = True
                res.final_url = cur
                return res
        except asyncio.TimeoutError:
            res.notes.append("timeout")
            break
        except Exception as exc:  # noqa: BLE001
            log.warning("expand failed %s: %s", cur, exc)
            res.notes.append(f"error: {type(exc).__name__}")
            break
    res.final_url = cur
    return res


def _registrar_name(entities: list | None) -> str:
    """Имя регистратора из RDAP-ответа — ближайший публичный аналог поля
    "Registrar" в классическом whois. RDAP не отдаёт владельца и контакты
    домена вовсе: с 2018 года (GDPR) их прячут почти все регистраторы,
    и whois-серверы отвечают тем же редактированием, так что запрашивать
    их бессмысленно что там, что тут — RDAP выбран вместо whois именно
    потому, что отвечает структурированным JSON вместо текста произвольного
    формата, который пришлось бы парсить регистратор за регистратором.
    """
    for entity in entities or []:
        roles = entity.get("roles") or []
        if "registrar" not in roles:
            continue
        vcard = entity.get("vcardArray")
        if not (isinstance(vcard, list) and len(vcard) > 1):
            continue
        for field in vcard[1]:
            if isinstance(field, list) and len(field) >= 4 and field[0] == "fn":
                return str(field[3])
    return ""


async def domain_age(host: str) -> "NetResult":
    from .analyze import NetResult

    res = NetResult()
    try:
        async with _session() as sess:
            async with sess.get(f"{RDAP_BOOTSTRAP}{host}") as resp:
                if resp.status != 200:
                    res.notes.append(f"rdap {resp.status}")
                    return res
                data = await resp.json(content_type=None)
                res.domain_registrar = _registrar_name(data.get("entities"))
                events = data.get("events", [])
                for ev in events:
                    if ev.get("eventAction") == "registration":
                        reg = ev.get("eventDate")
                        if reg:
                            dt = datetime.fromisoformat(reg.replace("Z", "+00:00"))
                            res.domain_age_days = (datetime.now(timezone.utc) - dt).days
                            break
    except Exception as exc:  # noqa: BLE001
        log.warning("rdap failed %s: %s", host, exc)
        res.notes.append(f"rdap error: {type(exc).__name__}")
    return res


async def safe_browsing(url: str, api_key: str | None) -> "NetResult":
    from .analyze import NetResult

    res = NetResult()
    if not api_key:
        res.notes.append("no api key")
        return res
    try:
        body = {
            "client": {"clientId": "radar-linkcheck", "clientVersion": "1.0"},
            "threatInfo": {
                "threatTypes": ["MALWARE", "SOCIAL_ENGINEERING",
                                "UNWANTED_SOFTWARE", "POTENTIALLY_HARMFUL_APPLICATION"],
                "platformTypes": ["ANY_PLATFORM"],
                "threatEntryTypes": ["URL"],
                "threatEntries": [{"url": url}],
            },
        }
        # Ключ — заголовком, а не в адресе. В адресе он попадал бы
        # в текст исключения aiohttp, а оттуда в журнал: при любом
        # сетевом сбое ключ оказывался бы в логах открытым текстом.
        async with _session() as sess:
            async with sess.post(
                "https://safebrowsing.googleapis.com/v4/threatMatches:find",
                json=body,
                headers={"X-Goog-Api-Key": api_key},
            ) as resp:
                if resp.status != 200:
                    res.notes.append(f"safebrowsing {resp.status}")
                    return res
                data = await resp.json(content_type=None)
                matches = data.get("threatMatches", [])
                for m in matches:
                    t = m.get("threatType", "unknown")
                    res.threats.append(t)
                res.success = True
    except Exception as exc:  # noqa: BLE001
        # Только тип исключения: текст может нести заголовки запроса.
        log.warning("safebrowsing failed %s: %s", url, type(exc).__name__)
        res.notes.append(f"safebrowsing error: {type(exc).__name__}")
    return res


# Отечественные центы сертификации, которыми подписываются сайты
# внутри национальной инфраструктуры. Их присутствие в цепочке
# при посещении сайта, который глобально известен другим издателем,
# означает перехват TLS на уровне провайдера (ТСПУ) — человек
# думает, что говорит с сайтом напрямую, а между ним и сайтом
# стоит посредник, читающий трафик. Список не исчерпывающий:
# проверка смотрит и на сам факт «издатель сменился на
# незнакомый», а не только на конкретные имена.
NATIONAL_CAs = {
    "russian trusted root ca",
    "russian trusted sub ca",
    "russian trusted center",
    "ministry of digital development",
    "моски",
    "нцпи",
    "фсб россии",
}

# Издатели крупнейших мировых площадок: если сайт известен каким-то
# из них, а цепочку подписал национальный или неизвестный центр —
# это не «сайт сменил сертификат», это перехват.
KNOWN_ISSUERS = {
    "gmail.com": ("google trust services", "globalsign"),
    "youtube.com": ("google trust services", "globalsign"),
    "google.com": ("google trust services", "globalsign"),
    "facebook.com": ("digicert", "globalsign"),
    "instagram.com": ("digicert", "globalsign"),
    "x.com": ("digicert", "globalsign"),
    "twitter.com": ("digicert", "globalsign"),
    "vk.com": ("globalsign", "sectigo"),
    "yandex.ru": ("globalsign", "sectigo", "digicert"),
    "telegram.org": ("digicert", "globalsign"),
    "wikipedia.org": ("globalsign", "digicert", "lets encrypt", "isrg"),
}


def _cert_mitm_suspect(issuer: str, host: str) -> tuple[bool, str]:
    """Похоже ли издателя сертификата на перехват TLS.

    Возвращает (подозрительно, пояснение). Смотрится не сам факт
    национального CA — им подписано много честных российских сайтов, —
    а противоречие: сайт известен глобальным издателем, а цепочку
    подписал кто-то другой. Ошибка здесь допустима только в одну
    сторону: непойманное — обычная осторожность, пойманное ложно —
    обвинение сайта без вины. Поэтому ложных срабатываний избегаем:
    незнакомый издатель без национальной подписи — не повод для
    сигнала.
    """
    issuer_lower = issuer.lower()
    if not issuer_lower.strip():
        return False, ""
    for domain, issuers in KNOWN_ISSUERS.items():
        if host == domain or host.endswith("." + domain):
            if any(marker in issuer_lower for marker in NATIONAL_CAs):
                return True, (
                    f"сайт {domain} использует сертификат национального "
                    "издателя — вероятен перехват TLS на уровне провайдера"
                )
            if not any(marker in issuer_lower for marker in issuers):
                return True, (
                    f"сертификат {domain} издан неизвестным центром "
                    f"({issuer[:60]}) — вероятен перехват TLS"
                )
            return False, ""
    # Сайт вне списка известных: сигнал ставим только за явную
    # национальную подпись — сам по себе она легальна, но для
    # человека, проверяющего ссылку, это важный факт: внутри
    # такой сессии возможен разбор трафика.
    for marker in NATIONAL_CAs:
        if marker in issuer_lower:
            return True, "сертификат издан национальным центром — внутри сессии возможен разбор трафика"
    return False, ""


async def cert_info(host: str) -> "NetResult":
    from .analyze import NetResult

    res = NetResult()
    writer = None
    try:
        loop = asyncio.get_running_loop()
        ctx = ssl.create_default_context()
        ctx.check_hostname = True
        ctx.verify_mode = ssl.CERT_REQUIRED
        # Соединение закрывается в finally независимо от того, дошло ли
        # дело до сертификата: раньше при отсутствии сокета у writer оно
        # утекало и висело до таймаута.
        _reader, writer = await asyncio.wait_for(
            asyncio.open_connection(host, 443, ssl=ctx),
            timeout=6,
        )
        # Версия TLS: SSLv3 и TLS 1.0 сломаны известными атаками,
        # а честные сайты давно не используют их.
        transport = writer.transport
        ssl_object = getattr(transport, "get_extra_info", lambda _n: None)("ssl_object")
        if ssl_object is not None:
            res.tls_version = ssl_object.version() or ""

        # Сертификат — через «peercert», а не через сокет. asyncio отдаёт
        # по «socket» обёртку TransportSocket, у которой getpeercert нет:
        # до 4.9.9.2 здесь каждый раз был AttributeError, и срок
        # сертификата не проверялся никогда.
        cert = writer.get_extra_info("peercert") or {}
        if cert:
            not_after = cert.get("notAfter")
            if not_after:
                expires = datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
                expires = expires.replace(tzinfo=timezone.utc)
                res.cert_valid_days = (expires - datetime.now(timezone.utc)).days
                res.success = True
            issuer = ""
            for piece in cert.get("issuer", ()):  # tuple of tuples
                for name, value in piece:
                    if name in ("organizationName", "commonName") and value:
                        issuer = f"{issuer} {value}".strip()
            suspect, why = _cert_mitm_suspect(issuer, host)
            if suspect:
                res.mitm_suspect = True
                res.notes.append(why)
    except Exception as exc:  # noqa: BLE001
        log.warning("cert failed %s: %s", host, exc)
        res.notes.append(f"cert error: {type(exc).__name__}")
    finally:
        if writer is not None:
            writer.close()
            try:
                await writer.wait_closed()
            except Exception:  # noqa: BLE001
                pass
    return res


async def http_security(url: str) -> "NetResult":
    """HTTPS-редирект, HSTS и примитивы страницы.

    Проверяется стартовый адрес (до редиректов): если он HTTP
    и не отправляет на HTTPS — весь путь до сайта идёт открытым
    текстом, и логин-форма на такой странице читается по дороге.
    """
    from .analyze import NetResult

    res = NetResult()
    try:
        async with _session() as sess:
            async with sess.get(url, allow_redirects=False) as resp:
                if url.lower().startswith("http://"):
                    location = resp.headers.get("Location") or ""
                    res.https_redirect = location.lower().startswith("https://")
                res.hsts = bool(resp.headers.get("Strict-Transport-Security"))

                # Форма входа на незащищённой странице: пароль уходит
                # открытым текстом, и это не зависит от честности сайта.
                # Читаем только начало: по ссылке может лежать образ
                # диска на гигабайты, а resp.text() тянул его целиком
                # в память одноплатника ради шестидесяти килобайт.
                head = await resp.content.read(65536)
                low = head.decode("utf-8", errors="replace").lower()
                if url.lower().startswith("http://"):
                    if "<form" in low and (
                        'type="password"' in low or "type='password'" in low
                    ):
                        res.login_form_http = True
                    # Смешанный контент: HTTPS-страница, тянущая HTTP.
                elif url.lower().startswith("https://"):
                    if 'src="http://' in low or "src='http://" in low:
                        res.mixed_content = low.count('src="http://') + \
                            low.count("src='http://")
                res.success = True
    except Exception as exc:  # noqa: BLE001
        log.debug("http_security failed %s: %s", url, exc)
        res.notes.append(f"security error: {type(exc).__name__}")
    return res


async def full_check(url: str, api_key: str | None = None) -> "NetResult":
    from .analyze import NetResult

    chain = await expand(url)
    # Сбой цепочки редиректов — не повод бросать остальное. До 4.9.9.2
    # проверка на этом заканчивалась: сайт, отвергший HEAD или
    # ответивший медленно, оставался без возраста домена, Safe Browsing
    # и сертификата, а человек видел «0/100, риск Ok» — то есть
    # отсутствие проверки выглядело как чистый результат.
    target = chain.final_url or url
    parsed = urlparse(target)
    host = parsed.netloc.split("@")[-1].split(":")[0]

    # Внутренний адрес — дальше не идём. Проверка сертификата открывает
    # соединение напрямую, мимо фильтра сессии, и без этого пошла бы
    # по домашней сети за роутером по чужой ссылке.
    if "private ip blocked" in chain.notes or not host:
        return chain
    addresses = await _resolve(host)
    if not addresses:
        # Имя не разрешилось — проверять нечего, и это само по себе
        # признак: у живого сайта DNS есть.
        if "dns failed" not in chain.notes:
            chain.notes.append("dns failed")
        return chain
    if not all(_is_public_ip(ip) for ip in addresses):
        chain.notes.append("private ip blocked")
        return chain

    # Параллельно: проверки друг от друга не зависят, и последовательно
    # они складывались в полминуты ожидания. Сбой одной не роняет другие.
    results = await asyncio.gather(
        domain_age(host),
        safe_browsing(target, api_key),
        cert_info(host),
        http_security(target),
        return_exceptions=True,
    )
    for item in results:
        if isinstance(item, asyncio.CancelledError):
            raise item
    age, sb, cert, sec = (
        item if isinstance(item, NetResult) else NetResult(
            notes=[f"error: {type(item).__name__}"])
        for item in results
    )

    return NetResult(
        # Успехом считаем, если сработала хоть одна содержательная
        # проверка: иначе «не проверено» опять покажется «безопасно».
        success=bool(chain.success or age.domain_age_days is not None
                     or sb.success or cert.success or sec.success),
        final_url=target,
        chain=chain.chain,
        domain_age_days=age.domain_age_days,
        domain_registrar=age.domain_registrar,
        cert_valid_days=cert.cert_valid_days,
        threats=sb.threats,
        notes=chain.notes + age.notes + sb.notes + cert.notes + sec.notes,
        https_redirect=sec.https_redirect,
        hsts=sec.hsts,
        tls_version=cert.tls_version,
        mitm_suspect=cert.mitm_suspect,
        mixed_content=sec.mixed_content,
        login_form_http=sec.login_form_http,
    )
RADAR_FILE_169
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "multitool/linkcheck/report.py"
cat > "multitool/linkcheck/report.py" <<'RADAR_FILE_170'
"""Формирование отчёта для Telegram в виде HTML-сообщения.

Отчёт содержит перечень найденных признаков и сетевые проверки,
но никогда не утверждает, что ссылка «безопасна».
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import html
from typing import Any

from .analyze import Verdict


def _verdict_icon(level: str) -> str:
    return {"ok": "✅", "attention": "⚠️", "suspect": "🔶", "danger": "🚨"}.get(level, "❓")


# Служебные пометки сетевых проверок — человеческими словами (с 4.9.9.2).
# Раньше в отчёт уходило как есть: «error: TypeError», «no api key»,
# «rdap 404». Человек не знает, что это, и не может понять, насколько
# доверять остальному отчёту.
_NOTES = {
    "dns failed": "имя сайта не находится в DNS — сайта может не существовать",
    "private ip blocked": "адрес ведёт во внутреннюю сеть — проверка остановлена",
    "timeout": "сайт не ответил вовремя",
    "no api key": "Safe Browsing не проверен — не задан ключ Google",
}


def humanize_note(note: str) -> str:
    """Пометка проверки понятным текстом. Незнакомая остаётся как есть."""
    text = (note or "").strip()
    if text in _NOTES:
        return _NOTES[text]
    if text.startswith("rdap "):
        return "возраст домена не узнать: реестр не ответил"
    if text.startswith("safebrowsing "):
        return "Safe Browsing не ответил"
    if text.startswith("cert error"):
        return "сертификат не получен: сайт без HTTPS или отверг соединение"
    if text.startswith("security error"):
        return "заголовки безопасности не получены"
    if text.startswith("error:"):
        return "сетевая проверка не удалась"
    return text


def net_incomplete(v: Verdict) -> bool:
    """Сетевые проверки не дали ничего содержательного.

    Тогда нулевой счёт означает не «чисто», а «не проверено», и зелёная
    галочка рядом с ним — обман: до 4.9.9.2 именно так и выглядел отчёт
    при сломанной сетевой части.
    """
    return v.net is not None and not v.net.success


def build_report(v: Verdict) -> str:
    if not v.signals and not v.net:
        return "Ничего не удалось проанализировать."

    lines: list[str] = ["<b>Результат проверки ссылки</b>\n"]
    url = html.escape(v.url)
    lines.append(f"<b>Ссылка:</b> <code>{url}</code>\n")

    if v.signals:
        lines.append("<b>Признаки из адреса:</b>")
        for sig in sorted(v.signals, key=lambda s: s.weight, reverse=True):
            title = html.escape(sig.title)
            detail = html.escape(sig.detail) if sig.detail else ""
            lines.append(f"  • <i>{title}</i> ({sig.weight})")
            if detail:
                lines.append(f"      <code>{detail}</code>")
        lines.append("")

    if v.net:
        lines.append("<b>Сетевые проверки:</b>")
        if not v.net.success:
            lines.append("  <i>Не удалось завершить сетевую проверку</i>")
            if v.net.notes:
                for note in dict.fromkeys(v.net.notes):
                    lines.append(f"      • {html.escape(humanize_note(note))}")
        else:
            if v.net.chain and len(v.net.chain) > 1:
                lines.append("  <b>Перенаправления:</b>")
                for hop in v.net.chain:
                    lines.append(f"      <code>{html.escape(hop)}</code>")
                lines.append("")
            if v.net.domain_age_days is not None:
                age = v.net.domain_age_days
                lines.append(f"  <i>Возраст домена:</i> {age} дн.")
                if age < 30:
                    lines.append("      <i>(домен зарегистрирован недавно)</i>")
                lines.append("")
            if v.net.domain_registrar:
                registrar = html.escape(v.net.domain_registrar)
                lines.append(f"  <i>Регистратор:</i> {registrar}")
                lines.append("")
            if v.net.cert_valid_days is not None:
                days = v.net.cert_valid_days
                lines.append(f"  <i>Сертификат валиден:</i> {days} дн.")
                if days < 0:
                    lines.append("      <i>(сертификат просрочен)</i>")
                elif days < 7:
                    lines.append("      <i>(сертификат скоро истекает)</i>")
                lines.append("")
            if v.net.mitm_suspect:
                lines.append("  🚨 <b>Подозрение на перехват TLS</b> — "
                             "сертификат выдан не тем центром, каким сайт "
                             "подписан глобально. Посредник между вами "
                             "и сайтом может читать трафик.")
                lines.append("")
            if v.net.tls_version:
                tls = v.net.tls_version
                lines.append(f"  <i>TLS:</i> {html.escape(tls)}")
                if tls in ("SSLv3", "TLSv1", "TLSv1.1"):
                    lines.append("      <i>(устаревшая версия — уязвима к атакам)</i>")
                lines.append("")
            if v.net.https_redirect is False:
                lines.append("  <i>HTTP не перенаправляет на HTTPS</i> — "
                             "путь до сайта идёт открытым текстом")
                lines.append("")
            if v.net.hsts:
                lines.append("  <i>HSTS:</i> включён")
                lines.append("")
            if v.net.mixed_content:
                lines.append(f"  ⚠️ <i>Смешанный контент:</i> "
                             f"{v.net.mixed_content} HTTP-элементов на HTTPS-странице")
                lines.append("")
            if v.net.login_form_http:
                lines.append("  ⚠️ <i>Форма входа на незащищённой странице</i> — "
                             "пароль уходит открытым текстом")
                lines.append("")
            if v.net.threats:
                lines.append("  <b>⚠️ Обнаружены угрозы по Safe Browsing:</b>")
                for t in v.net.threats:
                    lines.append(f"      <code>{html.escape(t)}</code>")
                lines.append("")
            if v.net.notes:
                lines.append("  <b>Что проверить не удалось:</b>")
                for note in dict.fromkeys(v.net.notes):
                    lines.append(f"      • {html.escape(humanize_note(note))}")
                lines.append("")
    score = v.score
    level = v.level
    icon = _verdict_icon(level)
    if net_incomplete(v) and level == "ok":
        # Признаков нет, но и сеть не проверена — это не «чисто».
        lines.append(f"<b>Итоговый счёт:</b> {score}/100 ❓")
        lines.append("<b>Уровень риска:</b> не определён — сетевая часть "
                     "не прошла, оценка только по виду адреса")
    else:
        lines.append(f"<b>Итоговый счёт:</b> {score}/100 {icon}")
        lines.append(f"<b>Уровень риска:</b> {level.title()}")
    lines.append("")
    lines.append(
        "⚠️ <i>Это не гарантия безопасности. "
        "Отсутствие признаков не означает, что ссылка полностью безопасна. "
        "Всегда проверяйте источник через официальные каналы.</i>"
    )
    return "\n".join(lines)


def build_report_plain(v: Verdict) -> str:
    if not v.signals and not v.net:
        return "Ничего не удалось проанализировать."

    lines: list[str] = ["Результат проверки ссылки"]
    lines.append("")
    lines.append(f"Ссылка: {v.url}")
    lines.append("")

    if v.signals:
        lines.append("Признаки из адреса:")
        for sig in sorted(v.signals, key=lambda s: s.weight, reverse=True):
            lines.append(f"  • {sig.title} ({sig.weight})")
            if sig.detail:
                lines.append(f"      {sig.detail}")
        lines.append("")

    if v.net:
        lines.append("Сетевые проверки:")
        if not v.net.success:
            lines.append("  Не удалось завершить сетевую проверку")
            if v.net.notes:
                for note in v.net.notes:
                    lines.append(f"      {note}")
        else:
            if v.net.chain and len(v.net.chain) > 1:
                lines.append("  Перенаправления:")
                for hop in v.net.chain:
                    lines.append(f"      {hop}")
                lines.append("")
            if v.net.domain_age_days is not None:
                age = v.net.domain_age_days
                lines.append(f"  Возраст домена: {age} дн.")
                if age < 30:
                    lines.append("      (домен зарегистрирован недавно)")
                lines.append("")
            if v.net.domain_registrar:
                lines.append(f"  Регистратор: {v.net.domain_registrar}")
                lines.append("")
            if v.net.cert_valid_days is not None:
                days = v.net.cert_valid_days
                lines.append(f"  Сертификат валиден: {days} дн.")
                if days < 0:
                    lines.append("      (сертификат просрочен)")
                elif days < 7:
                    lines.append("      (сертификат скоро истекает)")
                lines.append("")
            if v.net.threats:
                lines.append("  ⚠️ Обнаружены угрозы по Safe Browsing:")
                for t in v.net.threats:
                    lines.append(f"      {t}")
                lines.append("")
            if v.net.notes:
                lines.append("  Примечания сети:")
                for note in v.net.notes:
                    lines.append(f"      {note}")
                lines.append("")
    score = v.score
    level = v.level
    icon = _verdict_icon(level)
    lines.append(f"Итоговый счёт: {score}/100 {icon}")
    lines.append(f"Уровень риска: {level.title()}")
    lines.append("")
    lines.append(
        "⚠️ Это не гарантия безопасности. "
        "Отсутствие признаков не означает, что ссылка полностью безопасна. "
        "Всегда проверяйте источник через официальные каналы."
    )
    return "\n".join(lines)
RADAR_FILE_170
ok "Развёрнуто файлов: $(printf '%s' "$FILE_COUNT")"

# Сборщик журналов на стороне хоста. Журналы контейнеров Docker боту
# недоступны: чтобы их читать, ему пришлось бы дать доступ к сокету Docker,
# а это фактически полный доступ к серверу.
cat > "$APP_DIR/collect-logs.sh" <<'RADAR_COLLECT_EOF'
#!/usr/bin/env bash
# Собирает все журналы системы «Радар» в один архив.
#   bash collect-logs.sh            # архив в текущем каталоге
#   bash collect-logs.sh /tmp       # архив в указанном каталоге
set -Eeuo pipefail

APP_DIR="$(cd "$(dirname "$0")" && pwd)"
OUT_DIR="${1:-$APP_DIR}"
STAMP="$(date +%Y%m%d-%H%M%S)"
STAGE="$(mktemp -d)"
ARCHIVE="$OUT_DIR/radar-all-logs-$STAMP.tar.gz"

trap 'rm -rf "$STAGE"' EXIT

echo "Собираю журналы..."

mkdir -p "$STAGE/installer" "$STAGE/bot" "$STAGE/docker"
cp "$APP_DIR"/data/logs/installer_log_*.txt "$STAGE/installer/" 2>/dev/null || true
cp "$APP_DIR"/data/logs/bot.log* "$STAGE/bot/" 2>/dev/null || true

for container in radar_container radar_db; do
    if docker inspect "$container" >/dev/null 2>&1; then
        docker logs --tail 3000 "$container" > "$STAGE/docker/$container.log" 2>&1 || true
        # Без --format в снимок попадал Config.Env, а туда Compose кладёт
        # весь .env: токен бота, ключи ИИ и пароль базы уезжали в архив,
        # на котором ниже написано «секреты не попадают».
        {
            printf '{\n'
            printf '  "Image": %s,\n' "$(docker inspect --format '{{json .Config.Image}}' "$container" 2>/dev/null || echo null)"
            printf '  "Created": %s,\n' "$(docker inspect --format '{{json .Created}}' "$container" 2>/dev/null || echo null)"
            printf '  "RestartCount": %s,\n' "$(docker inspect --format '{{.RestartCount}}' "$container" 2>/dev/null || echo 0)"
            printf '  "State": %s,\n' "$(docker inspect --format '{{json .State}}' "$container" 2>/dev/null || echo null)"
            printf '  "Mounts": %s\n' "$(docker inspect --format '{{json .Mounts}}' "$container" 2>/dev/null || echo null)"
            printf '}\n'
        } > "$STAGE/docker/$container.inspect.json" 2>/dev/null || true
        echo "  + $container"
    fi
done

{
    echo "Система «Радар»"
    echo "Собрано: $(date '+%Y-%m-%d %H:%M:%S %Z')"
    echo "Хост: $(hostname) · $(uname -srm)"
    echo
    echo "--- контейнеры ---"
    docker ps -a --filter name=radar --format '{{.Names}}\t{{.Status}}\t{{.Image}}' 2>/dev/null || true
    echo
    echo "--- ресурсы ---"
    free -m 2>/dev/null | head -2 || true
    df -h "$APP_DIR" 2>/dev/null | tail -1 || true
    echo
    echo "--- настройки (без секретов) ---"
    grep -vE 'TOKEN|KEY|PASSWORD|SECRET' "$APP_DIR/.env" 2>/dev/null || true
} > "$STAGE/summary.txt"

tar -czf "$ARCHIVE" -C "$STAGE" .
echo "Готово: $ARCHIVE ($(du -h "$ARCHIVE" | cut -f1))"
echo "Секреты из .env в архив не попадают."
RADAR_COLLECT_EOF
# Скрипт восстановления кладётся рядом с установкой. Он нужен именно
# тогда, когда установщик может не работать, — значит должен лежать
# на машине заранее, а не скачиваться в момент аварии.
cat > "$APP_DIR/restore.sh" <<'RADAR_RESTORE_EOF'
#!/usr/bin/env bash
#
# Отдельный скрипт, а не флаг установщика. Причина в том, ради чего он
# существует: восстановление нужно тогда, когда установка сломана —
# а установщик в этот момент может не запускаться вовсе. Скрипт нарочно
# простой, без сборки образов и обращений к сети: распаковать, положить
# на место, поднять.
#
# Использование:
#   bash tools/restore.sh                     последняя копия
#   bash tools/restore.sh ФАЙЛ.tar.gz         конкретная
#   bash tools/restore.sh --list              что вообще есть
#
set -Eeuo pipefail

APP_DIR="${RADAR_HOME:-$HOME/radar_bot}"
BACKUPS="$APP_DIR/backups"

C_RESET=""; C_BOLD=""; C_DIM=""; C_GREEN=""; C_RED=""; C_YELLOW=""
if [ -t 1 ]; then
    C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_DIM=$'\033[2m'
    C_GREEN=$'\033[1;32m'; C_RED=$'\033[1;31m'; C_YELLOW=$'\033[1;33m'
fi

ok()   { printf "  %s✓%s %s\n" "$C_GREEN" "$C_RESET" "$*"; }
warn() { printf "  %s!%s %s\n" "$C_YELLOW" "$C_RESET" "$*"; }
die()  { printf "\n  %s✗ %s%s\n\n" "$C_RED" "$*" "$C_RESET" >&2; exit 1; }

listing() {
    find "$BACKUPS" -maxdepth 1 -name 'radar-backup-*.tar.gz' 2>/dev/null \
        | sort -r || true
}

if [ "${1:-}" = "--list" ]; then
    printf "\n  %sДоступные копии%s\n\n" "$C_BOLD" "$C_RESET"
    found=false
    while read -r item; do
        [ -n "$item" ] || continue
        found=true
        printf "    %s  %s%s%s\n" "$(basename "$item")" \
            "$C_DIM" "$(du -h "$item" | cut -f1)" "$C_RESET"
    done <<< "$(listing)"
    [ "$found" = true ] || printf "    копий нет\n"
    printf "\n"
    exit 0
fi

ARCHIVE="${1:-}"
if [ -z "$ARCHIVE" ]; then
    ARCHIVE="$(listing | head -1)"
    [ -n "$ARCHIVE" ] || die "Копий не найдено в $BACKUPS"
    printf "  Беру последнюю: %s\n" "$(basename "$ARCHIVE")"
fi
case "$ARCHIVE" in
    /*) : ;;
    *) [ -f "$ARCHIVE" ] || ARCHIVE="$BACKUPS/$ARCHIVE" ;;
esac
[ -f "$ARCHIVE" ] || die "Файл не найден: $ARCHIVE"

printf "\n  %sВосстановление «Радара»%s\n" "$C_BOLD" "$C_RESET"
printf "  Копия:    %s\n" "$(basename "$ARCHIVE")"
printf "  Каталог:  %s\n\n" "$APP_DIR"

# Подтверждение обязательно: восстановление затирает текущие данные,
# и человек, запустивший скрипт наугад, должен успеть остановиться.
if [ -t 0 ] || ( : < /dev/tty ) 2>/dev/null; then
    printf "  %sТекущие данные будут заменены. Продолжить? [д/Н]:%s " \
        "$C_YELLOW" "$C_RESET"
    answer=""
    read -r answer < /dev/tty || answer="n"
    case "$answer" in
        y|Y|д|Д|yes|да) : ;;
        *) die "Отменено" ;;
    esac
fi

STAGING="$(mktemp -d)"
trap 'rm -rf "$STAGING"' EXIT

tar -xzf "$ARCHIVE" -C "$STAGING" || die "Не удалось распаковать копию"
ok "Копия распакована"

if [ -f "$STAGING/manifest.txt" ]; then
    printf "\n  %sСодержимое копии%s\n" "$C_BOLD" "$C_RESET"
    sed 's/^/    /' "$STAGING/manifest.txt"
    printf "\n"
else
    warn "Манифеста нет — возможно, это не копия «Радара»"
fi

mkdir -p "$APP_DIR/data"

if [ -d "$APP_DIR" ] && command -v docker >/dev/null 2>&1; then
    (cd "$APP_DIR" && docker compose down 2>/dev/null) || true
    ok "Контейнеры остановлены"
fi

if [ -f "$STAGING/env.backup" ]; then
    cp "$STAGING/env.backup" "$APP_DIR/.env"
    chmod 600 "$APP_DIR/.env" 2>/dev/null || true
    # Владелец — пользователь контейнера: .env смонтирован внутрь,
    # и файл, оставшийся за root, бот перезаписать не сможет.
    chown 1000:1000 "$APP_DIR/.env" 2>/dev/null || true
    ok "Настройки восстановлены"
else
    warn "В копии нет .env — параметры придётся ввести заново"
fi

if [ -d "$STAGING/data" ]; then
    cp -r "$STAGING/data/." "$APP_DIR/data/" 2>/dev/null || true
    ok "Файлы данных восстановлены"
fi

if [ -f "$STAGING/database.sql" ]; then
    cp "$STAGING/database.sql" "$APP_DIR/data/restore-database.sql"
    warn "В копии дамп PostgreSQL — залейте его после запуска:"
    printf "    docker exec -i radar_db psql -U radar radar < %s\n" \
        "$APP_DIR/data/restore-database.sql"
fi

printf "\n"
ok "Восстановление завершено"
printf "\n  Дальше:\n"
printf "    cd %s && docker compose up -d\n" "$APP_DIR"
printf "    затем проверьте целостность в боте: Управление → Копии\n\n"
RADAR_RESTORE_EOF
chmod +x "$APP_DIR/restore.sh" 2>/dev/null || true

# Скрипт получения сертификата — тоже рядом с установкой: он нужен
# на самой машине, где домен и порты, а не на машине разработчика.
cat > "$APP_DIR/tls.sh" <<'RADAR_TLS_EOF'
#!/usr/bin/env bash
#
# Получает сертификат и поднимает перед панелью Caddy, который сам держит
# его в актуальном состоянии.
#
# Почему Caddy, а не certbot с nginx: Caddy получает и продлевает
# сертификат сам, без cron и хуков. Для машины, за которой никто
# не следит ежедневно, это важнее гибкости — забытое продление ломает
# панель ровно через три месяца, когда о нём уже никто не помнит.
#
# ГЛАВНОЕ ОГРАНИЧЕНИЕ, о котором нужно знать заранее: проверка владения
# доменом идёт ИЗВНЕ на порты 80 и 443. Если роутер их не пробрасывает
# или провайдер режет — выдача не пройдёт, и никакие настройки здесь
# не помогут. Скрипт проверяет это до обращения к Let's Encrypt,
# чтобы не тратить попытки: у них лимит пять неудач в час на домен.
#
set -Eeuo pipefail

APP_DIR="${RADAR_HOME:-$HOME/radar_bot}"
DOMAIN="${1:-}"
EMAIL="${2:-}"

C_RESET=""; C_BOLD=""; C_DIM=""; C_GREEN=""; C_RED=""; C_YELLOW=""
if [ -t 1 ]; then
    C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_DIM=$'\033[2m'
    C_GREEN=$'\033[1;32m'; C_RED=$'\033[1;31m'; C_YELLOW=$'\033[1;33m'
fi
ok()   { printf "  %s✓%s %s\n" "$C_GREEN" "$C_RESET" "$*"; }
info() { printf "  %s→%s %s\n" "$C_DIM" "$C_RESET" "$*"; }
warn() { printf "  %s!%s %s\n" "$C_YELLOW" "$C_RESET" "$*"; }
die()  { printf "\n  %s✗ %s%s\n\n" "$C_RED" "$*" "$C_RESET" >&2; exit 1; }

if [ -z "$DOMAIN" ]; then
    cat <<'USAGE'

  Сертификат для веб-панели «Радара»

  Использование:
    bash tls.sh домен [почта]

  Например:
    bash tls.sh radar.example.ru admin@example.ru

  Что нужно заранее:
    1. Домен указывает A-записью на внешний адрес этого сервера.
    2. Порты 80 и 443 проброшены на сервер снаружи.
       Проверка владения доменом идёт именно снаружи — без проброса
       сертификат не выдадут, сколько ни пробуй.

USAGE
    exit 0
fi

printf "\n  %sСертификат для %s%s\n\n" "$C_BOLD" "$DOMAIN" "$C_RESET"

command -v docker >/dev/null 2>&1 || die "Docker не установлен"
[ -d "$APP_DIR" ] || die "Установка не найдена в $APP_DIR"

# --- проверки до обращения к Let's Encrypt --------------------------------
#
# У них лимит: пять неудачных попыток на домен в час. Поэтому всё, что
# можно проверить самим, проверяем заранее.

info "Проверяю, куда указывает домен"
resolved="$(getent hosts "$DOMAIN" 2>/dev/null | awk '{print $1}' | head -1 || true)"
external="$(curl -fsS --max-time 8 https://api.ipify.org 2>/dev/null || true)"

if [ -z "$resolved" ]; then
    die "Домен $DOMAIN не разрешается в адрес — проверьте A-запись"
fi
ok "Домен указывает на $resolved"

if [ -n "$external" ] && [ "$resolved" != "$external" ]; then
    warn "Внешний адрес сервера — $external, а домен указывает на $resolved"
    warn "Если между ними нет проброса, проверка владения не пройдёт"
fi

info "Проверяю, свободен ли порт 80"
if command -v ss >/dev/null 2>&1 && ss -ltn 2>/dev/null | grep -q ':80 '; then
    die "Порт 80 занят. Освободите его: проверка Let's Encrypt идёт на него"
fi
ok "Порт 80 свободен"

WEB_PORT="$(grep -E '^WEB_PORT=' "$APP_DIR/.env" 2>/dev/null | cut -d= -f2- || true)"
: "${WEB_PORT:=8080}"

# --- Caddy ----------------------------------------------------------------

mkdir -p "$APP_DIR/tls"
cat > "$APP_DIR/tls/Caddyfile" <<CADDY
$DOMAIN {
    reverse_proxy radar:$WEB_PORT
    encode gzip
}
CADDY
ok "Настройки Caddy записаны"

cat > "$APP_DIR/tls/docker-compose.tls.yml" <<COMPOSE
services:
  caddy:
    image: caddy:2-alpine
    container_name: radar_tls
    restart: unless-stopped
    ports:
      - "80:80"
      - "443:443"
    volumes:
      - ./tls/Caddyfile:/etc/caddy/Caddyfile:ro
      - caddy_data:/data
      - caddy_config:/config
    networks:
      - default

volumes:
  caddy_data:
  caddy_config:
COMPOSE
ok "Описание контейнера готово"

info "Поднимаю Caddy — сертификат запросится автоматически"
cd "$APP_DIR"
if ! docker compose -f docker-compose.yml -f tls/docker-compose.tls.yml up -d caddy; then
    die "Caddy не запустился — смотрите docker logs radar_tls"
fi

printf "\n"
info "Жду выдачу сертификата (обычно до минуты)"
issued=false
for _ in $(seq 1 30); do
    if docker logs radar_tls 2>&1 | grep -q "certificate obtained successfully"; then
        issued=true
        break
    fi
    sleep 4
done

if [ "$issued" = true ]; then
    ok "Сертификат получен"
    printf "\n  Панель доступна: %shttps://%s%s\n" "$C_BOLD" "$DOMAIN" "$C_RESET"
    printf "  Короткие ссылки: %shttps://%s/s/КОД%s\n\n" "$C_BOLD" "$DOMAIN" "$C_RESET"
    printf "  Не забудьте задать в боте:\n"
    printf "    SHORT_BASE_URL = https://%s\n\n" "$DOMAIN"
else
    warn "Сертификат пока не выдан. Обычная причина — порты 80 и 443"
    warn "не проброшены снаружи. Посмотрите: docker logs radar_tls"
    printf "\n"
fi
RADAR_TLS_EOF
chmod +x "$APP_DIR/tls.sh" 2>/dev/null || true
chmod +x "$APP_DIR/collect-logs.sh"
ok "Сборщик журналов: $APP_DIR/collect-logs.sh"
ok "Восстановление из копии: $APP_DIR/restore.sh"
ok "Сертификат для панели: $APP_DIR/tls.sh домен"

# --------------------------------------------------------------------------
#  Шаг 6. Настройки
# --------------------------------------------------------------------------

step "$(t step_settings)"

ask() { # ask <подсказка> <переменная> <regexp> <обязательно yes|no>
    local prompt="$1" varname="$2" pattern="$3" required="$4" value=""
    while true; do
        read -r -p "$prompt" value < /dev/tty || true
        value="$(printf '%s' "$value" | tr -d '\r' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
        if [ -z "$value" ] && [ "$required" = "no" ]; then break; fi
        if [ -z "$value" ]; then warn "Значение не может быть пустым."; continue; fi
        if [ -n "$pattern" ] && ! printf '%s' "$value" | grep -Eq "$pattern"; then
            warn "Формат не распознан, проверьте значение."; continue
        fi
        break
    done
    printf -v "$varname" '%s' "$value"
}

if [ -f .env ] && [ "$RECREATE_ENV" = false ]; then
    info "Файл .env уже существует"
    read -r -p "  $(t env_reuse_ask) " reply < /dev/tty || true
    case "${reply:-y}" in
        [Nn]*) RECREATE_ENV=true ;;
        *) ok "Использую существующий .env" ;;
    esac
else
    RECREATE_ENV=true
fi

if [ "$RECREATE_ENV" = true ]; then
    echo
    printf "  %sЗаполните параметры (Ctrl+C — выход)%s\n" "$C_DIM" "$C_RESET"
    ask "  Токен Telegram-бота (@BotFather): " IN_TOKEN '^[0-9]{6,}:[A-Za-z0-9_-]{30,}$' yes
    ask "  Ваш Telegram ID (@userinfobot): " IN_ADMIN '^[0-9]{5,}$' yes
    ask "  Ключ Google Gemini (Enter — без ИИ): " IN_GEMINI '^.{20,}$' no
    # Символ $ недопустим: Docker Compose раскроет его как переменную
    ask "  Пароль базы данных (Enter — сгенерировать): " IN_DBPASS '^[^$]{8,}$' no
    if [ -z "${IN_DBPASS:-}" ]; then
        IN_DBPASS="$(head -c 32 /dev/urandom | base64 | tr -d '/+=$' | head -c 24)"
        echo "  Сгенерирован пароль базы: $IN_DBPASS"
    fi
    ask "  Часовой пояс [Europe/Saratov]: " IN_TZ '^[A-Za-z]+/[A-Za-z_+-]+$' no
    ask "  Город по умолчанию [Саратов]: " IN_CITY '.+' no
    echo "  Наборы источников: saratov, moscow, spb, kazan, samara (через запятую)"
    ask "  Какие подключить [saratov]: " IN_PRESET '^[a-z, ]+$' no
    : "${IN_TZ:=Europe/Saratov}"
    : "${IN_CITY:=Саратов}"
    : "${IN_PRESET:=saratov}"

    umask 077
    cat > .env <<ENVEOF
BOT_TOKEN=${IN_TOKEN}
SUPERADMIN_ID=${IN_ADMIN}
GEMINI_API_KEY=${IN_GEMINI:-}
DB_PASSWORD=${IN_DBPASS}
DB_HOST=postgres
DB_PORT=5432
DB_NAME=radar
DB_USER=radar
DB_POOL_SIZE=5
DB_MAX_OVERFLOW=5
EVENT_RETENTION_DAYS=180
MAX_BOT_TOKEN=
MAX_API_URL=https://platform-api2.max.ru
MAX_MODE=polling
GEMINI_MODEL=gemini-3.6-flash
GEMINI_MODEL_ANALYSIS=gemini-3.5-flash-lite
AI_CONCURRENCY=2
AI_TIMEOUT=90
AI_RPM=10
AI_RPD=250
AI_RESERVE=40
AI_BATCH_SIZE=8
AI_COOLDOWN=900
AI_PREFILTER=1
AI_SEARCH=1
TZ=${IN_TZ}
DEFAULT_CITY=${IN_CITY}
SOURCE_CITIES=${IN_PRESET}
POLL_INTERVAL=180
MSG_PER_SOURCE=5
CLUSTER_RADIUS_M=1000
MAX_LOCATIONS=0
EXTRA_CHANNELS=
EXTRA_RSS=
LOG_LEVEL=INFO
LOG_DIR=data/logs
LOG_KEEP_DAYS=14
LOG_MAX_MB=5
PROMO_ENABLED=1
PROMO_TITLE=🐙 HydraSite
PROMO_URL=https://t.me/+WWJFBZVhxBs4ZmNi
PROMO_IN_ALERTS=0
ENVEOF
    umask 022
    chmod 600 .env
    ok "Файл .env создан (права 600)"
    if [ -z "${IN_GEMINI:-}" ]; then
        warn "Ключ Gemini не задан: ассистент отключён, анализ пойдёт по ключевым словам"
    fi
fi

# С 4.8.4.2 .env смонтирован в контейнер, поэтому владельцем должен быть
# пользователь образа (uid 1000), а не root: иначе бот не прочитает ключи
# и не запишет новые из раздела настроек. Делается и при обновлении:
# на установках прежних версий .env остался за root.
env_fix_perms

# --- обслуживание базы данных ---------------------------------------------
# Отдельная копия только базы: она нужна чаще полной и восстанавливается
# быстрее. Полная копия проекта делается выше, при выборе способа установки.
database_menu() {
    local backend db_file
    backend="$(get_env_value DB_BACKEND)"
    : "${backend:=sqlite}"
    db_file="$APP_DIR/data/radar.db"

    local has_db=false
    if [ "$backend" = "sqlite" ] && [ -f "$db_file" ]; then has_db=true; fi
    if [ "$backend" = "postgres" ] && [ -d "$APP_DIR/data/postgres" ]; then has_db=true; fi

    local snapshots
    # Без `|| echo 0`: при pipefail неудачный ls делает весь конвейер
    # ненулевым, срабатывает запасная ветка — и к нулю от wc добавляется
    # второй ноль. На экране это выглядело как «доступно: 0 0)».
    snapshots="$(find "$APP_DIR/backups" -maxdepth 1 -name 'db-*.tar.gz' \
        2>/dev/null | wc -l)" || true
    snapshots="${snapshots//[!0-9]/}"
    : "${snapshots:=0}"

    if [ "$has_db" != true ] && [ "$snapshots" -eq 0 ]; then
        return 0
    fi

    echo
    printf "  %s%s%s\n\n" "$C_BOLD" "$(t dbmaint_title)" "$C_RESET"
    printf "    1) %s\n" "$(t dbmaint_nothing)"
    printf "    2) %s\n" "$(t dbmaint_backup)"
    printf "    3) %s\n" "$(t dbmaint_recreate)"
    printf "    4) %s%s %s)%s\n" \
        "$(t dbmaint_restore)" "$C_DIM" "$snapshots" "$C_RESET"
    printf "  %s [1]: " "$(t action_choice)"

    local answer=""
    read -r answer < /dev/tty || answer="1"
    : "${answer:=1}"
    log_raw "Обслуживание базы: вариант $answer"

    case "$answer" in
        2) backup_database ;;
        3)
            backup_database || { warn "Копия не создана — база не тронута"; return 0; }
            info "Удаляю базу"
            (cd "$APP_DIR" && run $COMPOSE down) || true
            rm -f "$db_file" "$db_file-wal" "$db_file-shm" 2>/dev/null || true
            rm -rf "$APP_DIR/data/postgres" 2>/dev/null || true
            ok "База удалена, будет создана заново при запуске"
            ;;
        4) restore_database ;;
        *) : ;;
    esac
    return 0
}

backup_database() {
    local stamp archive backend
    backend="$(get_env_value DB_BACKEND)"
    : "${backend:=sqlite}"
    stamp="$(date +%Y%m%d-%H%M%S)"
    mkdir -p "$APP_DIR/backups"
    archive="$APP_DIR/backups/db-${backend}-${stamp}.tar.gz"

    spinner_start "копирую базу данных…"
    local ok_flag=false
    if [ "$backend" = "postgres" ]; then
        if docker ps --format '{{.Names}}' 2>/dev/null | grep -q '^radar_db$'; then
            local dump="$APP_DIR/backups/.dump-$stamp.sql"
            if docker exec radar_db pg_dump -U radar radar > "$dump" 2>>"$LOG_FILE"; then
                tar -czf "$archive" -C "$APP_DIR/backups" "$(basename "$dump")" 2>>"$LOG_FILE"
                rm -f "$dump"
                ok_flag=true
            fi
        else
            # Контейнер не поднят — копируем сам том
            tar -czf "$archive" -C "$APP_DIR/data" postgres 2>>"$LOG_FILE" && ok_flag=true
        fi
    else
        if [ -f "$APP_DIR/data/radar.db" ]; then
            tar -czf "$archive" -C "$APP_DIR/data" radar.db 2>>"$LOG_FILE" && ok_flag=true
        fi
    fi
    spinner_stop

    if [ "$ok_flag" = true ] && [ -f "$archive" ]; then
        ok "Копия базы: $(basename "$archive") ($(du -h "$archive" | cut -f1))"
        ls -1t "$APP_DIR/backups"/db-*.tar.gz 2>/dev/null | tail -n +11 | xargs -r rm -f || true
        return 0
    fi
    rm -f "$archive" 2>/dev/null || true
    warn "Копию базы создать не удалось"
    return 1
}

restore_database() {
    local archives count choice archive
    mapfile -t archives < <(ls -1t "$APP_DIR/backups"/db-*.tar.gz 2>/dev/null || true)
    count=${#archives[@]}
    if [ "$count" -eq 0 ]; then
        warn "Копий базы не найдено"
        return 1
    fi

    echo
    printf "  %sДоступные копии:%s\n" "$C_BOLD" "$C_RESET"
    local index=1
    for item in "${archives[@]}"; do
        printf "    %d) %s  %s%s%s\n" "$index" "$(basename "$item")" \
            "$C_DIM" "$(du -h "$item" | cut -f1)" "$C_RESET"
        index=$((index + 1))
    done
    printf "  Выбор [1]: "
    read -r choice < /dev/tty || choice="1"
    : "${choice:=1}"

    if ! printf '%s' "$choice" | grep -qE '^[0-9]+$' || [ "$choice" -lt 1 ] ||
       [ "$choice" -gt "$count" ]; then
        warn "Неверный выбор — восстановление отменено"
        return 1
    fi
    archive="${archives[$((choice - 1))]}"

    warn "Текущая база будет заменена содержимым копии"
    printf "  Продолжить? (y/N): "
    local confirm=""
    read -r confirm < /dev/tty || confirm="n"
    case "${confirm:-n}" in [Yy]*) : ;; *) info "Восстановление отменено"; return 1 ;; esac

    (cd "$APP_DIR" && run $COMPOSE down) || true
    spinner_start "восстанавливаю базу…"
    local restored=false
    if tar -tzf "$archive" 2>/dev/null | grep -q '\.sql$'; then
        # Дамп PostgreSQL: распаковываем, зальётся при первом старте вручную
        tar -xzf "$archive" -C "$APP_DIR/backups" 2>>"$LOG_FILE" && restored=true
        spinner_stop
        ok "Дамп распакован в $APP_DIR/backups"
        info "Залейте его после запуска:"
        info "  docker exec -i radar_db psql -U radar radar < <файл>.sql"
        return 0
    fi
    tar -xzf "$archive" -C "$APP_DIR/data" 2>>"$LOG_FILE" && restored=true
    spinner_stop

    if [ "$restored" = true ]; then
        ok "База восстановлена из $(basename "$archive")"
        return 0
    fi
    warn "Восстановить не удалось — подробности в журнале"
    return 1
}

# Базу выбираем всегда: и при новом .env, и при использовании существующего.
# Раньше выбор молча наследовался из старого файла, где строки DB_BACKEND
# могло не быть вовсе — пользователь о базе даже не знал.
choose_database
database_menu

TZ_VALUE="$(grep -E '^TZ=' .env | cut -d= -f2- || true)"
: "${TZ_VALUE:=Europe/Saratov}"

# --------------------------------------------------------------------------
#  Шаг 7. Сборка и запуск
# --------------------------------------------------------------------------

step "$(t step_build)"

# Номер группы docker с этой машины. Сокет принадлежит root:docker с правами
# 660, а бот работает под uid 1000: без совпадающего номера группы обновление
# из панели упирается в «Permission denied» на /var/run/docker.sock. Значение
# у каждой системы своё, поэтому берём его здесь, а не зашиваем в compose.
DOCKER_GID_VALUE="$(getent group docker 2>/dev/null | cut -d: -f3)"
if [ -n "$DOCKER_GID_VALUE" ]; then
    set_env_value DOCKER_GID "$DOCKER_GID_VALUE"
else
    warn "Группа docker не найдена — обновление из панели будет недоступно"
fi

# Настройки PostgreSQL под память машины (ROADMAP 4.8, п.2; с 4.9.9.3).
# Раньше параметры были зашиты под 1–2 ГБ, и на машине помощнее база
# работала вполсилы, а на совсем слабой — впритык. Подбор осторожный:
# * только при DB_BACKEND=postgres — SQLite эти значения не читает;
# * только если их не задали руками — ручная настройка важнее расчёта;
# * shared_buffers не выше четверти лимита контейнера базы (512 МБ
#   в compose): иначе база упрётся в свой же лимит и её убьёт ядро;
# * значения по умолчанию в compose прежние — без этих строк в .env
#   база запускается ровно так же, как до 4.9.9.3.
pg_tune() {
    local mem_kb mem_mb shared cache work maint
    grep -qE '^DB_BACKEND=postgres' .env 2>/dev/null || return 0
    if grep -qE '^PG_SHARED_BUFFERS=' .env 2>/dev/null; then
        info "Настройки PostgreSQL заданы вручную — подбор пропущен"
        return 0
    fi
    mem_kb="$(awk '/^MemTotal:/ {print $2}' /proc/meminfo 2>/dev/null)"
    [ -n "$mem_kb" ] || return 0
    mem_mb=$((mem_kb / 1024))

    shared=$((mem_mb / 8))
    [ "$shared" -lt 64 ] && shared=64
    [ "$shared" -gt 128 ] && shared=128

    cache=$((mem_mb / 2))
    [ "$cache" -lt 192 ] && cache=192
    [ "$cache" -gt 2048 ] && cache=2048

    work=4
    [ "$mem_mb" -ge 2048 ] && work=8

    maint=$((mem_mb / 32))
    [ "$maint" -lt 32 ] && maint=32
    [ "$maint" -gt 256 ] && maint=256

    set_env_value PG_SHARED_BUFFERS "${shared}MB"
    set_env_value PG_EFFECTIVE_CACHE "${cache}MB"
    set_env_value PG_WORK_MEM "${work}MB"
    set_env_value PG_MAINTENANCE_MEM "${maint}MB"
    info "PostgreSQL под память ${mem_mb} МБ: shared_buffers ${shared}MB, кэш ${cache}MB"
}
pg_tune


TZ_VALUE="$(grep -E '^TZ=' .env | cut -d= -f2- || true)"
: "${TZ_VALUE:=Europe/Saratov}"
info "Часовой пояс: $TZ_VALUE"

# Пароль с символом $ ломает подстановку переменных в Docker Compose
if grep -qE '^DB_PASSWORD=.*\$' .env 2>/dev/null; then
    die_or_rollback "DB_PASSWORD содержит символ \$ — Compose примет его за переменную. Смените пароль в .env"
fi

info "Останавливаю прежние контейнеры"
run $COMPOSE down --remove-orphans || true
run docker rm -f "$CONTAINER_NAME" || true   # наследие версий 3.x

info "Собираю образ (первый раз это занимает 5–15 минут)"
spinner_start "сборка образа…"
if ! run_slow "Сборка образа" $COMPOSE build $NO_CACHE_FLAG; then
    spinner_stop
    trap - ERR
    fail "Сборка образа не удалась"
    offer_rollback "сборка образа" || true
    printf "  Полный журнал: %s\n\n" "$LOG_FILE"
    exit 1
fi
spinner_stop "Образ собран"

# PostgreSQL запоминает пароль при инициализации тома. Если .env изменился,
# а том остался прежним, бот будет молча биться в отказ авторизации.
# Проверка нужна только когда PostgreSQL действительно выбран: иначе она
# зря поднимала контейнер базы при работе на SQLite.
if [ "$(get_env_value DB_BACKEND)" = "postgres" ] &&
   [ -d "$APP_DIR/data/postgres" ] &&
   [ -n "$(ls -A "$APP_DIR/data/postgres" 2>/dev/null)" ]; then
    info "Проверяю пароль существующей базы"
    run_slow "Запуск PostgreSQL" $COMPOSE up -d postgres \
        || die_or_rollback "Не удалось запустить PostgreSQL"

    for _ in $(seq 1 45); do
        docker exec radar_db pg_isready -U radar >/dev/null 2>&1 && break
        sleep 2
    done

    ENV_DB_PASS="$(grep -E '^DB_PASSWORD=' .env | cut -d= -f2- || true)"
    ENV_DB_USER="$(grep -E '^DB_USER=' .env | cut -d= -f2- || echo radar)"
    ENV_DB_NAME="$(grep -E '^DB_NAME=' .env | cut -d= -f2- || echo radar)"
    : "${ENV_DB_USER:=radar}"
    : "${ENV_DB_NAME:=radar}"

    if docker exec -e PGPASSWORD="$ENV_DB_PASS" radar_db \
        psql -U "$ENV_DB_USER" -d "$ENV_DB_NAME" -c 'SELECT 1' >/dev/null 2>&1; then
        ok "Пароль базы совпадает"
    else
        warn "База не принимает пароль из .env"
        info "PostgreSQL задаёт пароль только при первой инициализации тома,"
        info "поэтому правка .env на уже созданную базу ничего не меняет."

        HAS_DATA=false
        if docker exec radar_db psql -U postgres -d "$ENV_DB_NAME" -tAc \
            "SELECT count(*) FROM users" 2>/dev/null | grep -qE '^[1-9]'; then
            HAS_DATA=true
        fi

        echo
        if [ "$HAS_DATA" = true ]; then
            warn "В базе есть данные пользователей — пересоздание их удалит!"
            printf "  Рекомендуется вернуть прежний пароль в .env, а не пересоздавать базу.\n"
        elif [ -f "$APP_DIR/data/db.json" ]; then
            info "Данные версии 3.x лежат в data/db.json — после пересоздания перенесутся заново"
        else
            info "Пользовательских данных в базе не найдено"
        fi

        printf "  %sПересоздать базу с новым паролем?%s (y/N): " "$C_BOLD" "$C_RESET"
        read -r recreate_db < /dev/tty || recreate_db="n"

        case "${recreate_db:-n}" in
            [Yy]*)
                info "Останавливаю контейнеры и пересоздаю том базы"
                run $COMPOSE down || true
                BACKUP_DIR="$APP_DIR/data/postgres.bak-$(date +%Y%m%d-%H%M%S)"
                mv "$APP_DIR/data/postgres" "$BACKUP_DIR"
                ok "Прежний том сохранён: $BACKUP_DIR"
                mkdir -p "$APP_DIR/data/postgres"
                chown -R 999:999 "$APP_DIR/data/postgres" 2>/dev/null || true
                ;;
            *)
                die_or_rollback "Верните прежний пароль в .env и запустите установщик заново"
                ;;
        esac
    fi
fi

# Профиль postgres поднимается только если выбран PostgreSQL
: "${DB_BACKEND_VALUE:=$(get_env_value DB_BACKEND)}"
: "${DB_BACKEND_VALUE:=sqlite}"
COMPOSE_ARGS=""
if [ "$DB_BACKEND_VALUE" = "postgres" ]; then
    COMPOSE_ARGS="--profile postgres"
    info "База данных: PostgreSQL (отдельный контейнер)"
    mkdir -p "$APP_DIR/data/postgres"
    chown -R 999:999 "$APP_DIR/data/postgres" 2>/dev/null || true
    run_slow "Запуск PostgreSQL" $COMPOSE $COMPOSE_ARGS up -d postgres \
        || die_or_rollback "Не удалось запустить PostgreSQL"
    for _ in $(seq 1 45); do
        docker exec radar_db pg_isready -U radar >/dev/null 2>&1 && break
        sleep 2
    done

    # Заливка дампа при переезде. Делается до старта бота: иначе он создаст
    # пустую схему, и дамп ляжет поверх наполовину — часть таблиц из копии,
    # часть новых. Логика общая с откатом — см. load_pg_dump.
    if [ -n "$MIGRATION_DUMP" ] && [ -f "$MIGRATION_DUMP" ]; then
        if load_pg_dump "$MIGRATION_DUMP"; then
            MIGRATION_DUMP="$MIGRATION_DUMP.applied"
        else
            warn "Система поднимется с пустой базой; данные остались в копии"
        fi
    fi
else
    info "База данных: SQLite (файл data/radar.db, отдельный контейнер не нужен)"
    if [ -n "$MIGRATION_DUMP" ] && [ -f "$MIGRATION_DUMP" ]; then
        # Дамп pg_dump в SQLite не заливается: это разные диалекты SQL.
        # Молча продолжить нельзя — человек решит, что данные переехали.
        warn "В копии дамп PostgreSQL, а выбрана SQLite — залить нельзя"
        warn "Выберите PostgreSQL при установке либо переносите файл data/radar.db"
    fi
fi

# Перенос данных при смене базы (5.9). Обе базы должны быть доступны
# одновременно, поэтому PostgreSQL поднимается и тогда, когда уходят С него;
# бот на это время остановлен — источник не должен меняться посреди копии.
# Цель заменяется целиком: в томе PostgreSQL или файле SQLite могли остаться
# данные прошлого выбора, и смешивать их с переносимыми нельзя. Прежний
# файл SQLite перед заменой сохраняется рядом.
if [ -n "${DB_TRANSFER_FROM:-}" ] && [ "$DB_TRANSFER_FROM" != "$DB_BACKEND_VALUE" ]; then
    info "$(t db_transfer_run) $DB_TRANSFER_FROM → $DB_BACKEND_VALUE"
    (cd "$APP_DIR" && run $COMPOSE stop radar) || true
    TRANSFER_ARGS="$COMPOSE_ARGS"
    if [ "$DB_BACKEND_VALUE" = "sqlite" ]; then
        TRANSFER_ARGS="$COMPOSE_ARGS --profile postgres"
        run_slow "Запуск PostgreSQL для переноса" $COMPOSE $TRANSFER_ARGS up -d postgres \
            || warn "PostgreSQL не поднялся — перенос не выйдет"
        for _ in $(seq 1 45); do
            docker exec radar_db pg_isready -U radar >/dev/null 2>&1 && break
            sleep 2
        done
        if [ -f "$APP_DIR/data/radar.db" ]; then
            SQLITE_KEEP="$APP_DIR/data/radar.db.bak-$(date +%Y%m%d-%H%M%S)"
            mv "$APP_DIR/data/radar.db" "$SQLITE_KEEP"
            rm -f "$APP_DIR/data/radar.db-wal" "$APP_DIR/data/radar.db-shm"
            info "Прежний файл SQLite сохранён: $(basename "$SQLITE_KEEP")"
        fi
    fi
    TRANSFER_CODE=0
    (cd "$APP_DIR" && run $COMPOSE $TRANSFER_ARGS run --rm --no-deps radar \
        python -m radar.cli db copy --from "$DB_TRANSFER_FROM" --to "$DB_BACKEND_VALUE" \
        --replace --yes) || TRANSFER_CODE=$?
    if [ "$TRANSFER_CODE" -eq 0 ]; then
        ok "$(t db_transfer_done)"
    else
        warn "$(t db_transfer_failed)"
        if [ -n "${SQLITE_KEEP:-}" ] && [ -f "$SQLITE_KEEP" ]; then
            mv -f "$SQLITE_KEEP" "$APP_DIR/data/radar.db"
            info "Файл SQLite возвращён на место"
        fi
        die_or_rollback "Данные не перенесены — прежняя база не тронута, выберите её снова"
    fi
    if [ "$DB_BACKEND_VALUE" = "sqlite" ]; then
        (cd "$APP_DIR" && run $COMPOSE $TRANSFER_ARGS stop postgres) || true
    fi
fi

# Профиль media поднимает собственный Bot API Server: он снимает предел
# отправки с 50 МБ до 2 ГБ, но требует ключей с my.telegram.org.
ask_bot_api_server

MEDIA_VALUE="$(get_env_value MEDIA_ENABLED)"
if [ "$MEDIA_VALUE" = "1" ]; then
    API_ID_VALUE="$(get_env_value TELEGRAM_API_ID)"
    API_HASH_VALUE="$(get_env_value TELEGRAM_API_HASH)"
    if [ -n "$API_ID_VALUE" ] && [ -n "$API_HASH_VALUE" ]; then
        COMPOSE_ARGS="$COMPOSE_ARGS --profile media"
        info "Загрузка видео: свой Bot API Server (файлы до 2 ГБ)"
        mkdir -p "$APP_DIR/data/bot-api"
    else
        warn "MEDIA_ENABLED=1, но TELEGRAM_API_ID или TELEGRAM_API_HASH не заданы"
        info "Загрузка видео будет работать с пределом 50 МБ"
        info "Ключи берутся на my.telegram.org → API development tools"
    fi
fi

# Профиль rustdesk поднимает hbbs/hbbr — свой релей удалённого доступа.
# Образ при отсутствии подтягивается штатным поведением `docker compose
# up` (pull-if-missing): в отличие от docker:cli в radar/updater.py,
# здесь контейнер создаётся через compose, а не напрямую через Engine API,
# явный docker pull не нужен.
ask_rustdesk

if [ "$(get_env_value RUSTDESK_ENABLED)" = "1" ]; then
    COMPOSE_ARGS="$COMPOSE_ARGS --profile rustdesk"
    info "RustDesk: контейнеры hbbs/hbbr поднимутся вместе с ботом"
fi

# --------------------------------------------------------------------------
#  Шаг 8. Диагностика до запуска
# --------------------------------------------------------------------------

step "$(t step_diagnose)"

info "Запускаю диагностику внутри контейнера"
DOCTOR_OUT="$APP_DIR/.doctor-out.txt"
# Ловушка bash: обработчик ERR срабатывает при ненулевом коде даже когда
# errexit выключен через `set +e`. Единственный надёжный способ получить код
# без обрыва — конструкция `команда || переменная=$?`: она входит в список
# с ||, а для таких команд ERR не вызывается.
DOCTOR_CODE=0
# Читаем вывод построчно: метки ##STAGE дают шкалу и название текущего теста,
# остальное копится в файл и показывается после завершения.
: > "$DOCTOR_OUT"
{
    $COMPOSE $COMPOSE_ARGS run --rm --no-deps radar python -m radar.doctor --stream \
        2>&1 || echo "##CODE $?"
} | while IFS= read -r dline; do
        case "$dline" in
            "##STAGE "*)
                set -- $dline
                progress "$2" "$3" "$(printf '%s ' "${@:4}" | sed 's/ $//')"
                ;;
            "##CODE "*)
                printf '%s\n' "${dline#\#\#CODE }" > "$APP_DIR/.doctor-code"
                ;;
            *)
                printf '%s\n' "$dline" >> "$DOCTOR_OUT"
                ;;
        esac
    done

if [ -f "$APP_DIR/.doctor-code" ]; then
    DOCTOR_CODE="$(cat "$APP_DIR/.doctor-code")"
    rm -f "$APP_DIR/.doctor-code"
fi
progress_done

cat "$DOCTOR_OUT" >> "$LOG_FILE" 2>/dev/null || true

# Показываем результат построчно, сохраняя пометки диагностики
while IFS= read -r dline; do
    case "$dline" in
        *"✓ "*) printf "  %s\n" "$dline" ;;
        *"! "*) printf "  %s%s%s\n" "$C_YELLOW" "$dline" "$C_RESET" ;;
        *"✗ "*) printf "  %s%s%s\n" "$C_RED" "$dline" "$C_RESET" ;;
        *"→ "*) printf "  %s%s%s\n" "$C_DIM" "$dline" "$C_RESET" ;;
        *) [ -n "$dline" ] && printf "  %s\n" "$dline" ;;
    esac
done < "$DOCTOR_OUT"

rm -f "$DOCTOR_OUT"

if [ "$DOCTOR_CODE" -eq 1 ]; then
    echo
    fail "Диагностика нашла ошибки — бот не запущен"
    trap - ERR
    offer_rollback "диагностика не пройдена" || true
    printf "  Полный отчёт с трассировками: %s\n\n" "$LOG_FILE"
    exit 1
elif [ "$DOCTOR_CODE" -eq 2 ]; then
    warn "Есть предупреждения, но запуск возможен"
else
    ok "Диагностика пройдена без замечаний"
fi

# --------------------------------------------------------------------------
#  Шаг 9. Запуск
# --------------------------------------------------------------------------

step "$(t step_start)"

run_slow "Запуск контейнеров" $COMPOSE $COMPOSE_ARGS up -d \
    || die_or_rollback "Не удалось запустить контейнеры"

# Сразу за запуском: Caddy удалён предыдущим `down --remove-orphans`,
# и без него панель недоступна снаружи вообще.
ensure_tls_running

# Первый запуск включает миграции Alembic, перенос данных и геокодирование —
# на слабом железе это занимает минуты, а не секунды.
info "Жду запуска бота (первый запуск — до 10 минут)"

BOT_OK=false
BOT_DEAD=false
LAST_STAGE=""
WAIT_LIMIT=300      # циклов по 2 секунды

for tick in $(seq 1 "$WAIT_LIMIT"); do
    state="$(docker inspect -f '{{.State.Status}}' "$CONTAINER_NAME" 2>/dev/null || echo нет)"
    snapshot="$(docker logs "$CONTAINER_NAME" 2>&1 || true)"

    # Показываем этапы по мере прохождения, чтобы ожидание не было немым
    for stage in "База загружена:загрузка данных" \
                 "Схема базы актуальна:схема базы готова" \
                 "Перенос завершён:данные перенесены" \
                 "Адреса дозаполнены:адреса уточнены" \
                 "Run polling:подключение к Telegram"; do
        marker="${stage%%:*}"
        title="${stage#*:}"
        if printf '%s' "$snapshot" | grep -q "$marker"; then
            if [ "$LAST_STAGE" != "$title" ]; then
                LAST_STAGE="$title"
                info "· $title"
            fi
        fi
    done

    if printf '%s' "$snapshot" | grep -q "Run polling"; then
        BOT_OK=true
        break
    fi

    if [ "$state" = "exited" ] || [ "$state" = "dead" ]; then
        BOT_DEAD=true
        break
    fi

    # Фатальные причины: ждать дальше бессмысленно
    if printf '%s' "$snapshot" | grep -qi "отклонил подключение\|Unauthorized\|Ошибка конфигурации"; then
        BOT_DEAD=true
        break
    fi

    # Полоса показывает пройденные этапы, а не абстрактное время
    STAGES_DONE=0
    for marker in "База загружена" "Схема базы" "Перенос завершён" "Run polling"; do
        printf '%s' "$snapshot" | grep -q "$marker" && STAGES_DONE=$((STAGES_DONE + 1))
    done
    progress "$STAGES_DONE" 4 "${LAST_STAGE:-запуск}"

    sleep 2
done
progress_done

log_raw "--- лог бота после запуска ---"
docker logs --tail 120 "$CONTAINER_NAME" >> "$LOG_FILE" 2>&1 || true

ok "Бот вышел в рабочий режим"

# Что удалось разобрать из лога — полезно видеть сразу
MIGRATED=$(docker logs "$CONTAINER_NAME" 2>&1 | grep -oP 'пользователей \K\d+' | head -1 || true)
[ -n "$MIGRATED" ] && ok "Перенесено пользователей: $MIGRATED"
docker logs "$CONTAINER_NAME" 2>&1 | grep -q "Схема базы актуальна" && ok "Схема базы актуальна"

# --- проверка целостности после переезда ----------------------------------
#
# Восстановление, которое не пересчитали, считается непроверенным. После
# переезда сверяем, что данные действительно доехали: пустая база при
# успешном старте выглядит точно так же, как полная, и человек узнает
# о потере, только когда кто-то пожалуется на пропавшие оповещения.
if [ "$RESTORED" = true ]; then
    step "$(t step_integrity)"
    if $COMPOSE $COMPOSE_ARGS run --rm --no-deps radar python - <<'RADAR_CHECK_EOF' 2>>"$LOG_FILE"
import asyncio


async def main() -> int:
    from radar.db import engine, repo

    await engine.ensure_schema()
    users = await repo.count_users()
    locations = await repo.count_locations()
    sources = await repo.count_sources()

    print(f"Пользователей: {users}")
    print(f"Локаций: {locations}")
    print(f"Источников: {sources}")

    if users == 0:
        print("ВНИМАНИЕ: пользователей ноль — данные не доехали")
        return 1
    return 0


raise SystemExit(asyncio.run(main()))
RADAR_CHECK_EOF
    then
        ok "$(t integrity_ok)"
    else
        warn "$(t integrity_failed)"
        warn "$(t integrity_hint)"
    fi
fi

trap - ERR
ELAPSED=$(( $(date +%s) - START_TS ))
echo
timing_report
echo
line
printf "  %s✓ Система «Радар» v%s запущена%s   %s(%d мин %d с)%s\n" \
    "$C_GREEN" "$VERSION" "$C_RESET" "$C_DIM" $((ELAPSED / 60)) $((ELAPSED % 60)) "$C_RESET"
line
echo
printf "  %sДальше:%s\n" "$C_BOLD" "$C_RESET"
printf "    Откройте бота в Telegram → /start → пришлите геопозицию\n"
echo
printf "  %sУправление:%s\n" "$C_BOLD" "$C_RESET"
printf "    Логи бота     docker logs -f %s\n" "$CONTAINER_NAME"
if [ "${DB_BACKEND_VALUE:-sqlite}" = "postgres" ]; then
    printf "    Логи базы     docker logs -f radar_db\n"
else
    printf "    %sБаза — файл data/radar.db, отдельного контейнера нет%s\n" \
        "$C_DIM" "$C_RESET"
fi
printf "    Перезапуск    cd %s && %s restart\n" "$APP_DIR" "$COMPOSE"
printf "    Остановка     cd %s && %s down\n" "$APP_DIR" "$COMPOSE"
printf "    Все журналы   bash %s/collect-logs.sh\n" "$APP_DIR"
printf "    Журналы в боте  /logs · /logtail · /logclear %s(суперадминистратор)%s\n" "$C_DIM" "$C_RESET"
echo
printf "  %sЖурнал установки: %s%s\n" "$C_DIM" "$LOG_FILE" "$C_RESET"
echo
log_raw "=== УСТАНОВКА ЗАВЕРШЕНА УСПЕШНО за ${ELAPSED} с ==="

# --------------------------------------------------------------------------
#  Публикация панели наружу (с 4.7.5.1)
# --------------------------------------------------------------------------
#
# Раньше сертификат получали отдельным скриптом, о котором надо было знать.
# Теперь установщик сам спрашивает — и сам доводит настройку до конца:
# получить сертификат мало, нужно ещё прописать адрес в сократитель ссылок
# и завести соль, иначе короткие ссылки останутся выключенными и человек
# не поймёт, почему.

setup_shortener() {   # setup_shortener <домен>
    local domain="$1"

    # Соль разводит коды разных экземпляров. Генерируем, если её нет,
    # и НИКОГДА не трогаем существующую: смена соли меняет все коды,
    # и уже разосланные ссылки перестают открываться.
    local salt
    salt="$(get_env_value SHORT_SALT)"
    if [ -z "$salt" ]; then
        salt="$(head -c 18 /dev/urandom | base64 | tr -dc 'a-zA-Z0-9' | head -c 24)"
        set_env_value SHORT_SALT "$salt"
        ok "$(t tls_salt_created)"
    else
        info "$(t tls_salt_kept)"
    fi

    set_env_value SHORT_BASE_URL "https://$domain"
    ok "$(t tls_short_url): https://$domain"
}

offer_tls() {
    set +e
    ( : < /dev/tty ) 2>/dev/null || return 0

    local existing=""
    if tls_certificate_present; then
        existing="$(configured_domain || true)"
        if [ -n "$existing" ]; then
            ok "$(t tls_found): $existing"
            # Наличие сертификата не значит, что его кто-то отдаёт.
            ensure_tls_running
            # Сертификат уже есть — остаётся убедиться, что короткие
            # ссылки о нём знают. Это отдельный шаг, и его легко забыть.
            local current
            current="$(get_env_value SHORT_BASE_URL)"
            if [ -z "$current" ]; then
                info "$(t tls_short_missing)"
                setup_shortener "$existing"
            elif [ "$current" != "https://$existing" ]; then
                # Раньше здесь стояла молчаливая перезапись, и адрес,
                # исправленный администратором, возвращался к домену
                # из Caddyfile при КАЖДОМ обновлении. Настройку,
                # сделанную руками, установщик не отменяет — только
                # показывает расхождение.
                warn "$(t tls_short_differs)"
                printf "      .env: %s\n" "$current"
                printf "      Caddyfile: https://%s\n" "$existing"
            fi
            return 0
        fi
        info "$(t tls_found_no_domain)"
    fi

    printf "\n  %s%s%s " "${C_DIM:-}" "$(t tls_ask)" "${C_RESET:-}"
    local answer=""
    if ! read -r answer < /dev/tty; then
        printf "\n"
        return 0
    fi
    printf "\n"
    case "$answer" in
        y|Y|д|Д|yes|да|YES|ДА) : ;;
        *) return 0 ;;
    esac

    printf "  %s " "$(t tls_domain_ask)"
    local domain=""
    read -r domain < /dev/tty || domain=""
    domain="$(printf '%s' "$domain" | tr -d ' \t\r')"
    printf "\n"

    if [ -z "$domain" ]; then
        warn "$(t tls_domain_empty)"
        return 0
    fi
    case "$domain" in
        *.*) : ;;
        *) warn "$(t tls_domain_bad) $domain"; return 0 ;;
    esac

    if [ ! -x "$APP_DIR/tls.sh" ]; then
        warn "$(t tls_script_missing)"
        return 0
    fi

    if RADAR_HOME="$APP_DIR" bash "$APP_DIR/tls.sh" "$domain"; then
        setup_shortener "$domain"

        # Панель теперь за HTTPS, и cookie сессии обязана уходить только
        # по нему. Раньше флаг нигде не выставлялся: сертификат был,
        # а кука ходила без Secure — при первом заходе на http её видно.
        set_env_value WEB_HTTPS 1

        # Домен для входа в панель привязывается у BotFather, а не здесь.
        # Без этого шага виджет Telegram пишет «Bot domain invalid»,
        # и по этой надписи догадаться, что делать, невозможно.
        line
        printf "  %s%s%s\n\n" "${C_BOLD:-}" "$(t tls_botfather_title)" "${C_RESET:-}"
        printf "    1. %s @BotFather\n" "$(t tls_botfather_open)"
        printf "    2. /setdomain\n"
        printf "    3. %s\n" "$(t tls_botfather_pick)"
        printf "    4. %s %shttps://%s%s\n\n" "$(t tls_botfather_send)" \
            "${C_CYAN:-}" "$domain" "${C_RESET:-}"
        printf "  %s\n" "$(t tls_botfather_note)"
        line

        info "$(t tls_restart_hint)"
    else
        warn "$(t tls_failed)"
    fi
    return 0
}

if [ "$MIGRATE_OUT" != true ]; then
    offer_tls
fi

# Предложение переехать. Спрашиваем в конце, а не в начале: до установки
# человек ещё не знает, работает ли новая версия, и решать про переезд рано.
#
# Всё тело — в функции с выключенным `set -e`. К этому месту ловушка ERR
# уже снята, и при включённом errexit любая осечка (недоступный внешний
# адрес, занятый порт) обрывала скрипт МОЛЧА: на экране оставался ответ
# «Y» и приглашение оболочки, без единого слова о причине. Молчание здесь
# хуже ошибки — человек считает, что переезд состоялся.
offer_migration() {
    set +e

    printf "  %s%s%s " "${C_DIM:-}" "$(t migrate_ask)" "${C_RESET:-}"
    local answer=""
    # Без таймаута: на экране вопрос уже напечатан, и оборвать его через
    # минуту — значит показать вопрос и не дать ответить. Ровно это
    # и происходило: строка появлялась, тут же возвращалось приглашение.
    # Если терминала нет, сюда мы не дойдём — проверка выше.
    if ! read -r answer < /dev/tty; then
        printf "\n"
        return 0
    fi
    printf "\n"

    case "$answer" in
        y|Y|д|Д|yes|да|YES|ДА) : ;;
        *) return 0 ;;
    esac

    # Способ передачи копии спрашивается и здесь: переезд предложен
    # в конце установки, но выбирать способ человек должен сам.
    local mode="link"
    if ( : < /dev/tty ) 2>/dev/null; then
        mode="$(ask_migration_mode)"
    fi

    local port="${MIGRATE_PORT:-8899}"
    local minutes="${MIGRATE_MINUTES:-30}"
    SERVE_TOKEN=""

    if [ -z "${BACKUP_PATH:-}" ] || [ ! -f "${BACKUP_PATH:-}" ]; then
        info "$(t migrate_making_copy)"
        if ! make_backup "переезд"; then
            warn "$(t migrate_backup_failed)"
            return 0
        fi
    fi

    if [ ! -f "${BACKUP_PATH:-}" ]; then
        warn "$(t migrate_backup_failed)"
        return 0
    fi
    ok "$(t migrate_copy_ready): $(basename "$BACKUP_PATH")"

    if [ "$mode" = "manual" ]; then
        print_manual_migration
        log_raw "MIGRATE ручной перенос, копия: $BACKUP_PATH"
        return 0
    fi

    kill_stale_serve

    # Порт может быть занят чужим процессом: молча промахнуться мимо
    # этого нельзя, ссылка тогда просто не откроется. Своя прошлая
    # раздача уже погашена выше.
    if command -v ss >/dev/null 2>&1 && ss -ltn 2>/dev/null | grep -q ":$port "; then
        warn "$(t migrate_port_busy) $port"
        print_manual_migration
        return 0
    fi

    local serve_file="$BACKUP_PATH" serve_bundle=false
    if build_migration_bundle "$BACKUP_PATH"; then
        serve_file="$MIGRATION_BUNDLE"
        serve_bundle=true
        ok "$(t migrate_bundle_ok)"
    fi

    if ! serve_migration "$serve_file" "$port" "$minutes"; then
        warn "$(t migrate_serve_failed)"
        print_manual_migration
        return 0
    fi

    local address link
    address="$(detect_address)"
    link="http://$address:$port/$SERVE_TOKEN"

    line
    printf "  %s%s%s\n\n" "${C_BOLD:-}" "$(t migrate_ready)" "${C_RESET:-}"
    # Про лимит ядра на длину аргумента и самодостаточный пакет —
    # см. комментарий у раздачи в --migrate: качаем в файл,
    # запускаем файлом.
    if [ "$serve_bundle" = true ]; then
        printf "  %s%s%s\n" "${C_CYAN:-}" \
            "curl -fsSLo radar-restore.sh $link" "${C_RESET:-}"
        printf "  %s%s%s\n\n" "${C_CYAN:-}" \
            "sudo bash radar-restore.sh" "${C_RESET:-}"
    else
        printf "  %s%s%s\n" "${C_CYAN:-}" \
            "curl -fsSLo radar-install.sh $INSTALLER_URL" "${C_RESET:-}"
        printf "  %s%s%s\n\n" "${C_CYAN:-}" \
            "sudo bash radar-install.sh --restore-url=$link" "${C_RESET:-}"
    fi
    line
    printf "  %s\n" "$(t migrate_note_once)"
    printf "  %s\n" "$(t migrate_note_time "$minutes")"
    printf "  %s\n" "$(t migrate_note_port "$port")"
    printf "  %s\n" "$(t migrate_note_nat "$port")"
    printf "  %s\n\n" "$(t migrate_note_secret)"
    printf "  %s\n" "$(t migrate_note_stop)"
    printf "    cd %s && docker compose down\n\n" "$APP_DIR"
    log_raw "MIGRATE ссылка выдана, порт $port, срок $minutes мин, пакет: $serve_bundle"
    wait_for_download "$SERVE_PID" "$minutes" || print_manual_migration
    cleanup_migration_files
    return 0
}

if ( : < /dev/tty ) 2>/dev/null && [ "$MIGRATE_OUT" != true ]; then
    offer_migration
fi

if [ "$SHOW_LOGS" = true ]; then
    docker logs -f "$CONTAINER_NAME"
fi

}   # конец radar_installer_main

# Единственная исполняемая пара строк файла. Если скачивание оборвалось,
# до неё дело не дойдёт — bash упадёт на разборе незакрытой функции.
# exit обязателен: у пакета переезда позади этих строк лежит бинарная
# копия, и без явного выхода bash взялся бы разбирать её как команды.
radar_installer_main "$@"
exit $?
